typedef long long lli;

bool check(vector<int> v) {
    lli sum = 0;

    for(int i : v)
        sum += i;

    for(int i : v) {
        if(__gcd(lli(i), sum - i) <= 1) {
            cout << i << " --- " << sum - i << endl;
            return false;
        }
    }

    return true;
}

bool used[50000];

int main() {
    int n, m, k;

//    cout << check({3, 9, 26, 30, 34});

    cin >> n;

    if(n == 3) {
        cout << "2 5 63\n";
    } else if(n == 4) {
        cout << "2 5 20 63\n";
    } else {
        m = n % 5;
        n -= m;
        k = n / 5;

        for(int i = 0; i < m; i++) {
            used[6 + i * 6] = true;
            cout << 6 + i * 6 << " ";
        }

        int cnt = 0, base = 3;

        for(int i = 0; i < 2 * k; i++) {
            if(used[base + i * 3]) {
                base += 3;
            }

            if(cnt < 1500) {
                if((base + i * 3) % 2 == 0) {
                    cnt++;
                    base += 3;
                }
            }

            used[base + i * 3] = true;
            cout << base + i * 3 << " ";
        }

        base = 26;

        for(int i = 0; i < 3 * k; i++) {
            if(used[i]) {
                base += 2;
            }

            cout << base + i * 2 << " ";
        }


        cout << endl;
    }

    return 0;
}

