int six(int x, int y) {
	return 6 * x + y;
}
int main() {
	int n;
	cin >> n;
	if (n == 3) {
		cout << 2 <<" "<< 3<<" " << 25 << endl;
	}
	else if (n == 4) {
		cout << 2 << " " << 5 << " " << 20 << " " << 63 << endl;
	}
	else {
		cout << 2 << " " << 3 << " " << 4 << " " << 6 << " ";
		int last = 6;
		int cnt = 15;
		for (int i = 1; (i+1)*4 < n; i=i+1) {
			cout << six(i, 2) << " " << six(i, 3) << " " << six(i, 4) <<" " << six(i, 6) << " ";
			n -= 4;
			last+=6;
			cnt += 1;
		}
		if (n == 2) {
			cout << last + 3 << " ";
			cnt += 1;
		}
		else if (n == 3) {
			cout << last + 2 << " " << last + 4 << " ";
		}
		else if (n == 4) {
			cout << last + 2 << " " << last + 3 << " " << last + 4 << " ";
			cnt += 1;
		}
		if (cnt % 2 == 1) {
			cout << last + 9 << endl;
		}
		else {
			cout << last + 6 << endl;
		}
	}
}

