int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    if (n == 3)
    {
        cout << 2 << " " << 5 << " " << 63 << endl;
        return 0;
    }

    V res{2, 4, 3, 9};

    n -= 4;
    int n_ = n - (n % 2);

    for (int i = 8; i + 2 <= 30000; i += 6)
    {
        if (!n_)
            break;
        n_ -= 2;
        res.push_back(i);
        res.push_back(i + 2);
    }

    for (int i = 15; i + 6 <= 30000; i += 12)
    {
        if (!n_)
            break;
        n_ -= 2;
        res.push_back(i);
        res.push_back(i + 6);
    }

    for (int i = 6; i <= 30000; i += 6)
    {
        if (!n_)
            break;
        n_--;
        res.push_back(i);
    }

    if (n % 2)
        res.push_back(30000);

    for (int i = 0; i < res.size(); i++)
        cout << res[i] << (i == res.size() - 1 ? "\n" : " ");

