}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
  int n;
  cin >> n;
  if(n==3) {
    cout << 2 << " " << 5 << " " << 63 << endl;
    return 0;
  }
  vector<ll> v[2];
  for(int i=2; i<=30000; i++) {
    if(i%2==0) v[0].push_back(i);
    else if(i%3==0) v[1].push_back(i);
  }
  for(int k=1; k<=v[1].size(); k++) {
    if(n-k>v[0].size()) continue;
    ll d=v[1][0],sum=d;
    for(int i=1; i<k; i++) {
      d=__gcd(d,v[1][i]);
      sum+=v[1][i];
    }
    for(int i=0; i<n-k; i++) {
      d=__gcd(d,v[0][i]);
      sum+=v[0][i];
    }
    for(int i=0; i<k; i++) {
      if(__gcd(sum-v[1][i],v[1][i])==1) goto next;
    }
    for(int i=0; i<n-k; i++) {
      if(__gcd(sum-v[0][i],v[0][i])==1) goto next;
    }
    if(d==1) {
      vector<int> a;
      for(int i=0; i<k; i++) a.push_back(v[1][i]);
      for(int i=0; i<n-k; i++) a.push_back(v[0][i]);
      for(int i=0; i<a.size(); i++) {
        if(i) cout << " ";
        cout << a[i];
      }
      cout << endl;
      return 0;
    }
    next:;
  }
  return 0;
}

#include <iostream>
