#define REP(i, n) for (int i = 0; i < (n); ++i)
#define SIZE(a) ((int)(a).size())
#define ALL(a) (a).begin(), (a).end()

int n;
vector<int> a;

int gcd(int a, int b) {
	while (a && b) {
		if (a > b) a %= b; else b %= a;
	}
	return a + b;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> n;
	int m = n;

	if (n == 3) {
		cout << "2 5 63\n";
		return 0;
	}

	vector<int> a, b, c;

	for (int i = 1; i <= 30000; ++i) {
		if (i % 6 == 0) {
			c.push_back(i);
			continue;
		}
		if (i % 2 == 0) {
			a.push_back(i);
		}
		if (i % 3 == 0) {
			b.push_back(i);
		}
	}

	//cout << "2: " << SIZE(a) << endl;
	//cout << "3: " << SIZE(b) << endl;
	//cout << "6: " << SIZE(c) << endl;

	reverse(ALL(a));
	reverse(ALL(b));
	reverse(ALL(c));

	vector<int> result;

	if (n > 15000) {	
		while (n >= 2 && SIZE(a) >= 2) {
			result.push_back(a.back()); a.pop_back();
			result.push_back(a.back()); a.pop_back();
			n -= 2;
		}

		while (n >= 2 && SIZE(b) >= 2) {
			result.push_back(b.back()); b.pop_back();
			result.push_back(b.back()); b.pop_back();
			n -= 2;
		}
	} else {
		while (n >= 4 && SIZE(a) >= 2 && SIZE(b) >= 2) {
			result.push_back(a.back()); a.pop_back();
			result.push_back(a.back()); a.pop_back();
			result.push_back(b.back()); b.pop_back();
			result.push_back(b.back()); b.pop_back();
			n -= 4;
		}
	}

	REP(i, min(n, SIZE(c))) result.push_back(c[i]);

	assert(SIZE(result) == m);
	int sum = 0;
	REP(i, SIZE(result)) sum += result[i];
	int g = 0;
	REP(i, SIZE(result)) {
		assert(gcd(sum-result[i], result[i]) > 1);
		g = gcd(g, result[i]);
	}
	assert(g == 1);

	for (auto& e : result) {
		cout << e << ' ';
	}
	cout << '\n';

	return 0;
}

