int main() {
	int N; cin >> N;

	for (int i = 2; i < 30001; i++) {
		bool flag = true;
		for (int j = 2; j*j <= i; j++) {
			if (i%j == 0) {
				flag = false;
				break;
			}
		}
		if (flag)primes.push_back(i);
	}

