using namespace std;

int gcd(int a, int b) {
	if (a == 0 || b == 0) {
		return 0;
	}
	if (a == b) {
		return a;
	}
	if (a > b) {
		return gcd(a-b, b);
	}
	return gcd(a, b-a);
}

bool check(vector<int> v) {
	int sum = 0, all = v[0];
	for (int i : v) {
		sum+= i;
		all = gcd(all, i);
	}
	if (all != 1) {
		return 0;
	}
	for (int i : v) {
		if (gcd(i, sum - i) == 1) {
			return 0;
		}
	}
	return 1;
}

