	ans.insert(3);

	n -= 2;

	for (int i = 4; i <= 30000; i++) {
		if ( i % 2 == 0 ) {
			if (i % 3 == 1)
				Four.push_back(i);
			else if ( i % 3 == 2 ){ 
				Two.push_back(i);
			}
			else if ( i % 3 == 0 ) {
				Zero.push_back(i);
			}
		}
		else if ( i % 3 == 0){
			Three.push_back(i);
		}
	}

