	else {

		//same count of %3 == 1,2,0

		ans.insert(Three.back());
		Three.pop_back();
		n--;

		ans.insert(Four.back());
		Four.pop_back();
		n--;

		// now MOD 3 = 0
		// and sum is odd

		while (n >= 2 and Three.size() >= 2) {
			ans.insert(Three.back());
			Three.pop_back();
			ans.insert(Three.back());
			Three.pop_back();
			n-=2;
