			ans.insert(Four.back());
			ans.insert(Two.back());
			Four.pop_back();
			Two.pop_back();
			n -= 2;
		}

		while(n >= 1) {
			ans.insert(Zero.back());
			Zero.pop_back();
			n--;
		}

	}
	/*
