	}
	else if(N == 4){
		ans.push_back(2), ans.push_back(5), ans.push_back(63), ans.push_back(20);
	}
	else if(N == 6){
		ans.push_back(2), ans.push_back(4), ans.push_back(6), 
		ans.push_back(3), ans.push_back(9), ans.push_back(12);
	}
	else if(N >= 15000){
		for(int i = 2; i <= 30000; i += 2) if(i % 6) ans.push_back(i);
		for(int i = 3; i <= 30000; i += 3) if(i % 6) ans.push_back(i);
		for(int i = 1; i <= N - 15000; i++) ans.push_back(i*6);
	}
	else{
		int X = N/5*3, Y = N/5*2;
		if(N%5 == 2) Y += 2;
		if(N%5 == 3) X += 3;
		if(N%5 == 4) Y += 4;
		if(N%5 == 1){
			X -= 3;
			Y -= 2;
			Y += 6;
		}
		int cnt = 0;
		for(int i = 2; i <= 30000; i += 2){
			if(i % 6){
				ans.push_back(i);
				cnt++;
			}
			if(cnt >= X) break;
		}
		cnt = 0;
		for(int i = 3; i <= 30000; i += 3){
			if(i % 6){
				ans.push_back(i);
				cnt++;
			}
			if(cnt >= Y) break;
		}
		for(int i = 6; i <= 30000; i += 6){
			if(ans.size() >= N) break;
			ans.push_back(i);
		}
	}

