set<int> setOfEvens(int x) {
	set<int> ans;
	for (int i = 1; i <= x; ++i) {
		ans.insert(2*i);
	}
	return ans;
}

set<int> answer(int n) {
	if (n == 3) {
		set<int> ans = {2, 5, 63};
		return ans;
	} else if (n == 19999 || n == 19997) {
		set<int> ans = answer(n+1);
		ans.erase(6);
		return ans;
	} else if (n < 15002) {
		if (n % 3 == 2 || n % 3 == 1) {
			set<int> ans = setOfEvens(n-2);
			ans.insert(3);
			ans.insert(9);
			return ans;
		} else {
			set<int> ans = setOfEvens(n-4);
			ans.insert(3);
			ans.insert(9);
			ans.insert(15);
			ans.insert(21);
			return ans;
		}
	} else {
		set<int> ans = setOfEvens((n%2 == 0 ? 15000 : 14997));
		int stillNeeded = n - 15000;
		for (int extra = 3; stillNeeded > 0; extra += 6, --stillNeeded) {
			ans.insert(extra);
		}
		return ans;
	}
}

