    for (int i = 2; i <= MAX_V; i++)
    {
        if (i % 2 == 0 || i % 3 == 0)
        {
            if (i % 6 == 0)
            {
                A.push(i);
            }
            else if (i % 2 == 0)
            {
                B.push(i);
            }
            else if (i % 3 == 0)
            {
                C.push(i);
            }
        }
    }
    vector<int> results;
    int sum = 0;
    while (results.size() < N)
    {
        int a = A.front();
        int b = B.front();
        int c = C.front();
        if (a < b and a < c)
        {
            results.push_back(a);
            A.pop();
            sum += a;
        }
        if (b < a and b < c)
        {
            results.push_back(b);
            B.pop();
            sum += b;
        }
        if (c < a and c < b)
        {
            results.push_back(c);
            C.pop();
            sum += c;
        }
    }
    if (sum % 6 == 2)
    {
        for (int i = 0; i < N; i++)
        {
            if (results[i] == 8)
            {
                results[i] = C.front();
                break;
            }
        }
    }
    else if (sum % 6 == 3)
    {
        for (int i = 0; i < N; i++)
        {
            if (results[i] == 9)
            {
                int c = C.front();
                C.pop();
                while (c % 6 != 4)
                {
                    c = C.front();
                    C.pop();
                }
                results[i] = c;
                break;
            }
        }
    }
    else if (sum % 6 == 5)
    {
        for (int i = 0; i < N; i++)
        {
            if (results[i] == 9)
            {
                results[i] = C.front();
                break;
            }
        }
    }
    for (int i = 0; i < N; i++)
    {
        cout << results[i] << " ";
    }
    cout << endl;
    return 0;
}

