  if (cnto % 2 == 1) {
    for (int i = N - 1; i >= 0; i--) {
      if (ans[i] % 2 == 1) {
        int tmp = ans[i] + 1;
        while (se.find(tmp) != se.end()) tmp += 2;
        ans[i] = tmp;
        se.insert(tmp);
        cnte += tmp / 2;
        break;
      }
    }
  }

  if (cnte % 3 == 1) {
    for (int i = N - 1; i >= 0; i--) {
      if (ans[i] % 2 == 0) {
        int tmp = ans[i] + 4;
        while (se.find(tmp) != se.end()) tmp += 6;
        ans[i] = tmp;
        break;
      }
    }
  }

  for (int i = 0; i < N; i++) {
    cout << ans[i] << " ";
  }
  cout << endl;
}

