    int to = (1 << sz(b));
    for(int i = 0; i < to; ++i)
    {
        if(popc(i) != n || (i & msk) != msk)
        {
            continue;
        }

        vector<int> v;
        for(int j = 0; j < sz(b); ++j)
        {
            if((i >> j) & 1)
            {
                v.push_back(b[j]);
            }
        }

        if(accumulate(all(v), 0) % md == 0)
        {
            return v;
        }
    }

    assert(false);
    return{};
}

