    rep(i, n - 1) prs(ans[i]);

    ll num = ans[n - 2] + 1;
    while (true){
        bool c1 = (tot + num) % 6 == 0;
        bool c2 = gcd(tot, num) != 1;
        if (c1 && c2) {ans.pb(num); break;}
        num++; 
    }
    assert(num <= 30000);
    prl(ans[n - 1]);
}

