void solve() {
	for(int i = 2; i <= 30000; i++) {
		if(!pr[i]) {
			primes.push_back(i);
			for(int j = 2 * i; j <= 30000; j += i) {
				pr[j] = 1;
			}
		}
	}
	int n;
	cin >> n;
	for(int i = 1; i <= 30000; i++) {
		if(i % 6 == 0) {
			v3.push_back(i);
		}
		else if(i % 3 == 0) {
			v2.push_back(i);
		}
		else if(i % 2 == 0) {
			v1.push_back(i);
		}
	}
	if(n == 3) {
		cout << "2 5 63" << endl;
	}
	else if(n == 4) {
		cout << "2 5 20 63" << endl;
	}
	else {
		for(int i = 1; i <= 3333; i++) {
			for(int j = 1; j <= 2500; j++) {
				if(n - 3 * i - 2 * j >= 0 && n - 3 * i - 2 * j <= 5000) {
					gen(i, j, n - 3 * i - 2 * j);
					for(int i = 1; i <= n; i++) {
						cout << a[i] << " ";
					}
					return;
				}
			}
		}
		// n = 20000
		for(int i = 1; i <= n; i++) {
			if(!v1.empty()) {
				a[i] = v1.back();
				v1.pop_back();
			}
			else if(!v2.empty()) {
				a[i] = v2.back();
				v2.pop_back();
			}
			else {
				a[i] = v3.back();
				v3.pop_back();
			}
		}
		sort(a + 1, a + n + 1);
		ll s = 0;
		for(int i = 1; i <= n; i++) {
			s += a[i];
		}
		bool found = 0;
		for(int i = 1; i <= n; i++) {
			if(!found)
			for(int p : primes) {
				if(p <= 3) continue;
				ll ss = s + p - a[i];
				if(ss % (6 * p) == 0) {
					a[i] = p;
					found = 1;
