set<int> eratosthenes(int n){
  set<int> st;
  st.insert(2);
  for(int i = 3; i<=n ;i+=2) st.insert(i);
  for(auto it = st.begin(); it != st.end(); ++it){
    auto it2 = it;
    ++it2;
    for(; it2 != st.end(); ++it2){
      if((*it2)%(*it)==0){
        auto it3 = it2;
        --it3;
        st.erase(it2);
        it2 = it3;
      }
    }
  }
  return st;
}

