    } else if (i % 2 == 0) {
      div2.push_back(i);
    } else if (i % 3 == 0) {
      div3.push_back(i);
    }
  }
  vi32 ans;
  if (n % 2 == 1) {
    ans.push_back(div6[0]);
    n--;
  }
  ans.push_back(div3[0]);
  ans.push_back(div3[1]);
  n -= 2;
  rep(i, min(n, (int) div2.size())) {
    ans.push_back(div2[i]);
  }
  n = max(n - (int) div2.size(), 0);
  repi(i, 2, min(n + 2, (int) div3.size())) {
    ans.push_back(div3[i]);
  }
  n = max(n - (int) div3.size() + 2, 0);
  rep(i, n) {
    if (ans[0] == div6[i]) continue;
    ans.push_back(div6[i]);
  }
