ll C[100][100];

ll binomic(int n, int r){
	if(C[n][r]!=0) return C[n][r];
	if(n==r || r==0) return 1;
	return C[n][r] = binomic(n-1,r-1)+binomic(n-1,r);
}

int buscar(int A[],int l, int r, int dato){
	if(l>r) return -1;
	int mid = (l+r)/2;
	if(A[mid]==dato) return mid;
	if(A[mid]>dato) return buscar(A,l,mid-1,dato);
	return buscar(A,mid+1,r,dato);
}

bool isPossibleSum(int sum,int n,int A[]){
	if(n==0 && sum!=0) return false;
	if(sum==0) return true;
	if(A[n-1]>sum) return isPossibleSum(sum,n-1,A);
	return isPossibleSum(sum-A[n-1],n-1,A) || isPossibleSum(sum,n-1,A);
}


char P[100005];

int solve(int n){
	if(n==0) return 1;
	if(n%2==0 || P[n]!=P[n/2]) return 1+solve(n-1);
	int i=n/2;
	while(P[i]==P[i+n/2+1] && i!=-1)i--;
	if(i==-1) return 1 + solve(n/2);
	return n/2-i + solve(n/2+i+1);
}
