bool judge(vector<int> v){
	bool ans = true;
	int sum = 0;
	for (int x : v) sum += x;

	for (int i = 0; i < v.size(); ++i) {
		int ai = v[i];
		int sumi = sum - ai;
		int gcdi = __gcd(ai, sumi);
		if (gcdi==1){
			ans = false;
			break;
		}
	}
	int gcd_all = __gcd(v[0], v[1]);
	for (int x : v) gcd_all = __gcd(gcd_all, x);
	if (gcd_all!=1) ans = false;

	sort(v.begin(), v.end());
	for (int i = 0; i < v.size()-1; ++i) {
		if (v[i]==v[i+1]) ans = false;
	}

	return ans;
}


