        end = sz(a) - 1;
    for (ll i = begin; i <= end; i++) {
        cout << a[i] << " ";
    }
    cout << endl;
}

void solve() {
    ll n;
    cin >> n;
    if (n == 3) {
        cout << "2 5 63";
        return;
    }

    bool wasodd = false;
    v res;
    if (n & 1) {
        wasodd = true;
        res.push_back(3e4);
        n--;
    }

    res.push_back(5);
    res.push_back(25);
    ll lim = wasodd ? 3e4 - 10 : 3e4;

    n -= 2;
    ll base = 2;
    while (base < 3e4) {
        res.push_back(base);
        res.push_back(base + 6);
        n -= 2;
        if (n == 0)goto end;
        base += 10;
    }
    base = 4;
    while (base < 3e4) {
        res.push_back(base);
        res.push_back(base + 2);
        n -= 2;
        if (n == 0)goto end;
        base += 10;
    }
    base = 10;
    while (base < lim) {
        res.push_back(base);
        res.push_back(base + 10);
        n -= 2;
        if (n == 0)goto end;
        base += 20;
    }

    base = 3;
    while (true) {
        res.push_back(base);
        res.push_back(3e4 - base);
        n -= 2;
        if (n == 0)goto end;
        base += 6;
    }

    end:
    pa(res);
}

