void solve() {
	ll N;
	cin >> N;

	if (N == 3) {
		cout << "2 5 63" << endl;
		return;
	}

	vll result(0);

	vll three(0);
	reps(i, 3, 30000) {
		if (i % 3 == 0 && i % 2 > 0) {
			three.push_back(i);
		}
	}

	//偶数を最低2個、奇数はN-2個を最大として偶数でめいっぱい、残りを偶数
	ll odd = min((ll)three.size(), ((N - 2) / 2) * 2);
	ll even = N - odd;

	rep(i, odd) {
		result.push_back(three[i]);
	}

	if (even % 3 == 0 || even % 3 == 2) {
		//2,4,6,...でOK
		reps(i, 1, even) {
			result.push_back(i * 2);
		}
	}
	else {
		//2,4,6,...だが、最後の一個(%3=2)は飛ばして、30000(%3=0)を選ぶ
		reps(i, 1, even - 1) {
			result.push_back(i * 2);
		}
		result.push_back(30000);
	}

	rep(i, (ll)result.size()) {
		cout << result[i];
		if (i < (ll)result.size() - 1) {
			cout << " ";
		}
	}
	cout << endl;
