ll binpow(ll a, ll b)
{
    ll res = 1;
    while (b > 0)
    {
        if (b & 1) res = (res * a);
        a = (a * a);
        b >>= 1;
    }
    return res;
}

ll result[1000010];
ll tempo[1000010];
ll per[1000010];


void permutation_exp(ll n,ll x)
{
  fr(o,1,n)
  {
    result[o]=o;
  }

  while(x>0)
  {
    if(x&1)
    {
      fr(o,1,n)
      {
        tempo[o]=result[o];
      }

      fr(o,1,n)
      {
        result[o]=tempo[per[o]];
      }
    }

    fr(o,1,n)
    {
      tempo[o]=per[o];
    }

    fr(o,1,n)
    {
      per[o]=tempo[tempo[o]];
    }
    x>>=1;
  }
}


ll modpow(ll a, ll b,ll x)
{
    ll res = 1;
    while (b > 0)
    {
        if (b & 1) res = (res * a)%x;
        a = (a * a)%x;
        b >>= 1;
    }
    return res;
}

int modInverse(int a, int m)
{
    int m0 = m;
    int y = 0, x = 1;
    if (m == 1)
      return 0;
    while (a > 1)
    {
        // q is quotient
        int q = a / m;
        int t = m;
        // m is remainder now, process same as
        // Euclid's algo
        m = a % m, a = t;
        t = y;
        // Update y and x
        y = x - q * y;
        x = t;
    }
    // Make x positive
    if (x < 0)
       x += m0;
    return x;
}

