void solve(long long N) {
  vl ans;

  if (N > 4) {
    ans.push_back(2);
    ans.push_back(3);

    ll cnt = 2;
    ll i = 1;
    ll m = 0;
    while (cnt < N) {
      ans.push_back(6 * i + m);
      cnt++;

      if (cnt == N) {
        break;
      }

      if (m == 0) {
        m = 2;
      } else if (m == 2) {
        m = 3;
      } else if (m == 3) {
        m = 4;
      } else if (m == 4) {
        i++;
        m = 0;
      }
    }

    ll sum = 0;
    rep(n, N) { sum += ans[n]; }
    if (sum % 6 != 0) {
      while (sum % 6 != 0) {
        sum -= ans[N - 1];

        if (m == 0) {
          m = 2;
        } else if (m == 2) {
          m = 3;
        } else if (m == 3) {
          m = 4;
        } else if (m == 4) {
          i++;
          m = 0;
        }
        ans[N - 1] = 6 * i + m;
        sum += ans[N + 1];
      }
    }
  } else {
    if (N == 3) {
      ans.push_back(2);
      ans.push_back(5);
      ans.push_back(63);
    }
    if (N == 4) {
      ans.push_back(2);
      ans.push_back(5);
      ans.push_back(20);
      ans.push_back(63);
    }
  }

  rep(n, N) {
    cout << ans[n];
    if (n != N - 1) {
      cout << " ";
    }
  }
  cout << endl;
}

int main() {
  long long N;
  scanf("%lld", &N);
  solve(N);
  return 0;
}

