int64_t gcd(int64_t a, int64_t b){
    if(b == 0) return a;
    return gcd(b, a % b);
}

int64_t lcm(int64_t a, int64_t b){
    return a * b / gcd(a, b);
}

bool checkPrime(int n){
    if(n <= 1) return false;
    for(int i = 2; i * i <= n; ++i){
        if(n % i == 0){
            return false;
        }
    }
    return true;
}

int po[20001];
bool prime[20001];
bool used[100001];

int64_t pr = 1;
int64_t sum = 0;

int Func(int n){
    int ans = 0;
    while(true){
        ans += pr;
        if(!used[ans] && gcd(63, sum + ans) > 1){
            break;
        }
    }
    return ans;
}

int main(){
    int N;
    cin >> N;

    po[0] = 2;
    po[1] = 5;
    po[2] = 63;
    for(int i = 0; i < 3; ++i){
        used[i] = true;
        sum += po[i];
        prime[i] = checkPrime(po[i]);
        if(prime[i]) pr *= po[i];
    }

    for(int i = 4; i <= N; ++i){
        po[i - 1] = Func(i);
        sum += po[i - 1];
        prime[i - 1] = checkPrime(po[i - 1]);
        if(prime[i - 1]) pr *= po[i - 1];
        used[po[i - 1]] = true;
    }

    for(int i = 0; i < N; ++i){
        if(i != 0) cout << " ";
        cout << po[i];
    }
    cout << endl;
}

