using namespace std;
template <typename T>
T gcd(T a, T b) {
  T large; 
  T less;
  if (a >= b) {
    large = a, less = b;
  } else {
    large = b, less = a;
  }
  while (large > less) {
    large -= less;

    if (large <= less) {
      swap(large, less);
    }
  }
  return large;


}

int lotgcd(int vec[], int num)
{
  int tmp;
  tmp = gcd(vec[0], vec[1]);
  for (int i=2; i<num; i++) {
    tmp = gcd(tmp, vec[i]);

  }
  return tmp;
}

