    return (b == 0 ? a : gcd(b, a % b));
}

void solve(int N) {
    vector<long long> a(N);
    for (int i = 0; i < N - 2; i++) {
        a[i] = i + 2;
    }

    for (long long k = a[N - 3] + 1; k <= 30000; k++) {
        a[N - 2] = k;
        for (long long i = k + 1; i <= 30000; i++) {
            a[N - 1] = i;
            auto sum = accumulate(a.begin(), a.end(), 0LL);
            bool flag = true;
            for (int j = 0; j < N; j++) {
                if (gcd(a[j], sum - a[j]) == 1) {
                    flag = false;
                    break;
                }
            }

            if (flag) {
                for (int j = 0; j < N; j++) {
                    cout << a[j] << " ";
                }
                cout << endl;
                return;
            }
        }
    }
}

