int __gcd(int a, int b) {
    if (a == 0 || b == 0) return a + b;
    if (a > b) swap(a, b);
    return __gcd(b % a, a);
}

bool solve(int n) {
    for (int x = 2; x + 1 <= 30000; x++) {
        for (int y = 2; y <= 30000; y++) {
