ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
ll mod_inv(ll a, ll m) { ll x, y; extgcd<ll>(a, m, x, y); return (m + x % m) % m; }

vector<int> solve(int n) {
	vector<int> ans = { 3,5 };
	n -= 2;
	ll cur = 8;
	for (int i = 6; i <= 30000; i++) {
		if (n == 1) break;
		if (i % 2 == 0 || i % 3 == 0 || i % 5 == 0) {
			cur += i;
			ans.push_back(i);
			n--;
		}
	}
	while (n == 1) {
		for (int i = ans.back(); i <= 30000; i++) {
			if ((cur + i) % 30 == 0 && gcd<ll>(cur, i) > 1) {
				ans.push_back(i);
				n--;
				break;
			}
		}

		if (n == 1) {
			int ss = ans.back();
			cur -= ss;
			ans.pop_back();
			ss++;
			while (gcd(ss, 30) == 1) {
				ss++;
			}
			cur += ss;
			ans.push_back(ss);
		}
	}

	return ans;
}

