		rep(i, MAX_A + 1) {
			if (ans[i]) {
				sum += i;
				if (eratos[i])
					multi *= i;
			}
		}
		for (LL i = (sum / multi + 1) * multi; i - sum <= MAX_A; i += multi) {
			LL num = i - sum;
			if (!ans[num] && Gcd(i, num) != 1) {
				ans[num] = true;
				break;
			}
		}

		auto a = TrueIndex(ans, [](bool b) {return b; });
		if (sz(a) == N)
			out.exit(a);
	};

	auto primes = Prime(MAX_A);
	solve(N, primes);

	for (int i = 0;; i++) {
		primes = Prime(MAX_A);
		while (true) {
			auto it = primes.begin() + i;
			if (it == primes.end())break;
			primes.erase(it);
			solve(N, primes);
		}
	}
}

