ll bs(ll low,ll high,ll target)
{
  while(low+3<high)
  {
    ll mid=(low+high)/2;
    //increasing function with inclusion
    if(brr[mid]<=target)
    {
      low=mid; //included
    }
    else
    {
      high=mid-1; //not included
    }
  }

  frr(o,high,low)
  {
    if(brr[o]<=target) return o;
  }
  return -1;//to check for bugs
}

