int Gcd(int a, int b) {
  while (b) {
    a %= b;
    swap(a, b);
  }
  return a;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;

  int sum = 0;
  vector<int> result;

  for (int v = 2; result.size() < N - 2 && v <= 30000; v += 2) {
    result.push_back(v);
    sum += v;
  }

  for (int v = 3; result.size() < N - 1 && v <= 30000; v += 6) {
    result.push_back(v);
    sum += v;
  }

  for (int cand = result.back() + 2; cand <= 30000; cand += 2) {
    if (Gcd(sum, cand) == 1) {
      continue;
    }
    if (Gcd(sum + cand - 3, 3) == 1) {
      continue;
    }

    result.push_back(cand);
    assert(result.size() == N);
    for (int r : result) {
      cout << r << ' ';
    }
    cout << '\n';

    return 0;
  }

  assert(false);

  return 0;
}

