    rep(i, n) {
        g = __gcd(g, a[i]);
    }
    if (g != 1) {
        return 0;
    }
    if (!(n == x)) {
        return 0;
    }
    rep(i, n) {
        if (!(1 <= a[i] && a[i] <= 30000)) {
            return 0;
        }
    }
    map<ll, ll> memo;
    rep(i, n) {
        memo[a[i]]++;
    }
    for (auto x : memo) 
        if (!(x.se <= 1)) {
            return 0;
        }

    ll s = accumulate(all(a), 0ll);
    rep(i, n) {
        if(!(__gcd(s-a[i], a[i]) != 1)){
            return 0;
        }
    }
    return 1;
