int A[20004];

int solve(int a, int b, int c, int N)
{
    A[1] = a, A[2] = b, A[3] = c;
    int sum = a+b+c, ptr = 2;
    int lcm = a * b * c;

    while(ptr == a || ptr == b || ptr == c || (ptr%a && ptr%b && ptr%c))
        ptr++;

    for(int i=4; i<N; i++)
    {
        A[i] = ptr++;

        while(ptr == a || ptr == b || ptr == c || (ptr%a && ptr%b && ptr%c))
            ptr++;

        sum += A[i];
    }

    while((sum + ptr) % lcm)
    {
        ptr++;

        while(ptr == a || ptr == b || ptr == c || (ptr%a && ptr%b && ptr%c))
            ptr++;

        if(ptr > 30000)
            return 0;
    }

    A[N] = ptr;
    return 1;
}

int main() {

    cin.tie(NULL), cout.tie(NULL);

    int N;
    cin >> N;

    if(N == 3)
    {
        cout << "2 5 63\n";
        return 0;
    }

    int prime[5] = {2, 3, 5, 7, 11};

    for(int i=0; i<5; i++)
        for(int j=i+1; j<5; j++)
            for(int k=j+1; k<5; k++)
            {
                if(solve(prime[i], prime[j], prime[k], N))
                {
                    for(int x=1; x<=N; x++)
                        cout << A[x] << " ";
                    cout << "\n";

                    return 0;
                }
            }

    return 0;
}

