    for (int j = 1; j < 15; ++j) {
        if (j % 2 == 0 or j % 3 == 0) {
            legits.push_back(j);
        }
    }

    b = 0;
    while (b < 30000 and n >= 2) {
        for (int x : legits) {
            if (n < 2) break;
            if (b + x == 2 or b + x == 3 or b + 30 - x == 25) continue;
            if (b + 30 - x >= 30000) continue;

