std::bitset<900000000> mem;
std::bitset<900000000> memed;

int gcd(int m, int n) {
    if (m < n) {
        std::swap(m, n);
    }
    const int d = m % n;
    const int ret = d ? gcd(n, d) : n;
    const auto idx = static_cast<size_t>(m + n * 30000);
    if (!memed[idx]) {
        mem.set(idx, ret == 1);
        memed.set(idx, true);
    }
    return ret;
}

bool gcdIsOne(int m, int n) {
    if (m < n) {
        std::swap(m, n);
    }
    const auto idx = static_cast<size_t>(m + n * 30000);
    if (memed[idx]) {
        return mem[idx];
    }
    return gcd(m, n) == 1;
}

static std::vector<int> emptySeq;

std::vector<int> gcdSequence(int n, int p, std::vector<int> &seq, int threshold) {
    if (n == p) {
        int g = gcd(seq[0], seq[1]);
        for (int i = 2; i < n; ++i) {
            g = gcd(g, seq[i]);
        }
        if (g > 1) {
            return emptySeq;
        }
        int sum = std::accumulate(seq.cbegin(), seq.cend(), 0);
        for (int i = 0; i < n; ++i) {
            int v = seq[i];
            if (gcdIsOne(v, sum - v)) {
                return emptySeq;
            }
        }
        return seq;
    }

    for (int i = seq[p - 1] + 1; i <= threshold; ++i) {
        seq[p] = i;
        auto ret = gcdSequence(n, p + 1, seq, threshold);
        if (ret.size() > 0) {
            return ret;
        }
    }
    return emptySeq;
}

std::vector<int> gcdSequence(int n, int threshold) {
    std::vector<int> seq(n);
    for (int i = 2; i <= threshold; ++i) {
        seq[0] = i;
        auto ret = gcdSequence(n, 1, seq, threshold);
        if (ret.size() > 0) {
            return ret;
        }
    }
    return seq;
}

int main() {
    int n;
    std::cin >> n;
    int threshold = std::max(6, n);
    std::vector<int> seq;
    while (threshold <= 30000) {
        seq = gcdSequence(n, 100);
        if (seq.size() > 0) {
            break;
        }
        threshold *= 2;
        threshold = std::min(threshold, 30000);
    }
    for (auto itr = seq.cbegin(); itr != seq.cend(); ++itr) {
        std::cout << *itr;
        if (itr != seq.cend() - 1) {
            std::cout << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

