#include <cstdio>
using namespace std;
int gcd(register int a, register int b){
	register int c;
	while (c = a % b) {
		a = b;
		b = c;
	}
	return b;
}
int main(){
	register int n, i, cnt, sum = 0;
	scanf("%d", &n);
	for (i = cnt = 1; i <= 30000 && cnt < n; ++i) {
		if (i % 2 == 0 || i % 3 == 0) printf("%d ", i), ++cnt, ++sum;
	}
	for (; i <= 30000; ++i) if (gcd(sum, i) > 1 && (sum + i) % 2 == 0 && (sum + i) % 3 == 0) {
		printf("%d", i);break;
	}
	return 0;
}

