const int MaxN = 20000,MaxS = 30000;
typedef long long LL;
int n;
vector<int> s;
LL sum;

int main() {
    scanf("%d",&n);
    if (n==3) return printf("%d %d %d\n",2,5,63),0;
    s.push_back(2);s.push_back(3);sum=5;n-=2;
    for (int i=4;i<=MaxS;++i)
        if (i%2==0 || i%3==0) {
            s.push_back(i);
            n--;
            sum+=i;
            if (n==0) break;
        }
    if (sum%6) {
        int it=s.back();
        for (int i=MaxS;i>it;--i) if (i%2==0 || i%3==0) {
            for (int j=(int)s.size()-1;j>=2;--j) if ((sum-s[j]+i)%6==0) {
                s[j]=i;
                sum=sum-s[j]+i;
                break;
            }
            if (sum%6==0) break;
        }
    }
    for (int i=0;i<s.size();++i) printf("%d ",s[i]);
    return 0;
}

