    puts("2 5 63");
    return 0;
  }
  if (n == 4) {
    puts("2 5 20 63");
    return 0;
  }
  if (n == 6) {
    puts("2 3 4 5 6 10");
    return 0;
  }

  vector<int> s[3];
  for (int i = 2; i <= 30000; ++i) {
    if (i % 6 == 0)
      s[2].pb(i);
    else if (i % 2 == 0)
      s[0].pb(i);
    else if (i % 3 == 0)
      s[1].pb(i);
  }

  vector<int> ans;
  for (int i = 0; i < min(n, (int)s[2].size()); ++i) {
    ans.pb(s[2][i]);
  }
  n -= min(n, (int)s[2].size());

  if (n)
    for (int a = 1; 3 * a < s[0].size(); ++a) {
      bool f = false;
      for (int b = 1; 2 * b < s[1].size(); ++b) {
        if (3 * a + 2 * b == n) {
          for (int i = 0; i < 3 * a; ++i) {
            ans.pb(s[0][i]);
          }
          for (int i = 0; i < 2 * b; ++i) {
            ans.pb(s[1][i]);
          }

          f = true;
          break;
        }
      }

      if (f) break;
    }

  cout << ans << endl;
}

