const int K=30000;

vi solve(int n) {
    if (n==3) return {2,3,25};
    vi ans{2,4,3,9};
    int k=ans.size();
    for (int x=10; x<=K && k+2<=n; x+=6) {
        ans.pb(x-2);
        ans.pb(x);
        k+=2;
    }
    for (int x=21; x<=K && k+2<=n; x+=12) {
        ans.pb(x-6);
        ans.pb(x);
        k+=2;
    }
    for (int x=6; x<=K && k+1<=n; x+=6) {
        ans.pb(x);
        k+=1;
    }
    return ans;
}

bool check(int n, const vi& xs) {
    if (n!=(int)xs.size()) return false;
    ll hi=*max_element(all(xs));
    if (hi>K) return false;
    ll d=0;
    for (int x:xs) d=gcd(d, x);
    if (d!=1) return false;
    ll sum=accumulate(all(xs), 0ll);
    for (int x:xs)
        if (gcd(x, sum-x)<=1) return false;
    return true;
}

