void solve(){
  ini(N);
  vi ans;
  ll s = 0;
  for(int i = 1 ; ; i++){
    if(i % 3 != 0 && i % 2 != 0) continue;
    if(sz(ans) < N - 2){
      ans.push_back(i);
      s += i;
    }
    else if(sz(ans) == N - 2){
      if((s + i) % 6 == 1 || (s + i) % 6 == 5) continue;
      ans.push_back(i);
      s += i;
    }
    else if(sz(ans) == N - 1){
      if((s + i) % 6 == 0)
        ans.push_back(i);
    }
    if(sz(ans) == N) break;
  }
  out(ans);
}

