struct IO {
#ifdef _WIN32
  inline char getchar_unlocked() { return getchar(); }
  inline void putchar_unlocked(char c) { putchar(c); }
#endif
  std::string separator = " ";
  template <class T>
  inline void read(T& x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c != '-' && (c < '0' || '9' < c));
    bool minus = 0;
    if (c == '-') {
      minus = 1;
      c = getchar_unlocked();
    }
    x = 0;
    while ('0' <= c && c <= '9') {
      x *= 10;
      x += c - '0';
      c = getchar_unlocked();
    }
    if (minus) x = -x;
  }
  inline void read(std::string& x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c == ' ' || c == '\n');
    x.clear();
    do {
      x += c;
      c = getchar_unlocked();
    } while (c != ' ' && c != '\n' && c != EOF);
  }
  template <class T>
  inline void read(std::vector<T>& v) {
    for (auto& x : v) read(x);
  }
  template <class S, class T>
  inline void read(std::pair<S, T>& p) {
    read(p.first);
    read(p.second);
  }
  template <class Head, class... Tail>
  inline void read(Head& head, Tail&... tail) {
    read(head);
    read(tail...);
  }
  template <class T>
  inline void write(T x) {
    char buf[32];
    int p = 0;
    if (x < 0) {
      x = -x;
      putchar_unlocked('-');
    }
    if (x == 0) putchar_unlocked('0');
    while (x > 0) {
      buf[p++] = (x % 10) + '0';
      x /= 10;
    }
    while (p) {
      putchar_unlocked(buf[--p]);
    }
  }
  inline void write(std::string x) {
    for (char c : x) putchar_unlocked(c);
  }
  inline void write(const char s[]) {
    for (int i = 0; s[i] != 0; ++i) putchar_unlocked(s[i]);
  }
  template <class T>
  inline void write(std::vector<T> v) {
    if (v.empty()) return;
    for (auto itr = v.begin(); itr + 1 != v.end(); ++itr) {
      write(*itr);
      write(separator);
    }
    write(v.back());
  }
  template <class Head, class... Tail>
  inline void write(Head head, Tail... tail) {
    write(head);
    write(separator);
    write(tail...);
  }
  template <class Head, class... Tail>
  inline void writeln(Head head, Tail... tail) {
    write(head, tail...);
    write("\n");
  }
  void set_separator(std::string s) { separator = s; }
} io;

int main() {
  int N;
  io.read(N);
  if (N == 3) {
    io.writeln(vector<int>({2, 5, 63}));
  } else if (N == 4) {
    io.writeln(vector<int>({2, 5, 20, 63}));
  } else if (N == 5) {
    io.writeln(vector<int>({2, 3, 4, 6, 15}));
  } else {
    vector<int> ans;
    int last_even, last_odd;
    FOR(i, 1, 30001) {
      if (ans.size() >= N) break;
      if (i % 2 == 0 || i % 3 == 0) {
        ans.push_back(i);
        if (i % 2 == 0)
          last_even = ans.size() - 1;
        else
          last_odd = ans.size() - 1;
      }
    }
    int mod = accumulate(ALL(ans), 0) % 6;
    if (mod % 2 == 1) {
      ans[last_odd] += (6 - mod);
      if (N < 19998) ans[last_odd] += 6;
    } else if (mod > 0) {
      ans[last_even] += (6 - mod);
      if (N < 19998) ans[last_even] += 6;
    }
    io.writeln(ans);
  }
  return 0;
}

