  }
  for(int i = 3; i <= 30000; i += 3) {
    if(i % 2 == 0) continue;
    v.emplace_back(i);
  }
  auto check = [&]() {
    int sum = 0, gcd = 0;
    for(int i = 0; i < N; i++) sum += v[i];
    for(int i = 0; i < N; i++) {
      if(__gcd(sum, v[i]) == 1) return false;
      gcd = __gcd(gcd, v[i]);
    }
    return gcd == 1;
  };
  while(!check()) {
    shuffle(begin(v), end(v), rnd);
  }
  for(int i = 0; i < N; i++) {
    cout << v[i] << " ";
  }
  cout << endl;
