int gcd(int x, int y) {
	if (y > x) return gcd(y, x);
	if (y == 0) return x;
	return gcd(y, x % y);
}

bool special(vector<int> v) {
	int sum = 0;
	rep(i, v.size()) {
		sum += v[i];
	}
	rep(i, v.size()) {
		if (gcd(v[i], sum - v[i]) == 1) return false;
	}
	int g = gcd(v[0], v[1]);
	rep(i, (int)v.size() - 2) {
		g = gcd(g, v[i + 2]);
	}
	return g == 1;

}


