            LL s = sum + d;
            if (gcd(s, d) > 1 && ans.find(d) == ans.end()) {
                sum += d;
                ans.insert(d);
                N--;
            }
            d--;
            if (d == 0) break;
        }
        if (N == 1) {
            break;
        }
    }

    LL g = 30000;
    for (auto x: ans) g = gcd(x, g);

