    int cnt = x;
    vi bits;
    rep (i, 8 - cnt) bits.pb(0); rep (i, cnt) bits.pb(1);
    do {
        vi use; int sum = 0;
        bool flag = true;
        rep (i, 8) if (bits[i]) use.pb(cand[i]), sum += cand[i];
        int gcd = use[0];
        FOR (i, 1, cnt) gcd = __gcd(gcd, use[i]);
        if (gcd != 1) flag = false;
        rep (i, cnt) {
