// gcd(0,0) は未定義
i64 gcd(i64 a, i64 b) {
    assert(a != 0 || b != 0);
    const auto impl = RECURSIVE([](auto&& self, i64 x, i64 y) {
        if(y == 0) return x;
        return self(y, x % y);
    });
    return impl(ABS(a), ABS(b));
}

i64 N;



void solve() {
    if(is_even(N%3) && N >= 5) {
        vector<i64> ans;
        i64 n = min<i64>(15000, N/3*3);
        i64 m = N - n;
        FOR(i, 1, n) {
            ans.emplace_back(2*i);
        }
        for(i64 i = 1; m > 0; ++i) {
            i64 a = 3*i;
            if(is_even(a)) continue;

            ans.emplace_back(a);
            --m;
        }

        PRINTLN(ans);
    }
}

