void solve(){
    ll tot = 0; ll i = 2;
    while (ans.size() < n - 1){
        if (i % 2 == 0 || i % 3 == 0) {ans.pb(i); visited[i] = true; tot += i;}
        i++;
    }

    rep(i, n - 1) prs(ans[i]);

    ll num = 4;
    while (true){
        if (visited[num]) {num++; continue;}
        bool c1 = (tot + num) % 6 == 0;
        bool c2 = gcd(tot, num) != 1;
        if (c1 && c2) {ans.pb(num); break;}
        num++; 
    }

    assert(num <= 30000);
    prl(ans[n - 1]);
}

