const int MAX_VALUE = 30000;

#ifdef __LOCAL
bool validate(vector<int> v)
{
	for(auto& x: v)
	{
		if(x < 1 || x > MAX_VALUE)
			return false;
	}

	sort(v.begin(), v.end());

	for(int i = 0; i + 1 < len(v); ++i)
	{
		if(v[i + 1] == v[i])
			return false;
	}

	int common_gcd = v.front();	

	for(auto& x: v)
		common_gcd = gcd(common_gcd, x);

	if(common_gcd != 1)
		return false;

	int fsum = 0;

	for(auto& x: v)
		fsum += x;

	for(auto& x: v)
	{
		if(gcd(x, fsum - x) == 1)
			return false;
	}

	return true;
}
#endif

void solve()
{
	int n;
	cin >> n;

	vector<int> answ;
	int fsum = 0;

	for(int c = 1; c <= MAX_VALUE; ++c)
	{
		if(c % 2 == 0 || c % 3 == 0)
		{
			answ.push_back(c);
			fsum += c;
		}

		if(len(answ) == n)
			break;
	}

	if(fsum % 6 != 0)
	{
		int last = answ.back();
		answ.pop_back();
		fsum -= last;

		int last2 = answ.back();
		answ.pop_back();
		fsum -= last2;

		for(int i = last;; ++i)
		{
			for(int j = last2; j < i; ++j)
			{
				bool ok = true;

				ok &= (fsum + i + j) % 6 == 0;
				ok &= (i % 2 == 0 || i % 3 == 0);
				ok &= (j % 2 == 0 || j % 3 == 0);

				if(ok)
				{
					answ.push_back(j);
					answ.push_back(i);

					goto end;
				}
			}
		}
	}

end:
#ifdef __LOCAL
	validate(answ);
#endif

	cout << answ << endl;
}

int main()
{
	fast_io();
	solve();

	return 0;
}

