vector<ll> solve(const vector<ll>& a, int n) {
  vector<ll> ans;
  ll i = 0;
  ll j = 0;
  while (n) {
    ans.push_back(a[i] + 12*j);
    ++i;
    if (i == 8) {
      i = 0;
      ++j;
    }
    --n;
  }
  return ans;
}

