    int odd, even;
    if (n <= N) {
        even = (n - 1) / 3 * 3;
        odd = n - even;
        if (odd % 2) {
            odd ++;
            even --;
        }
    } else {
        even = 15000;
        odd = n - even;
        if (odd % 2) {
            odd ++;
            even --;
        }
    }
    print_even(even);
    print_odd(odd);
    printf("\n");
}

