bool solve(int N) {
  int sum = 0;
  vector<int> nums;
  for (int i = 2;; i++) {
    if (i % 2 == 0 || i % 3 == 0) {
      nums.push_back(i);
      sum += i;
      if (nums.size() == N - 1) break;
    }
  }
  if (sum % 6 == 5) {
    for (int i = N - 2; i >= 0; i--) {
      if (nums[i] % 6 == 3) {
        sum -= nums[i];
        nums.erase(nums.begin() + i);
        nums.push_back(nums.back() + 2);
        sum += nums.back();
        break;
      }
    }
  }

  for (int x : nums) {
    cout << x << ' ';
  }
  for (int x = nums.back() + 1; x <= 30000; x++) {
    if ((x + sum) % 6 == 0 && __gcd(x, sum) > 1) {
      cout << x << endl;
      return true;
    }
  }
  dbg(N, sum, sum % 6);
  return false;
}

