int gcd(int m, int n)
{
  // ユークリッドの方法
  while (m != n)
  {
    if (m > n)
      m = m - n;
    else
      n = n - m;
  }
  return m;
} //gcd

bool check(int num)
{
  long long sum = 0;
  for (auto x : s)
  {
    sum += x;
  }
  sum += num;
  for (auto x : s)
  {
    if (gcd(x, sum - x) == 1)
    {
      return false;
    }
  }
  if (gcd(num, sum - num) == 1)
  {
    return false;
  }

  int y = num;
  //すべての最大公約数が1
  for (auto x : s)
  {
    y = gcd(y, x);
  }
  if (y != 1)
  {
    return false;
  }
  return true;
}

