bool check(const vector<int>& v) {
    int sum = 0;
    set<int> s(ALL(v));
    if(SZ(s) != SZ(v)) return false;
    REP(i, SZ(v)) {
        sum += v[i];
    }
    int g = v[0];
    REP(i, SZ(v)) {
        g = gcd(g, v[i]);
    }
    if(g > 1) return false;
    REP(i, SZ(v)) {
        if(gcd(v[i], sum-v[i]) == 1) {
            return false;
        }
    }
    return true;
}

void enu(int n, vector<int>& v) {
