  auto tmp = A;
  A.erase(unique(A.begin(),A.end()),A.end());
  if(A.size() != tmp.size()) return 0;
  if(A.back() > 30000) return 0;

  int sum = 0;
  for(int a:A) sum += a;

  for(int a:A) if(__gcd(sum-a,a) == 1) return 0;
  int gcd = A[0];
  for(int a:A) gcd = __gcd(a,gcd);
  return gcd == 1;
}


