bool check(vector<long long> vec) {
    long long sum = 0;
    for (int i = 0; i < vec.size(); ++i) {
        if (vec[i] > 30000) return false;
        sum += vec[i];
    }

    for (int i = 0; i < vec.size(); ++i) {
        long long rem = sum - vec[i];
        long long d = GCD(vec[i], rem);
        if (d == 1) return false;
    }

    long long d = vec[0];
    for (int i = 0; i < vec.size(); ++i) {
        d = GCD(d, vec[i]);
    }
    if (d != 1) return false;

    set<long long> se;
    for (int i = 0; i < vec.size(); ++i) {
        if (se.count(vec[i])) return false;
        se.insert(vec[i]);
    }

    return true;
}

