template <typename T>
T gcd(T a, T b) {
  T large; 
  T less;
  if (a >= b) {
    large = a, less = b;
  } else {
    large = b, less = a;
  }
  while (large > less) {
    large -= less;

    if (large <= less) {
      swap(large, less);
    }
  }
  return large;


}

