void solve() {
  int n;
  cin >> n;
  if (n == 3) {
    vi32 ans = {2, 5, 63};
    cout << ans << endl;
    return;
  }
  vi32 div2, div3, div6;
  reps(i, 30000) {
    if (i % 6 == 0) {
      div6.push_back(i);
    } else if (i % 2 == 0) {
      div2.push_back(i);
    } else if (i % 3 == 0) {
      div3.push_back(i);
    }
  }
  vi32 ans;
  if (n % 2 == 1) {
    ans.push_back(div6[0]);
    n--;
  }
  ans.push_back(div3[0]);
  ans.push_back(div3[1]);
  n -= 2;
  rep(i, min(n, (int) div2.size())) {
    ans.push_back(div2[i]);
  }
  n = max(n - (int) div2.size(), 0);
  repi(i, 2, min(n + 2, (int) div3.size())) {
    ans.push_back(div3[i]);
  }
  n = max(n - (int) div3.size() + 2, 0);
  if (ans[0] == div6[0]) {
    reps(i, n) {
      ans.push_back(div6[i]);
    }
  } else {
    rep(i, n) {
      ans.push_back(div6[i]);
    }
  }
  cout << ans << endl;
}

