ll facs(ll n)
{
	if (n <= 1) return false;
	if (n == 2) return true;
	if (n % 2 == 0) return false;
	ll m = sqrt(n);


	for (ll i = 3; i <= m; i += 2)
		if (n%i == 0)
			return i;

	return n;
}

