		ans.push_back(good[upto + 3]);
	} else if(miss == 4){
		ans.push_back(good[upto]);
		ans.push_back(good[upto + 1]);
		ans.push_back(good[upto + 2]);
		ans.push_back(good[upto + 5]);
	} else {
		for(int j = 0; j < 4; j++) ans.push_back(good[upto + j]);
		upto += 4;
		miss -= 4;
		if(miss == 1){
			ans.push_back(good[upto + 1]);
		} else if(miss == 2){
			ans.push_back(good[upto + 1]);
			ans.push_back(good[upto + 3]);
