void solve(ll n){
  vector<ll> ans;
  if(n==3){
    ans = {2,5,63};
    print_array(ans);
  }
  if(n==4){
    ans = {2,5,20,63};
    print_array(ans);
  }
  if(n==5){
    ans = {2,3,4,6,9};
    print_array(ans);
  }
  //n>=6, n=4k+r
  ll k = n/4;
  ll r = n%4;
  FOR(i,1,k+1){
    ans.push_back(6*i-4);
    ans.push_back(6*i-3);
    ans.push_back(6*i-2);
    ans.push_back(6*i);
  }
  FOR(i,1,4){
    if(r>=i) ans.push_back(6*k+1+i);
  }
  //帳尻合わせ
  ll sum = 0;
  k++;
  REP(i,SZ(ans)) sum += ans[i];
  if(sum%6==5){
    if(n==19997) ans.push_back(6*(k-1)+4);
    else ans.push_back(6*k+4);
    ans.erase(ans.begin()+5); //9を消す
