  if(sum%6==3){
    ans.push_back(6*k);
    ans.erase(ans.begin()+5); //9を消す
  }
  if(sum%6==2){
    ans.push_back(6*k);
    ans.erase(ans.begin()+4); //8を消す
  }
  print_array(ans);
}

