vector<int> v[3], sum[3];

vector<int> solve(int N) {
	vector<int> res;

	if (N == 3) {
		res.assign({2, 5, 63});
		return res;
	}

	REP(i, 3) {
		sum[i] = v[i];
		FOR(j, 1, v[i].size()) sum[i][j] += sum[i][j - 1];
	}

	REP(a, v[0].size() + 1) {
		REP(b, v[1].size() + 1) {
			int c = N - a - b;
			if (c > v[2].size()) continue;
			if (c < 0) break;
			if ((a > 0) + (b > 0) + (c > 0) <= 1) continue;

			int sa = a ? sum[0][a - 1] : 0;
			int sb = b ? sum[1][b - 1] : 0;
			int sc = c ? sum[2][c - 1] : 0;

			if (a > 0 && (sb + sc) % 2 != 0) continue;
			if (b > 0 && (sa + sc) % 3 != 0) continue;
			if (c > 0 && (sa + sb) % 5 != 0) continue;
			res.insert(res.end(), v[0].begin(), v[0].begin() + a);
			res.insert(res.end(), v[1].begin(), v[1].begin() + b);
			res.insert(res.end(), v[2].begin(), v[2].begin() + c);
			return res;
		}
	}

	return res;
}

ll gcd(ll a, ll b) {
	if (b == 0) return a;
	return gcd(b, a % b);
}

bool check(int N, vector<int> ans) {
	if (ans.size() != N) { puts("A"); return false; }
	set<int> ss;
	REP(i, N) ss.insert(ans[i]);
	if (ss.size() != ans.size()) { puts("B"); return false; }


	REP(i, N) if (ans[i] < 1 || ans[i] > 30000) { puts("C"); return false; }

	int g = ans[0];
	REP(i, N) g = gcd(g, ans[i]);
	if (g != 1) { puts("D"); return false; }

	int sum = accumulate(ans.begin(), ans.begin() + N, 0);
	REP(i, N) if (gcd(ans[i], sum - ans[i]) == 1) {
		puts("E");
		printf("%d %d\n", ans[i], sum - ans[i]);
		return false;
	}

	return true;
}

int main() {
	int N; cin >> N;

	int mx = 30000;
	for (int i = 2; i <= mx; i += 2) v[0].push_back(i);
	for (int i = 3; i <= mx; i += 6) v[1].push_back(i);
	for (int i = 5; i <= mx; i += 5) if (i % 2 && i % 3) v[2].push_back(i);

	vector<int> ans = solve(N);
	if (ans.empty()) assert(false);

	//FOR(i, 3, 20000) if (!check(i, solve(i))) cout << i << endl;
	REP(i, N) printf("%d%c", ans[i], i == N - 1 ? '\n' : ' ');
	return 0;
}

