void chemthan() {
    FOR(i, 2, maxn) sp[i] = i;
    FOR(i, 2, maxn) if (sp[i] == i) {
        for (int j = i; j < maxn; j += i) {
            chkmin(sp[j], i);
        }
    }
    FOR(i, 2, maxn) {
        int t = i;
        set<int> st;
        while (t > 1) {
            st.insert(sp[t]);
            t /= sp[t];
        }
        if (sz(st) >= 2) {
            g[i].pb(*st.begin());
            g[i].pb(*st.rbegin());
        }
    }
    int n; cin >> n;
