        if (sz(g[n - k]) == 2) {
            FOR(i, 0, n - k - k) cout << 5 << " ";
            FOR(i, 0, k) cout << 2 << " ";
            FOR(i, 0, k) cout << 3 << " \n"[i == k - 1];
            return;
        }
    }
}

