vector<bool> Eratosthenes(int n) {
	vector<bool> p(n + 1, true);
	p[0] = p[1] = false;
	for (int i = 0; i <= n; ++i)if (p[i])
		for (int j = i * 2; j <= n; j += i)p[j] = false;
	return p;
}

vector<int> Prime(int n) {
	vector<int> ret;
	auto p = Eratosthenes(n);
	for (int i = 0; i <= n; ++i)
		if (p[i])ret.push_back(i);
	return ret;
}

int main() {
	int N = in;

	const int MAX_A = 30000;
	auto eratos = Eratosthenes(MAX_A);

	auto solve = [&](int n, const VI& primes) {

		vector<bool> ans(MAX_A + 1);
		ans[primes[0]] = true;
		ans[primes[1]] = true;
		n -= 2;

		for (auto p : primes) {
			for (int i = p; n >= 2 && i <= MAX_A; i += p) {
				if (!ans[i]) {
					ans[i] = true;
					n--;
				}
			}
		}
		int multi = 1, sum = 0;
		rep(i, MAX_A + 1) {
			if (ans[i]) {
				sum += i;
				if (eratos[i])
					multi *= i;
			}
		}
		for (int i = (sum / multi + 1) * multi; i - sum <= MAX_A; i += multi) {
			int num = i - sum;
			if (!ans[num] && Gcd(i, num) != 1) {
				ans[num] = true;
				break;
			}
		}

		auto a = TrueIndex(ans, [](bool b) {return b; });
		if (sz(a) == N)
			out.exit(a);
	};

	auto primes = Prime(MAX_A);
	solve(N, primes);
	while (true) {
		primes.erase(primes.begin());
		solve(N, primes);
	}
}

