    puts("2 5 20 63");
    return 0;
  }
  if (n == 6) {
    puts("2 3 4 5 6 10");
    return 0;
  }

  vector<int> a[3];
  for (int i = 2; i <= 30000; ++i) {
    if (i % 6 == 0)
      a[2].push_back(i);
    else if (i % 2 == 0)
      a[0].push_back(i);
    else if (i % 3 == 0)
      a[1].push_back(i);
  }

  vector<int64_t> r[2];
  for (int idx = 0; idx < 2; ++idx) {
    r[idx].resize(a[idx].size());
    r[idx][0] = a[idx][0];
    for (int i = 1; i < a[idx].size(); ++i) {
      r[idx][i] = r[idx][i - 1] + a[idx][i];
    }
  }

  vector<int> s;
  for (int i = 0; i < a[0].size(); ++i) {
    bool f = false;
    for (int j = 0; j < a[1].size(); ++j) {
      if ((r[0][i] + r[1][j]) % 6 == 0 && n - (i + j + 2) <= a[2].size()) {
        for (int k = 0; k <= i; ++k) {
          s.push_back(a[0][k]);
        }
        for (int k = 0; k <= j; ++k) {
          s.push_back(a[1][k]);
        }
        for (int k = 0; k < n - (i + j + 2); ++k) {
          s.push_back(a[2][k]);
        }

        f = true;
        break;
      }
    }

    if (f) break;
  }

  // cerr << s.size() << endl;
  for (int i = 0; i < n; ++i) {
    cout << s[i] << (i + 1 == n ? "\n" : " ");
  }
}

