int gcd(int m, int n) {
    while (m != n) {
        if (m > n) {
            m = m - n;
        } else {
            n = n - m;
        }
    }
    return m;
}

static std::vector<int> emptySeq;

std::vector<int> gcdSequence(int n, int p, std::vector<int> &seq) {
    errOut(p);
    if (n == p) {
        errOut(seq.back());
        int sum = std::accumulate(seq.cbegin(), seq.cend(), 0);
        for (int i = 0; i < n; ++i) {
            int v = seq[i];
            if (gcd(v, sum - v) == 1) {
                return emptySeq;
            }
        }
        return seq;
    }

    for (int i = seq[p - 1] + 1; i < 30000; ++i) {
        int j = 0;
        for (; j < p; ++j) {
            if (gcd(i, seq[j]) > 1) {
                break;
            }
        }
        if (j < p) {
            continue;
        }
        seq[p] = i;
        auto ret = gcdSequence(n, p + 1, seq);
        if (ret.size() > 0) {
            return ret;
        }
    }
        return emptySeq;
}

std::vector<int> gcdSequence(int n) {
    std::vector<int> seq(n);
    errOut(seq.size());
    for (int i = 2; i < 30000; ++i) {
        seq[0] = i;
        auto ret = gcdSequence(n, 1, seq);
        if (ret.size() > 0) {
            return ret;
        }
    }
    return seq;
}

