vector<int> sol( int N )
{
  vector<int> res;

  if( N == 3 )
    {
      res.push_back(2);
      res.push_back(5);
      res.push_back(63);
      return res;
    }

  int cnt = 0;

  for( int num = 3 ;num <= 30000; num += 6 )
    { 
      if( ( ( (N-cnt)%3 == 2 ) or ( (N-cnt)%3 == 0 ) ) and 0 < cnt and N-cnt <= 15000 )
	{
	  break;
	}

      res.push_back(num);
      ++ cnt;
      num += 6;
      res.push_back(num);
      ++ cnt;
    }

  for( int num = 2; num <= 30000; num += 2 )
    {
      if( N == cnt )
	{
	  break;
	}

      res.push_back(num);
      ++ cnt;
    }

  return res;
}


