inline void dfs(int v, int last = 1) {
    if (v > n) {
        int s = 0, g = 0;
        for (int i = 1; i <= n; ++i)
            s += a[i], g = __gcd(g, a[i]);
        if (g != 1) return;
        for (int i = 1; i <= n; ++i)
            if (__gcd(a[i], s - a[i]) == 1) return;
        fo(i, n) cout << a[i] << ' ';
        cout << '\n';
        exit(0);
    }
    for(int i = last + 1; i <= K; i++) {
        a[v] = i;
        dfs(v + 1, i);
    }
}

inline int lcm(int x, int y) {
    return x / __gcd(x, y) * y;
}


