    return a/gcd(a,b)*b;
}
void add(int i){
    if (i>30000)return;
    if (!(n==1&&sig!=(i&1))){
        a[i]=1,d[++d[0]]=i,n--;
        all+=i;
        sig^=(i&1);
    }
}
bool check(int x){
    for (int i=1;i<=d[0];i++)
        if ((x+all)%d[i])return 0;
    return 1;
}
int main(){
