      X.push_back(i);
    }else if(i%2>0 && i%3==0){
      if(cc%2==0) Y.push_back(i);
      else YY.push_back(i);
      cc++;
    }else if(i%6==0){
      Z.push_back(i);
    }
  }

  reverse(X.begin(),X.end());
  reverse(Y.begin(),Y.end());
  reverse(YY.begin(),YY.end());
  reverse(Z.begin(),Z.end());
  //  cout<<X.size()<<' '<<Y.size()<<' '<<YY.size()<<endl;

