      for(int i=0;i<2;i++){
        ans.push_back(Y.back());
        Y.pop_back();
      }
    }


  }
  //  cout<<X.size()<<' '<<Y.size()<<endl;

  while( (int)ans.size() < n ){
    ans.push_back(Z.back());
    Z.pop_back();
  }
}

int main(){
