using namespace std;

int gcd(int a, int b) {
    while (b > 0) {
        int tmp = a % b;
        a = b;
        b = tmp;
    }
    return a;
}

vector<int> next(vector<int> vi, int N) {
    int poped_count = 0;
    for (int i = vi.size() - 1; i >= 0; i--) {
        if (vi[i] < N) {
            N = vi[i] + 1;
            vi.pop_back();
            poped_count++;
            REP(i, poped_count)
                vi.push_back(N++);
            return vi;
        }
        else {
            vi.pop_back();
            poped_count++;
        }
    }
    return vector<int>();
}

int main() {
    int N;
    cin >> N;
    vector<int> vi;
    FOR(i, 2, N + 2) vi.push_back(i);

    while (true) {
        int sum = accumulate(ALL(vi), 0);
        bool ok = true;
        REP(i, N) {
            if (gcd(vi[i], sum - vi[i]) == 1) {
                ok = false;
                break;
            }
        }
        int gcd_num = gcd(vi[0], vi[1]);
        FOR(i, 2, N)
            gcd_num = gcd(gcd_num, vi[2]);
        ok &= gcd_num == 1;

        if (ok) {
            for (int x : vi) {
                cout << x << " ";
            }
            cout << endl;
            return 0;
        }

        vi = next(vi, 100);
    }
    return 0;
}

