int gcd(int m, int n) {
  while(n != 0) {
    int r = m % n;
    m = n;
    n = r;
  }
  return m;
}

bool check(int m, const int sum, const vector<int> &a) {
  if(gcd(sum, m) == 1) return false;
  for(int i = 0; i < a.size(); i++) {
    if(gcd(sum-a[i]+m,a[i]) == 1) return false;
  }
  return true;
}

void solve(int N) {
