using namespace std;
#define ll long long

int NN[20000];
int LCM;
ll SUM;

int gcd(int m, int n){
  if ( ( 0 == m ) || ( 0 == n ) )
    return 0;
  while( m != n )
    {
      if ( m > n ) m = m - n;
      else         n = n - m;
    }
  return m;
}

int lcm(int m, int n){
  if ( ( 0 == m ) || ( 0 == n ) )
    return 0;
  return ((m / gcd(m, n)) * n);
}

bool prime_p(int num){
  for(int i=2; i<=floor(sqrt(num)); i++)
    if(num % i == 0)
      return false;
  return true;
}

void make(int num){
  int n = num;
  NN[num - n] = 2;
  LCM = 2;
  SUM = 2;
  n--;
  int tmp = 3;
  while(n > 0){
    if(!prime_p(tmp) || tmp == 3){
      NN[num - n] = tmp;
      SUM += tmp;
      n--;
      if(prime_p(tmp))
        LCM *= tmp;
    }
    tmp++;
  }
}

int main(){
  int N;
  cin >> N;
  make(N-1);
  NN[N-1] = lcm(LCM, SUM) - SUM;

  for(int i=0; i<N; i++)
    cout << NN[i] << ' ';
  cout << endl;

  return 0;
}

