    cin >> N;

    if (N == 3) { cout << "2 5 63\n"; return 0; }

    vi even, odd;
    for (int v = 1; v <= 30000; v++) {
        if (v % 6 == 3) odd.push_back(v);
        if ((v % 6) % 2 == 0) even.push_back(v);
    }

    vi res;

    reverse(all(odd));

    if (N <= odd.size()) {
        if (N&1) {
            res.push_back(even[even.size() - 1]);
            res.push_back(even[even.size() - 2]);
            res.push_back(even[even.size() - 3]);
            N -= 3;
        } else {
            res.push_back(even[even.size() - 2]);
            res.push_back(even[even.size() - 3]);
            N -= 2;
        }
        for (int i = 0; i < N; i++)
            res.push_back(odd[i]);
    } else {
        res = odd;

        int use_even = N - odd.size();
        for (int i = 0; i < use_even; i++) {
            res.push_back(even[i + (use_even % 3 == 1 ? 2 : 0)]);
        }
    }

    ll sum = 0;
    int g = 0;
    for (int v : res) {
        sum += v;
        g = __gcd(g, v);
        cout << v << " ";
    }
    cout << endl;

    assert(g == 1);
    assert(sum % 6 == 0);

    return 0;
}

