int const MAX = 30 * 1000;

vi ans;
int n;

int gcd(int a, int b) {
	return (a ? gcd(b % a, a) : b);
}

bool check(vi a) {
	int s = 0;
	for (int x : a) {
		s += x;
	}
	set<int> t;
	for (int x : a) {
		t.insert(x);
	}
	if (sz(t) < sz(a)) return false;
	for (int x : a) {
		if (gcd(x, s) == 1) return false;
	}
	return true;
}

int u[MAX + 1];

void solve() {
	vi ans;
	ans.pb(2);
	ans.pb(3);
	u[2] = u[3] = 1;
	for (int i = 2; i <= MAX; i += 2) {
		if (sz(ans) == n) break;
		if (!u[i]) {
			ans.pb(i);
			u[i] = 1;
		}
	}		

	for (int i = 3; i <= MAX; i += 3) {
		if (sz(ans) == n) break;
		if (!u[i]) {
			ans.pb(i);
			u[i] = 1;
		}
	}		
	int s = 0;
	for (int x : ans) {
		s += x;
	}
	if (s % 6 != 0) {
		s -= ans.back();
		ans.pop_back();
		fi(2, MAX) {
			if (!u[i] && (i + s) % 6 == 0 && gcd(i, s) != 1) {
				ans.pb(i);
				break;
			}
		}
	}
	for (int x : ans) {
		printf("%d ", x);
	}
	assert(check(ans));
}

