using namespace std;
void init_ios() {ios_base::sync_with_stdio(false); cin.tie(nullptr);}

class Xorshift {
    uint32_t x, y, z, w;
public:
    Xorshift(uint32_t x = 123456789, uint32_t y = 362436069, uint32_t z = 521288629, uint32_t w = 88675123) : x(x), y(y), z(z), w(w) {}
    uint32_t operator()() {
        uint32_t t;
    	t = x ^ (x << 11);
    	x = y;
        y = z;
        z = w;
    	return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
    }
    uint32_t operator()(uint32_t N) {
        return (*this)() % N;
    }
};

int N;

vector<bool> is_prime;
void f() {
    is_prime.resize(30001, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= 30000; ++i) {
        if (!is_prime[i]) continue;
        for (int j = i * i; j <= 30000; j += i) {
            is_prime[j] = false;
        }
    }
}

int main() {
    cin >> N;

    f();

    Xorshift rnd;

    while (1) {
        vector<int> res {
            2, 5
        };

        vector<bool> check(30001);
        for (auto& v : res) {
            check[v] = true;
        }

        long long sum = 7;
        for (int i = 0; i < N-2; ++i) {
            int rv;
            do {
                rv = rnd(30001);
            } while (check[rv]);
            check[rv] = true;
            sum += rv;
            res.push_back(rv);
        }

        bool f = true;
        for (auto& v : res) {
            if (__gcd(sum-v, (long long)v) != 1) {
                f = false;
                break;
            }
        }

        if (f) {
            for (int i = 0; i < res.size(); i++) {
                if (i) cout << " ";
                cout << res[i];
            }
            cout << endl;
            break;
        }
    }

    // cout << "finish" << endl;

    return 0;
}

