//変数
int N;
//ans2:3の倍数ではない、2の倍数の集合
//ans3:2の倍数ではない、3の倍数の集合
//ans5:2,3の倍数ではない、5の倍数の集合
vector<int> ans, ans2, ans3, ans5;
const int lim = 30000;




//サブ関数
//入力
void input()
{
	cin >> N;

}
void make_set()
{
	FOR(i, 1, lim / 2+1) {
		ans2.push_back(i * 2);
	}
	FOR(i, 1, lim / 3+1) {
		if (i % 2 == 0)continue;
		ans3.push_back(i * 3);
	}
}

void make_ans(int num2, int num3, int num5 = 0)
{
	REP(i, num2)ans.push_back(ans2[i]);
	REP(i, num3)ans.push_back(ans3[i]);
	REP(i, num5)ans.push_back(ans5[i]);
}


//計算
void calc()
{
	make_set();
	FOR(i, 1, 15001)FOR(j, 1, 5001) {
		if (i + j != N)continue;
		if (i % 3 == 1 || j % 2 != 0)continue;
		make_ans(i, j);
		//cerr << i << "  " << j << endl;
		return;
	}
	ans.push_back(2);
	ans.push_back(5);
	ans.push_back(63);
}


//出力
void output()
{
	for (auto num : ans) {
		cout << num << " ";
	}
	cout << endl;
}


//デバッグ
void debug()
{
	int N;
	cin>>N;
}


//メイン関数
int main()
{
	input();
	calc();
	output();
	debug();

	return 0;
}

