void func(int n){
  set<int>st;
  st.emplace(2);st.emplace(3);
  int num=4;
  while(st.size()<n-1){
      if((num%2==0)||(num%3==0))st.emplace(num),++num;
      else ++num;
  }
  ll sum=0;
  for(auto x:st){
    sum+=x;
  }
  while(1){
    ++num;
    if(gcd(sum,num)!=1){
      if((num%2==sum%2)&&(num%3==(3-sum%3)%3)){
        st.emplace(num);
        break;
     }
    }
  }
  for(auto x:st){
    cout<<x<<" ";
  }
  cout<<endl;
}

