void solve(long long N) {
  vl ans;

  if (N == 3) {
    ans.push_back(2);
    ans.push_back(5);
    ans.push_back(63);
  } else if (N == 4) {
    ans.push_back(2);
    ans.push_back(5);
    ans.push_back(20);
    ans.push_back(63);
  } else if (N == 5) {
    ans.push_back(2);
    ans.push_back(5);
    ans.push_back(20);
    ans.push_back(30);
    ans.push_back(63);
  } else {
    ll cnt = 0;
    ll i = 0;
    ll m = 2;
    while (cnt < N) {
      ans.push_back(6 * i + m);
      cnt++;

      if (cnt == N) {
        break;
      }

      if (m == 0) {
        m = 2;
      } else if (m == 2) {
        m = 3;
      } else if (m == 3) {
        m = 4;
      } else if (m == 4) {
        i++;
        m = 0;
      }
    }

    ll sum = 0;
    rep(n, N) { sum += ans[n]; }
    ll rest = sum % 6;
    if (rest == 2) {
      ans[4] = ++i * 6;
    }
    if (rest == 3) {
      ans[5] = ++i * 6;
    }
    if (rest == 5) {
      ans[5] = ++i * 6 + 4;
    }
  }

  rep(n, N) {
    cout << ans[n];
    if (n != N - 1) {
      cout << " ";
    }
  }
  cout << endl;
}

