inline int gcd(const int &a, const int &b) {
	if (!b) return a;
	return gcd(b, a%b);
}

int main() {
	for (int i = 1; i <= 30000; i++) {
		if (i % 2 == 0 || i % 3 == 0) a[sz++] = i;
	}
	scanf("%d", &n);
	srand((unsigned int)(new char));
	while (true) {
		random_shuffle(a, a+sz);
		int sum = 0;
		int x = a[0];
		for (int i = 0; i < n; i++) {
			sum += a[i];
			x = gcd(x, a[i]);
		}
		if (x != 1) continue;
		bool flag = true;
		for (int i = 0; i < n; i++) {
			x = gcd(a[i], sum-a[i]);
			if (x == 1) {
				flag = false;
				break;
			}
		}
		if (flag) {
			for (int i = 0; i < n; i++) {
				printf("%d%c", a[i], " \n"[i+1 == n]);
			}
			return 0;
		}
	}
	return 0;
}

