      for(int i=2;i<=lim;i+=2) {
        ret[pos++] = i;
      }
      for(int i=3;i<=lim && pos<n;i+=3) {
        if(i%2==0) continue;
        ret[pos++] = i;
      }
    }
  }
  int sum = 0;
  for(int i=0;i<n;++i) {
    sum += ret[i];
  }
  int u = ret[0];
  for(int i=0;i<n;++i) {
    assert(ret[i]<=lim);
    assert(gcd(sum-ret[i],ret[i])!=1);
    u = gcd(u,ret[i]);
  }
  assert(u==1);
  for(int i=0;i<pos;++i) {
    printf("%d\n", ret[i]);
  }
}

