ll gcd(ll a, ll b) {
    return b ? gcd(b, a % b) : a;
}

const int MAX = 30000;

bool check(vi a) {
    int old = sz(a);

    sort(all(a));
    a.resize(unique(all(a)) - a.begin());

    if  (sz(a) != old) {
        eprintf("found some same elements\n");
        return 0;
    }

    ll S = accumulate(all(a), 0ll);
    forn(i, n) {
        if  (a[i] > MAX) {
            eprintf("too big\n");
            return 0;
        }
        if  (gcd(a[i], S) == 1) {
            eprintf("a[i]=%d, S=%lld, gcd=%lld\n", a[i], S, gcd(S, a[i]));
            return 0;
        }
    }
    ll g = a[0];
    forn(i, sz(a)) {
        g = gcd(g, a[i]);
    }
    if  (g != 1) {
        eprintf("whole g=%lld\n", g);
        return 0;
    }
    return 1;
}


vi old_solve() {
    if  (n == 3) {
        return {2, 5, 63};
    }

    vi cands;
    for (int i = 1; i <= MAX / 2; ++i) {
        cands.pb(i);
    }

    while (1) {
        random_shuffle(all(cands));
        vi as{cands.begin(), cands.begin() + (n - 2)};

        sort(all(as));
        assert(unique(all(as)) - as.begin() == sz(as));

        ll sum = accumulate(all(as), 0ll);
        eprintf("sum = %lld\n", sum);
        int p = 4;
        for (; (p % 2 == 0 || p % 3 == 0 || sum % p != 0) && p < sum; ++p) {}
        if  (sum == p || 3 * p > MAX) {
            eprintf("bad sum, go on\n");
            continue;
        }

        assert(p % 2 != 0);
        assert(p % 3 != 0);

        eprintf("found prime = %d\n", p);

        vi ans;
        ans.pb(p);
        ans.pb(3 * p);
        for (int a : as) {
            ans.pb(2 * a);
        }

        assert(check(ans));

        return ans;

        break;
    }

    return {};
}

vi solve2() {
    if  (n <= 10000) {
        return old_solve();
    }

    vi vals;
    for (int i = 4; i <= MAX; ++i) {
        if  (i % 2 == 0 || i % 3 == 0) {
            vals.pb(i);
        }
    }

    while (1) {
        random_shuffle(all(vals));

        vi a{vals.begin(), vals.begin() + (n - 2)};

        a.pb(2);
        a.pb(3);

        if  (!check(a)) {
            continue;
        }

        return a;
    }
}

