int main() {
	std::vector<int> r;
	for (int i = 0; i < 30; i++) if (i % 2 == 0 || i % 3 == 0 || i % 5 == 0) r.push_back(i);
	int n = ri();
	std::deque<int> res;
	for (int i = 0; i + 1 < n; i++) res.push_back(i / r.size() * 30 + r[i % r.size()]);
	res.pop_front();
	int64_t sum = std::accumulate(res.begin(), res.end(), 0LL);
	bool b_flag = false;
	for (int i = 0; i < (int) r.size(); i++) {
		for (int j = 0; j < i; j++) {
			if (!((r[i] + r[j] + sum) % 30)) {
				int base = (res.back() + 30) / 30 * 30;
				res.push_back(base + r[j]);
				res.push_back(base + r[i]);
				b_flag = true;
				break;
			}
		}
		if (b_flag) break;
	}
	assert(res.size() == n);
	for (auto i : res) std::cout << i << " ";
	std::cout << std::endl;

	return 0;
}

