  int n;
  cin >> n;
  if (n == 3) {
    cout << "2 5 63\n";
    return 0;
  }
  set<int> s{2, 3, 4, 9};
  const int C = 30000;
  vector<int> s2, s3, s6;
  for (int i = 1; i <= C; ++i) {
    if (s.count(i)) {
      continue;
    }
    if (i % 6 == 0) {
      s6.push_back(i);
    } else if (i % 2 == 0) {
      s2.push_back(i);
    } else if (i % 3 == 0) {
      s3.push_back(i);
    } else {
    }
  }
  while (!s2.empty()) {
    ll sum = s2.back();
    int i = s2.size() - 1;
    while (i > 0 && sum % 6 != 0) {
      sum += s2[--i];
    }
    assert(sum % 6 == 0);
    if ((int) s.size() + (int) s2.size() - i > n) {
      break;
    }
    for (int j = i; j < (int) s2.size(); ++j) {
      s.insert(s2[j]);
    }
    s2.resize(i);
  }
  while (s3.size() >= 2 && (int) s.size() + 2 <= n) {
    for (int iter = 0; iter < 2; ++iter) {
      s.insert(s3.back());
      s3.pop_back();
    }
  }
  while (!s6.empty() && (int) s.size() < n) {
    s.insert(s6.back());
    s6.pop_back();
  }
  ll sum = 0;
  for (int x : s) {
    sum += x;
  }
  assert(sum % 6 == 0);
  assert((int) s.size() == n);
  for (int x : s) {
    cout << x << ' ';
  }
  cout << '\n';
}

