bool validate(vi s, size_t n) {
  // 1. all elements are positive and no more than 30,000.
  for (int a : s) {
    if (a <= 0 or a > 30000) return false;
  }

  // 2. elements in s are distinct.
  if (s.size() != n) return false;
  sort(all(s));
  s.erase(unique(all(s)), s.end());
  if (s.size() != n) return false;

  // 3. check gcd of all elements.
  ll gcd_s = s[0];
  for (int a : s) {
    gcd_s = gcd(a, gcd_s);
  }
  if (gcd_s != 1) return false;

  // 4. s is special set.
  ll sum = 0;

  for (int a : s) sum += a;
  for (int a : s) {
    if (gcd(a, sum-a) == 1) return false;
  }
  return true;
}

