#include <cstdio>
#define ll long long int

int calcgcd(int m, int n){
    if ((m == 0) || (n == 0)){
        return 0;
    }
    while(m != n){
        if (m > n){
            m = m - n;
        }else{
            n = n - m;
        }
    }
    return m;
}

int *derive(int N){
    int * result = new int[N];
    if(N == 3){
        result[0] = 2;
        result[1] = 5;
        result[2] = 63;
        return result;
    }

    int* prevresult = derive(N - 1);
    ll prevsum = 0;
    for(int i = 0; i < N - 1; i++){
        result[i] = prevresult[i];
        prevsum += result[i];
    }
    result[N - 1] = 0;

    for(ll i = 30000; i > 1; i--){
        if(calcgcd(prevsum, i) < 2){
            continue;
        }
        int flag = 0;
        for(int j = 0; j < N - 1; j++){
            if(calcgcd(result[j], i) == 1){
                flag = 1;
            }
            if(result[j] == i){
                flag = 0;
                break;
            }
        }
        if(flag == 1){
            result[N - 1] = i;
            return result;
        }else{
            continue;
        }
    }

}

int main(void){
    int N;
    scanf("%d", &N);
    int *result = derive(N);
    for(int i = 0; i < N - 1; i++){
        printf("%d ", result[i]);
    }
    printf("%d\n", result[N - 1]);

    return 0;
}

