const int INF = 1e15;

int gcd(int a, int b){
    if(a < b) swap(a, b);
    if(b == 0) return a;
    return gcd(b, a % b);
}

signed main(){
    int n, sum = 0;
    cin >> n;
    vector<int> ans;
    for(int i = 2; i <= 30000; i++){
        if(i % 2 == 0 || i % 3 == 0 || i % 5 == 0){
            if(ans.size() < n - 2){
                ans.push_back(i);
                sum += i;
            }
        }
    }
    int last = ans.back();
    for(int i = last + 1; i <= 30000; i++){
        if(!(i % 2 == 0 || i % 3 == 0 || i % 5 == 0)) continue;
        for(int j = i + 1; j <= 30000; j++){
            if(j % 2 == 0 || j % 3 == 0 || j % 5 == 0){
                if((i + j + sum) % 30 == 0){
                    ans.push_back(i);
                    ans.push_back(j);
                    sum += i + j;
                    j = INF; i = INF;
                }
            }
        }
    }
    int G = ans[0];
    rep(i, 1, n) G = gcd(G, ans[i]);
    assert(G == 1);
    assert(ans.size() == n);
    for(int ii = 0; ii < ans.size(); ii++){
        int tmp = gcd(ans[ii], sum - ans[ii]);
        assert(tmp != 1);
        if(ii) cout << ' ';
        cout << ans[ii];
    }
    cout << endl;
}

