		for (int b=0;b<a;b++) {
			for (int c=0;c<min((int)pool.size(),LIM);c++) {
				for (int d=0;d<c;d++) {
					ll ch=pool[c]+pool[d]-(v[a]+v[b]);
					if ((sum+ch)%6==0) {
						vll newans;
						for (auto &w:v) {if (w!=v[a]&&w!=v[b]) newans.PB(w);}
						newans.PB(pool[c]); newans.PB(pool[d]);
						go(newans);
					}
				}
			}
		}
	}
	assert(0);
}

