void out_ans(vector<int> ret) {
    for (int i = 0; i < ret.size(); i++) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << ret[i];
    }
    std::cout << std::endl;
}

void solve(long long N){
    if (N == 3) {
        std::cout << 2 << ' ' << 5 << ' ' << 63 << std::endl;
    } else {
        vector<int> ret;
        ret.push_back(2);
        ret.push_back(4);
        ret.push_back(3);
        ret.push_back(9);
        N -= 4;
        if (N==0) {
            out_ans(ret); return;
        }
        if (N%2 == 1) {
            ret.push_back(30000);
            N--;
        }
        if (N==0) {
            out_ans(ret); return;
        }
        int j = 4;
        for (int i = 0; i < 4999; i++) {
            ret.push_back((j)*2);
            ret.push_back((j+1)*2);
            j += 3;
            N -= 2;
            if (N==0) {
                out_ans(ret); return;
            }
        }
        j = 5;
        for (int i = 0; i < 2499; i++) {
            ret.push_back((j)*3);
            ret.push_back((j+2)*3);
            j += 4;
            N -= 2;
            if (N==0) {
                out_ans(ret); return;
            }
        }
        for (int i = 0; i < 4999; i++) {
            ret.push_back((i+1)*6);
            N -= 1;
            if (N==0) {
                out_ans(ret); return;
            }
        }
        ret.push_back(30000);
        out_ans(ret); return;
    }
}

