int pri[N];
int getprime(int x,int tot=0) {
    mem(prime,1),prime[1]=0;
    FOR(i,2,x) {
        if(prime[i])pri[++tot]=i;
        FOR(j,1,tot) {
            if(i*pri[j]>x)break;
            prime[i*pri[j]]=0;
            if(i%pri[j]==0)break;
        }
    }
    return tot;
}

