std::vector<bool> Eratosthenes( int N )
{
    std::vector<bool> is_prime(N + 1, true);
    std::vector<int> P;
    for( int i = 2; i <= N; i++ )
    {
        if( is_prime[ i ] )
        {
            for( int j = 2 * i; j <= N; j += i )
            {
                is_prime[ j ] = false;
            }
            P.emplace_back( i );
        }
    }
    is_prime[0] = false;
    is_prime[1] = false;
    return is_prime;
}

int main() {
    int n;
    cin >> n;

    vector<bool> v = Eratosthenes(30000);
    vector<int> ans;
    if(n % 2 == 1){
        for(int i = 1;;i++){
            if(i % 2 == 1 && v[i]){
                ans.push_back(i);
                if(ans.size() >= n)break;
            }
        }
    }else{
        ans.push_back(2);
        ans.push_back(3);
        int one = 0;
        int two = 0;
        for(int i = 4;;i++){
            if(one >= (n - 2) / 2 && two >= (n - 2) / 2)break;
            if(i % 3 == 1 && v[i] && one < (n - 2) / 2){
                one++;
                ans.push_back(i);
            }
            if(i % 3 == 2 && v[i] && two < (n - 2) / 2){
                two++;
                ans.push_back(i);
            }
        }
    }
    for(int i = 0;i < ans.size();i++){
