		for (size_t i = 2; i <= n/6 +1; i++) {
			v.push_back(i * 6);
			v.push_back(i * 6 + 2);
			v.push_back(i * 6 + 3);
			v.push_back(i * 6 + 4);
		}

		std::vector<int> ans;
		int sum = 0;
		for (size_t i = 0; i < n; i++) {
