    FOR(i,0,(int)prime.size()){
      if(prime[i]>num){
        break;
      }else if(num%prime[i]==0&&num/prime[i]!=S){
        if(SE.find(num/prime[i])==SE.end()){
          S+=num/prime[i];
          SE.insert(num/prime[i]);
          F=false;
