LL N;

LL ans[20000];

void solve(){
	if(N==3){
		ans[0] = 2;ans[1] = 5;ans[2] = 63;
		return;
	}
	ans[0] = 2;
	ans[1] = 4;
	ans[2] = 3;
	ans[3] = 9;
	int counter = 0;
	LL two = 6;
	LL three = 12;
	LL six = 6;

	auto add_six= [&](int length){
		ans[length] = six;
		six+=6;
	};
	auto add_two= [&](int length){
		if(two<=30000){
			if(two%3==0) two+=2;
			ans[length] = two;
			two+=2;
			if(two%3==0) two+=2;
			if(two<=30000){
				ans[length+1] = two;
				two+=2;
			}
			else{
				add_six(length);
				add_six(length+1);
			}
		}else{
			add_six(length);
			add_six(length+1);
		}
	};
	auto add_three= [&](int length){
		if(three<=30000){
			if(three%2==0) three+=3;
			ans[length] = three;
			three+=3;
			if(three%2==0) three+=3;
			if(three<=30000){
				ans[length+1] = three;
				three+=3;
			}
			else{
				add_six(length);
				add_six(length+1);
			}
		}else{
			add_six(length);
			add_six(length+1);
		}
	};
	if(N%2==0){
		for(int length = 4;length<N;length+=2){
			if(counter%2==0){
				add_two(length);
			}else{
				add_three(length);
			}
			counter++;
		}
	}else{
		N--;
		for(int length = 4;length<N;length+=2){
			if(counter%2==0){
				add_two(length);
			}else{
				add_three(length);
			}
			counter++;
		}
		N++;
		add_six(N-1);
	}
}

int main(){
    cin >> N;

    solve();

    for(int i=0;i<N;i++) cout << ans[i] << " ";
    cout << endl;
    return 0;
}

