bool check(ll n){
  //2の倍数をk個
  for(ll k=1;k<n;k++){
    if((n-2*k)%3!=0)continue;
    ll l=(n-2*k)/3;
    if(!(1<=3*l&&3*l<=15000))continue;
    if(!(1<=2*k&&2*k<=5000))continue;
    //cout<<k<<" "<<l<<endl;
    rep(i,3*l)cout<<2*(i+1)<<" ";
    rep(i,2*k)cout<<3*(2*i+1)<<" ";
    cout<<endl;
    return true;
  }
  return false;
}

