        if (i % 3 == 0 && i % 6 != 0) {
            answer.emplace_back(i);
            n--;
        }
        if (n == 0) break;
    }
    rep(i,0,N) {
        cout << answer[i] << (i == N-1 ? "\n" : " ");
    }
}

