  // gcd(ans[i], \sum_{j = 0} ^ {ans.size - 1} - ans[i]) != 1
  // 0 <= i < j < ans.size で gcd(ans[i], ans[j]) == 1となる i, jが存在する.
  // ans[i] <= 30000
  // 以上.
  // 2の倍数と3の倍数を使って考えてみる.(なぜ2,3の倍数なんだと聞かれたら、めっちゃ考えた結果良さそうだったからとしか...)
  // 2の倍数で6の倍数ではない数が偶数個、3の倍数で6の倍数ではない数を偶数個用意すると条件を満たすことができる
  // この条件のもとで、6の倍数はいくつ入れても良い.
  // 3000以下の該当する数の個数の合計は丁度20000なのでok
  // てかもうなんか説明すんのめんどくさい...
  cin >> n;
  if (n == 3) {
    cout << 2 << " " << 5 << " " << 63 << endl;
    return 0;
  }
  for (int i = 1; 2 * i <= 30000; i++) {
    if (2 * i % 6 == 0) continue;
    two.push_back(2 * i);
  }
  for (int i = 1; 3 * i <= 30000; i++) {
    if (3 * i % 6 == 0) continue;
    three.push_back(3 * i);
  }
  for (int i = 1; i * 6 <= 30000; i++) {
    six.push_back(6 * i);
  }
  for (int i = 0; i < (int) three.size(); i += 2) {
    if ((int) ans.size() + 4 > n) break;
    ans.push_back(two[i]);
    ans.push_back(two[i + 1]);
    ans.push_back(three[i]);
    ans.push_back(three[i + 1]);
  }
  for (int i = (int) three.size(); i < (int) two.size(); i += 2) {
    if ((int) ans.size() + 2 > n) break;
    ans.push_back(two[i]);
    ans.push_back(two[i + 1]);
  }
  rep(i, 0, (int) six.size()) {
    if ((int) ans.size() == n) break;
    ans.push_back(six[i]);
  }
  rep(i, 0, (int) ans.size()) {
    cout << ans[i];ln(i, (int) ans.size());
  }
#ifdef  LOCAL_DEFINE
  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << "s." << endl;
#endif
  return 0;
}

