void show(int start, int count, const std::vector<int> &target) {
	while (count != 0) {
		if (std::find(target.begin(), target.end(), start % 12) != target.end()) {
			std::cout << start;
			--count;
			if (count != 0) std::cout << ' ';
		}
		++start;
	}
}
