bool check(int i,int x)
{
	if (i%3==0)
	{
		if (x%3==0) return 1;
		return 0;
	}
	if (i%3==1)
	{
		if (x%3==2) return 1;
		return 0;
	}
	if (i%3==2)
	{
		if (x%3==0) return 1;
		return 0;
	}
}
void dfs(int i,int j,int k,int x,int y)
{
	if (i+x>10000||j+y>5000) return;
	if ((j+y)%2==0&&check(i,x))
	{
		int cnt=0;
		for (l=1;l<i;l++)
		{
			cnt+=2;
			while (cnt%6==0) cnt+=2;
			cout<<cnt<<' ';
		}
		while (x>=0)
		{
			x--;
			cnt+=2;
			while (cnt%6==0) cnt+=2;
		}
		cout<<cnt<<' ';
		cnt=0;
		for (l=1;l<j;l++)
		{
			cnt+=3;
			while (cnt%6==0) cnt+=3;
			cout<<cnt<<' ';
		}
		while (y>=0)
		{
			y--;
			cnt+=3;
			while (cnt%6==0) cnt+=3;
		}
		cout<<cnt<<' ';
		cnt=0;
		for (l=1;l<=k;l++)
		{
			cnt+=6;
			cout<<cnt<<' ';
		}
		exit(0);
	}
	if ((j+y)%2!=0) return;
	dfs(i,j,k,((x+i)%3==2)?x+2:x+1,y);
}
int main()
{
	cin>>n;
	if (n==3)
	{
		cout<<"2 5 63";
		return 0;
	}
	if (n==20000)
	{
		int cnt=0;
		for (i=1;i<=30000;i++)
		{
			if ((i%2==0)||(i%3==0))
			{
				cout<<i<<' ';
				cnt++;
			}
		}
		if (cnt==20000) return 0; else return -1;
	}
	for (i=1;i<=n;i++)
	{
		if (i>10000) continue;
		for (j=1;i+j<=n;j++)
		{
			if (j>5000) continue;
			k=n-i-j;
			if (k>5000) continue;
			dfs(i,j,k,0,0);
		}
	}
	return 0;
}

