long long gcd(long long a, long long b) {
    return (b == 0 ? a : gcd(b, a % b));
}

void solve(int N) {
    vector<long long> a(N);
    a[0] = 3;
    a[1] = 5;
    for (int i = 2; i < N; i++) {
        a[i] = (i + 2) * 4;
    }

    for (long long i = a[N - 1]; ; i += 2) {
        a[N - 1] = i;
        auto sum = accumulate(a.begin(), a.end(), 0LL);
        bool flag = true;
        for (int j = 0; j < N; j++) {
            if (gcd(a[j], sum - a[j]) == 1) {
                flag = false;
                break;
            }
        }

        if (flag) {
            assert(a[N - 1] <= 30000);
            while (a[N - 1] > 30000) {
                if (sum % 4 == 0) {
                    a[N - 1] -= sum / 2;
                    sum /= 2;
                } else {
                    a[N - 2] += 2;
                    sum += 2;
                }
            }
            for (int j = 0; j < N; j++) {
                cout << a[j] << " ";
            }
            cout << endl;
            return;
        }
    }
}

