const int maxN = 3 * (int)1e4 + 10;
bool ok[maxN];
vector < int > pr;
bool get_[100];
bool used[maxN];
int main() {
    srand(time(0));
    ios_base::sync_with_stdio(false);
    //freopen("input.txt", "r", stdin);
    for (int i = 2; i < 7; i++) {
        if (get_[i]) continue;
        pr.push_back(i);
        for (int j = 2 * i; j < 7; j += i) get_[j] = true;
    }
    cin >> n;
    for (int j = 0; j < pr.size(); j++) {
        int p = pr[j];
        for (int k = p; k < maxN; k += p) ok[k] = true;
    }
    int cur = 0;
    int sum = 0;
    vector < int > ans;
    for (int i = 1; i < maxN; i++) {
        if (cur == n - 1) break;
        if (ok[i]) {
            used[i] = true;
            sum += i;
            ans.push_back(i);
            cur++;
        }
    }
    //for (int j = 0; j < pr.size(); j++) cout << pr[j] << " ";
    //cout << sum << endl;
    while (ans.size() != n) {
        //for (int i = 0; i < ans.size(); i++) cout << ans[i] << " ";
        //cout << endl;
        for (int i = 3 * (int)1e4; i >= 3 * (int)1e4 - 1000; i--) {
            int t = sum + i;
            if (!ok[i]) continue;
            if (used[i]) continue;
            bool okk = true;
            for (int j = 0; j < pr.size(); j++) {
                if ((t % pr[j]) != 0) {
                    okk = false;
                    break;
                }
            }
            if (okk) {
                ans.push_back(i);
                break;
            }
        }
        if (ans.size() != n) {
            used[ans.back()] = false;
            sum -= ans.back();
            ans.pop_back();
            for (int j = 3 * (int)1e4; ;j--) {
                if (ok[j] && !used[j]) {
                    ans.push_back(j);
                    used[j] = true;
                    sum += j;
                    break;
                }
            }
        }
    }
    for (int i = 0; i < ans.size(); i++) cout << ans[i] << " ";
}

