long long gcd(long long a, long long b) {
    return (b == 0 ? a : gcd(b, a % b));
}

void solve(int N) {
    vector<long long> a(N);
    a[0] = 2;
    a[1] = 3;
    for (int i = 2; i < N - 1; i++) {
        a[i] = a[i - 1] + a[i - 2];
    }

    for (long long i = a[N - 2] + 1; ; i++) {
        a[N - 1] = i;
        auto sum = accumulate(a.begin(), a.end(), 0LL);
        bool flag = true;
        for (int j = 0; j < N; j++) {
            if (gcd(a[j], sum - a[j]) == 1) {
                flag = false;
                break;
            }
        }

        if (flag) {
