inline int popc(int x)
{
    return __builtin_popcount(x);
}

vector<int> f(vector<int> b, int n, int md)
{
    b.push_back(15);

    int to = (1 << sz(b));
    for(int i = 0; i < to; ++i)
    {
        if(popc(i) != n)
        {
            continue;
        }

        vector<int> v;
        for(int j = 0; j < sz(b); ++j)
        {
            if((i >> j) & 1)
            {
                v.push_back(b[j]);
            }
        }

        if(accumulate(all(v), 0) % md == 0)
        {
            return v;
        }
    }

    assert(false);
    return{};
}

