int gcd(int m, int n) {
    if (m < n) {
        std::swap(m, n);
    }
    const int d = m % n;
    const int ret = d ? gcd(n, d) : n;
    const auto idx = static_cast<size_t>(m + n * 30000);
    if (!memed[idx]) {
        mem.set(idx, ret == 1);
        memed.set(idx, true);
    }
    return ret;
}

bool gcdIsOne(int m, int n) {
    if (m < n) {
        std::swap(m, n);
    }
    const auto idx = static_cast<size_t>(m + n * 30000);
    if (memed[idx]) {
        return mem[idx];
    }
    return gcd(m, n) == 1;
}

