    res.push_back(25);
    n -= 2;

    ll a = 1, b = 1.5e4 - 1;
    while (a != b) {
        res.push_back(a << 1);
        res.push_back(b << 1);
        n -= 2;
        if (a >= b)break;
        if (n == 0)goto end;
        a++;
        b--;
    }

    a = 1;
    b = 1e4 - 1;
    while (a != b) {
        res.push_back(a * 3);
        res.push_back(b * 3);
        n -= 2;
        if (a >= b)break;
        if (n == 0)goto end;
        a += 2;
        b -= 2;
    }

    end:
    pa(res);
}

