i64 extgcd(i64 a, i64 b, i64 &x, i64 &y) {
    i64 d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

void solve(){
    i64 N;
    cin >> N;

    if(N==3){
        cout << "2 5 63" << endl;
        return;
    }

    if(N==4){
        cout << "2 5 20 63" << endl;
        return;
    }

    if(N==6){
        cout << "2 5 63 4 10 126" << endl;
        return;
    }

    map<i64,vector<i64>> mp;
    mp[5]={2, 4, 6, 9, 15};
    mp[7]={2, 4, 6, 9, 15, 21, 27};
    mp[8]={2, 4, 6, 8, 10, 12, 9, 15};
    mp[12]={2, 4, 6, 8, 10, 12, 9, 15, 21, 27, 33, 39};

    vector<int> op;
    i64 n=N;
    while(mp.find(n)==mp.end()){
        if(n&1){
            --n;
            op.push_back(0);
        }else{
            n/=2;
            op.push_back(1);
        }
    }

    reverse(begin(op),end(op));

    set<i64> ans;
    for(auto x:mp[n]) ans.insert(x);

    rep(i,0,op.size()){
        if(op[i]==0){
            i64 a=6;
            for(auto x:ans) if(a==x) a+=6;
            ans.insert(a);
        }else{
            i64 d=6;
            while(true){
                bool ok=true;
                for(auto x:ans) if(ans.find(x+d)!=ans.end()){
                    ok=false;
                    break;
                }
                if(ok) break;
                d+=6;
            }
            set<i64> tmp;
            for(auto x:ans) tmp.insert(x+d);
            ans.insert(tmp.begin(),tmp.end());
        }
    }

    i64 i=0;
    for(auto x:ans){
        cout << x;
        if(i==N-1) cout << endl;
        else cout << " ";
        ++i;
    }
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

