	template<std::uint64_t Mod>struct modnum;
	template<class T>constexpr T pow(T base, std::size_t p)
	{
		if (p == 0)
		{
			return T(1);
		}
		else if (p == 1)
		{
			return base;
		}
		else if (p == 2)
		{
			return base * base;
		}
		else if (p % 2 == 0)
		{
			return pow(pow(base, p / 2), 2);
		}
		else
		{
			return pow(pow(base, p / 2), 2)*base;
		}
	}
	template<std::uint64_t Mod>constexpr auto inverse(modnum<Mod> const&);

	template<std::uint64_t Mod>struct modnum
	{
		static constexpr auto mod = Mod;
		std::uint64_t val;
		modnum() = default;
		constexpr modnum(std::uint64_t v):val(v%Mod)
		{

		}

		constexpr auto& clamp()
		{
			val %= mod;
			return *this;
		}

		constexpr auto& operator+=(modnum const& v)
		{
			val += v.val;
			return clamp();
		}
		constexpr auto& operator-=(modnum const& v)
		{
			val += mod - v.val;
			return clamp();
		}
		constexpr auto& operator*=(modnum const& v)
		{
			val *= v.val;
			return clamp();
		}
		constexpr auto& operator/=(modnum const& v)
		{
			return operator*=(inverse(v));
		}
	};
#define MAKE_MODNUM_OPERATOR(op)\
	template<std::uint64_t Mod>constexpr auto operator op(modnum<Mod> lhs, modnum<Mod>const& rhs)\
	{\
		return lhs BOOST_PP_CAT(op,=) rhs;\
	}
	MAKE_MODNUM_OPERATOR(+);
	MAKE_MODNUM_OPERATOR(-);
	MAKE_MODNUM_OPERATOR(*);
	MAKE_MODNUM_OPERATOR(/);

	template<std::uint64_t Mod>constexpr auto inverse(modnum<Mod>const& base)
	{
		return pow(base, Mod - 2);
	}

	template<class T>constexpr T gcd(T a, T b)
	{
		return a > b ? gcd(b, a) : a == T() ? b : gcd(b%a, a);
	}

