        return 0;
    }
    else if (n == 4) {
        cout << "2 5 20 63" << endl;
        return 0;
    }
    vector<ll> ans(n);
    ll acnt = 0, bcnt = 0, idx = 0;
    rep(i, n) {
        if (i % 2 == 0) {
            acnt++;
            if (acnt % 3 == 0) acnt++;
            ans[i] = acnt * 2;
            idx = i;
        }
        else {
            bcnt++;
            if (bcnt % 2 == 0) bcnt++;
            ans[i] = bcnt * 3;
        }
    }
    if (bcnt % 2 == 1) {
        bcnt++;
        if (bcnt % 2 == 0) bcnt++;
        ans[idx] = bcnt * 3;
