bool validate(vector<int>&v, int n) {
  if( v.size() != (size_t)n ) {
    cerr << "!!" << n << " > " << v.size() << endl;
    return false;
  }
  sort(v.begin(), v.end());
  ll tot = v[0], g = v[0];
  for(int i=1; i<n; i++) {
    if( v[i] == v[i-1] ) {
      cerr << "x2 :" << v[i] << endl;
      return false;
    }
    tot += v[i];
    g = __gcd(g, (ll)v[i]);
  }
  if( g > 1 ) {
    cerr << "G" << g << endl;
    return false;
  }
  for(int i=0; i<n; i++) {
    if( v[i] > 30000 ) return false;
    if( __gcd((ll)v[i], tot-v[i]) == 1 ) {
      cerr << v[i] << ',' << tot-v[i]
	   << ':' << __gcd((ll)v[i], tot-v[i]) << endl;
      return false;
    }
  }
  return true;
}

