    int nmax(2), spare(0);

    while (pare.size() + impare.size() < n) {
        if (nmax % 2 != 0 && nmax % 3 != 0)
            nmax++;
        if (nmax & 1)
            impare.insert(nmax++);
        else {
            spare += nmax;
            pare.insert(nmax++);
        }
    }

    if (impare.size() % 2 != 0) {
        int x = *pare.rbegin();
        pare.erase(x);
        spare -= x;
        while (nmax % 3 != 0)
            nmax++;
        impare.insert(nmax++);
    }

    if (spare % 3 != 0) {
        int x = *pare.rbegin();
        pare.erase(x);
        spare -= x;
        while (nmax % 2 == 1 || (spare + nmax) % 3 != 0)
            nmax++;
        pare.insert(nmax);
    }

    for (auto i : pare)
        cout << i << ' ';
    for (auto i : impare)
        cout << i << ' ';

    return 0;
