int n;
LL s;

bool compatible(int m){
    if(m <= 1) return false;
    if(m > 30000) return false;
    if(m % 2 == 0) return true;
    if(m % 3 == 0) return true;
    if(m % 5 == 0) return true;
    if(m % 7 == 0) return true;
    if(m % 11 == 0) return true;
    if(m % 13 == 0) return true;
    if(n >= 180 and m % 17 == 0) return true;
    if(n >= 900 and m % 19 == 0) return true;
    //~ if(n >= 7000 and m % 23 == 0) return true;
    //~ if(n >= 10000 and m % 29 == 0) return true;
    return false;
}

void solve(int n){
    srand(time(NULL));
    s = 30030;
    if(n == 3){
        cout << "2 3 25\n";
        return;
    }
    if(n >= 180) s *= 17;
    if(n >= 900) s *= 19;
    if(n >= 3900) s *= 2;
    if(n >= 5600) s *= 3;
    if(n >= 9700) s *= 3;
    if(n >= 16800) {s *= 3; s/=2;}
    //~ if(n >= 10000) s *= 29;

    LL x = s - 5;
    LL y = x;
    LL med = x / (n-2);
    set<int> ans = {2, 3};
    int l = med - 1;
    int r = med;
    while((int)ans.size() + 2 < n){
        //~ cerr << ans.size() << ' ' << l  << ' ' << r << endl;
        if(med - l < r - med){
            assert(l > 3);
            if(not compatible(l)) l--;
            else{
                ans.insert(l);
                y -= l;
                l--;
            }
        }else{
            assert(r <= 30000);
            if(not compatible(r)) r++;
            else{
                ans.insert(r);
                y -= r;
                r++;
            }
        }
    }

    for(LL f=4; f<=30000; f++){
        if(not compatible(f)) continue;
        if(not compatible(y - f)) continue;
        if(ans.count(f)) continue;
        if(ans.count(y - f)) continue;
        ans.insert(f);
        ans.insert(y - f);
        break;
    }

    for(int a:ans) cout << a << ' ';
    cout << '\n';
    return;
}

