long long gcd(long long a, long long b) {
    return (b == 0 ? a : gcd(b, a % b));
}

void solve(int N) {
    vector<long long> a(N);
    a[0] = 3;
    a[1] = 5;
    for (int i = 2; i < N; i++) {
        a[i] = (i + 2) * 4;
    }

    for (long long k = a[N - 2]; ; k += 2) {
        a[N - 2] = k;
        for (long long i = k + 2; i<= 30000; i += 2) {
            a[N - 1] = i;
            auto sum = accumulate(a.begin(), a.end(), 0LL);
            bool flag = true;
            for (int j = 0; j < N; j++) {
                if (gcd(a[j], sum - a[j]) == 1) {
                    flag = false;
                    break;
                }
            }

            if (flag) {
                assert(a[N - 1] <= 30000);
                for (int j = 0; j < N; j++) {
                    cout << a[j] << " ";
                }
                cout << endl;
                return;
            }
        }
    }
}

int main() {
    int N;
    cin >> N;
    if (N == 3) {
        cout << "2 3 25" << endl;
        return 0;
    }
    solve(N);
}

