ll const Cons = 30000;
void solve(ll N){

    ll c1,c2;
    c1 = -1; c2 = -1;

    for(ll m1=1; 2*(3*m1-1)<=Cons; m1++){
        c1 = 3*m1 -1;
        c2 = N - c1;
        if(c2%2==0 && (c1*c2 != 0)){break;}
        else c2 = -1;
    }

    if(c2 == -1){
        for(ll m1=1; 2*3*m1<=Cons; m1++){
            c1 = 3*m1;
            c2 = N - c1;
            if(c2%2==0 && (c1*c2 != 0)){break;}
            else c2 = -1;
        }
    }

    // cout<<c1<<" "<<c2<<endl;
    assert(c2 < 0);
    rep(i,c1) cout<<2*(i+1)<<" ";
    rep(i,c2) cout<<3*(2*i+1)<<" ";
    puts("");
}
