bool valid(int x, int y){
	if( x == 0 || y == 0 ) return false;
	int xlim = 10000, ylim = 5000, zlim = 5000;
	if( x%2 == 1 ){
		zlim -= 1; x--;
	}
	x -= xlim; y -= ylim;
	x = max(x,0); y = max(y,0);
	if( x+y <= zlim ) return true;
	return false;
}

