int n;
int res[30000];

int gcd(int a, int b)
{
    int r = a % b;
    if (r == 0)
        return b;

    return gcd(b, r);
}

int lcd(int a, int b)
{
    int g = gcd(a, b);
    return a / g * b;
}

int main(void)
{
    cin >> n;

    res[0] = 2;
    res[1] = 3;
    res[2] = 25;
    lin sum = 30;
    int sp[300000];

    loop(i, 3, n)
    {
        rep(j, i)
        {
            int g = gcd(sum, res[j]);
            if (g == res[j])
                sp[j] = res[j];
            else
                sp[j] = res[j] / g;
        }

        int l = 1;
        rep(j, i)
        {
            l = lcd(l, sp[j]);
        }

        res[i] = l - (sum % l);
        sum += res[i];
    }

    rep(i, n - 1)
    {
        cout << res[i] << " ";
    }
    cout << res[n - 1] << endl;

    return 0;
}

