	vector<ll> t, h, f, s, ans;
	rep(i, 1, 5000){
		t.push_back(6*i-4);
		h.push_back(6*i-3);
		f.push_back(6*i-2);
		s.push_back(6*i);
	}

	ll n;
	cin >> n;
	if(n == 3){cout << "2 5 63" << endl; return 0;}
	if(n == 4){cout << "2 5 20 63" << endl; return 0;}

