	ll ti = 0;
	ll hi = 0;
	ll fi = 0;
	ll si = 0;
	if(m <= 6){si = m;}
	if(6 < m && m <= 11){ti = 3; hi = 2; si = m-ti-hi;}
	if(11 < m && m <= 16){ti = 6; hi = 4; si = m-ti-hi;}
	if(16 < m && m <= 21){ti = 6; hi = 6; fi = 3; si = m-ti-hi-fi;}
