	zep(i, 0, hi){ans.push_back(h[(n/24)*6+i]);}
	zep(i, 0, fi){ans.push_back(f[(n/24)*6+i]);}
	zep(i, 0, si){ans.push_back(s[(n/24)*6+i]);}

	zep(i, 0, ans.size()){cout << ans[i] << " ";}cout << endl;
	return 0;
}

