const int MAX_VALUE = 30000;

int GCD(int x, int y)
{
	return (x == 0 ? y : GCD(y % x, x));
}

bool validate(int n, vector<int> v)
{
	if(len(v) != n)
		return false;

	for(auto& x: v)
	{
		if(x < 1 || x > MAX_VALUE)
			return false;
	}

	sort(v.begin(), v.end());

	for(int i = 0; i + 1 < len(v); ++i)
	{
		if(v[i + 1] == v[i])
			return false;
	}

	int common_gcd = v.front();	

	for(auto& x: v)
		common_gcd = GCD(common_gcd, x);

	if(common_gcd != 1)
		return false;

	int fsum = 0;

	for(auto& x: v)
		fsum += x;

	for(auto& x: v)
	{
		if(GCD(x, fsum - x) == 1)
			return false;
	}

	DBG("ok");
	return true;
}

void solve()
{
	int n;
	cin >> n;

	if(n == 3)
	{
		cout << "2 5 63" << endl;
		return;
	}

	vector<int> answ;
	int fsum = 0;

	for(int c = 1; c <= MAX_VALUE; ++c)
	{
		if(c % 2 == 0 || c % 3 == 0)
		{
			answ.push_back(c);
			fsum += c;
		}

		if(len(answ) == n)
			break;
	}

	if(fsum % 6 != 0)
	{
		int last = answ.back();
		answ.pop_back();
		fsum -= last;

		int last2 = answ.back();
		answ.pop_back();
		fsum -= last2;

		for(int i = last;; ++i)
		{
			for(int j = last2; j < i; ++j)
			{
				bool ok = true;

				ok &= (fsum + i + j) % 6 == 0;
				ok &= (i % 2 == 0 || i % 3 == 0);
				ok &= (j % 2 == 0 || j % 3 == 0);

				if(ok)
				{
					answ.push_back(j);
					answ.push_back(i);

					goto end;
				}
			}
		}
	}

end:
	cout << answ << endl;

#ifdef __LOCAL
	assert(validate(n, answ));
#endif
}

int main()
{
	fast_io();
	solve();

	return 0;
}

