int gcd(int a, int b){
  if (b>a) swap(a,b);
  if (b==0) return a;
  return gcd(b, a%b);
}

int solve(){
  int n;cin>>n;
  if (n==3){
    cout << "2 5 63" << endl;
    return 0;
  }

  vi ans;
  set<int> st;
  rep(i, 2, 30001){
    if (i%6==2){
      ans.pb(i);
      ans.pb(i+2);
      st.insert(i);
      st.insert(i+2);
    }
    if (i%6==3){
      if (st.find(i)==st.end()){
        ans.pb(i);
        ans.pb(i+6);
        st.insert(i);
        st.insert(i+6);
      }
    }
    if (sz(ans)>=n-1) break;
  }

  rep(i, 2, 30001){
    if (i%6==0){
      ans.pb(i);
    }
    if (sz(ans)==n) break;
  }

  assert(sz(ans)==n);
  rep(i, sz(ans)) cout << ans[i] << (i!=sz(ans)-1 ? " " : "\n");

  int s = accumulate(all(ans), 0LL);
  int g = 0;
  vi c(30001);
  each(el, ans){
    assert(gcd(el, s-el)!=1);
    c[el]++;
    assert(c[el]<=1);
    g = gcd(g, el);
  }
  assert(g==1);

  return 0;
}

