    for (int i=4;i<=30000&&n>1;i+=2){
        //if (n-1==1&&(all&1)==(i&1))continue;
        if (i==30000&&n-1==1&&(all&1)==(i&1))continue;
        n--,a[i]=1,all+=i;
    }
    int l=2;
    while (n>1){
        while (a[l])l++;
        Lcm=lcm(Lcm,l);
        d[++d[0]]=l;
        for (int i=1;(long long)i*l<=30000&&n>1;i++)
            if (!a[i*l]&&!(n-1==1&&(all&1)==((i*l)&1))){
