void solve(int N) {
    vi S(N);
    if (N == 3) {
        S[0] = 2, S[1] = 5, S[2] = 63;
    } else if (N == 4) {
        S[0] = 2, S[1] = 5, S[2] = 20, S[3] = 63;
    } else if (N == 5) {
        S[0] = 2, S[1] = 5, S[2] = 20, S[3] = 30, S[4] = 63;
    } else {
        S.clear();
        int i;
        for (i = 1; sz(S) < N; ++i) {
            if (i % 2 == 0 || i % 3 == 0)S.push_back(i);
        }
        ll sm = accumulate(all(S), 0ll);
        if (sm % 6 == 2) {
            S.erase(S.begin());
            while (i % 6)i++;
            S.push_back(i);
        } else if (sm % 6 == 5) {
            S.erase(S.begin() + 1);
            while (i % 6 != 4)++i;
            S.push_back(i);
        } else if (sm % 6 == 3) {
            S.erase(S.begin() + 1);
            while (i % 6)i++;
            S.push_back(i);
        }
        sm = accumulate(all(S), 0ll);
        assert(sm % 6 == 0);
    }
    rep(i, N) {
        assert(S[i] <= 30000);
        cout << S[i] << (i != N - 1 ? ' ' : '\n');
    }
}

