    ll submin = 1e18;
    srep (xx, 1, 15000) srep (yy, 1, 10000) {
        if (xx * 2LL + yy * 3LL != n) continue;
        ll sub = abs(xx * 2LL - yy);
        if (sub < submin) {
            submin = sub;
            x = xx;
            y = yy;
        }
    }

    x *= 2LL;
    y *= 3LL;
    V<ll> anslist;

    srep (i, 1, y+1) anslist.pb(2LL * i);
    ll cnt = x;
    srep (i, 1, 100000000) {
        ll val = i * 3LL;
        if (val & 1LL) {
            anslist.pb(val);
            cnt--;
        }
        if (!cnt) break;
    }

    if (orig_n != n) {
        rep (i, anslist.size()) {
            if (anslist[i] % 6LL == 0LL) {
                anslist[i] = -1;
                n--;
                if (orig_n == n) break;
            }
        }
