int64_t calcGCD(int64_t a, int64_t b)
{
	while (a)
	{
		b %= a;
		std::swap(a, b);
	}
	return b;
}

bool match(int, int);

int main()
{
	int N;
	scanf("%d", &N);
	std::vector<int> ans;
	const int quo{N / 8}, rem{N % 8};
	for (int i{}; i < quo; i++)
		for (int j{1}; j <= 12; j++)
			if (j % 2 == 0 || j % 3 == 0)
				ans.push_back(12 * i + j);

	if (rem == 1)
		ans.push_back(12 * quo + 2);
	else if (rem == 3)
	{
		if (N == 3)
		{
			ans.push_back(12 * quo + 2);
			ans.push_back(12 * quo + 5);
			ans.push_back(12 * quo + 63);
		}
		else
		{
			ans.push_back(12 * quo + 3);
			ans.push_back(12 * quo + 6);
			ans.push_back(12 * quo + 9);
		}
	}
	else
	{
		for (int set{}; set < (1 << 12); set++)
		{
			if (!match(set, rem)) continue;
			for (int i{}; i < 12; i++)
			{
				if (~set >> i & 1) continue;
				ans.push_back(quo * 12 + i + 1);
			}
			break;
		}
	}
	for (int i{}; i < N; i++)
		printf("%d%c", ans[i], i + 1 == N? '\n': ' ');

	return 0;
}

bool match(int set, int remainder)
{
	for (int i{}; i < 12; i++)
		if ((set >> i & 1) && (i + 1) % 3 != 0 && (i + 1) % 2 != 0)
			return false;
	int count{};
	for (int i{}; i < 12; i++)
		if (set >> i & 1)
			count++;
	if (count != remainder)
		return false;
	int sum{};
	for (int i{}; i < 12; i++)
		if (set >> i & 1)
			sum += i + 1;
	if (sum % 6 != 0) return false;
	int64_t gcd{};
	for (int i{}; i < 12; i++)
		if (set >> i & 1)
			gcd = calcGCD(gcd, i + 1);
	return gcd == 1;
}

