int main()
{
	int N;
	scanf("%d", &N);
	std::vector<int> ans;
	const int quo{N / 8}, rem{N % 8};
	for (int i{}; i < quo; i++)
		for (int j{1}; j <= 6; j++)
			if (j % 2 == 0 || j % 3 == 0)
				ans.push_back(6 * i + j);

	for (int set{}; set < (1 << 12); set++)
	{
		if (!match(set, rem)) continue;
		int sum{};
		for (int i{}; i < 12; i++)
			if (set >> i & 1)
				sum += i + 1;
		if (sum % 6 != 0) continue;

		for (int i{}; i < 12; i++)
		{
			if (~set >> i & 1) continue;
			ans.push_back(quo * 12 + i + 1);
		}
		break;
	}
	for (int i{}; i < N; i++)
		printf("%d%c", ans[i], i + 1 == N? '\n': ' ');

	return 0;
}

bool match(int set, int remainder)
{
	for (int i{}; i < 12; i++)
		if ((set >> i & 1) && (i + 1) % 3 != 0 && (i + 1) % 2 != 0)
			return false;
	int count{};
	for (int i{}; i < 12; i++)
		if (set >> i & 1)
			count++;
	return count == remainder;
}

