unsigned int randxor()
{
    static unsigned int x = 123456789, y = 362436069, z = 521288629, w = 88675123;
    unsigned int t;
    t = (x ^ (x << 11)); x = y; y = z; z = w; return(w = (w ^ (w >> 19)) ^ (t ^ (t >> 8)));
}

void solve(int N) {
    vector<long long> a(N);
    while (true) {
        for (int i = 0; i < N; i++) {
            a[i] = 1;
            while (a[i] % 2 == 1) {
                a[i] = randxor() % 30000;
            }
        }

        int index = randxor() % (N - 1);
        a[index]++;
        a[index + 1]++;

        auto sum = accumulate(a.begin(), a.end(), 0LL);
        bool flag = true;
        for (int j = 0; j < N; j++) {
            if (gcd(a[j], sum - a[j]) == 1) {
                flag = false;
                break;
            }
        }

        if (flag) {
            for (int j = 0; j < N; j++) {
                cout << a[j] << " ";
            }
            cout << endl;
            return;
        }

        a[index]--;
        a[index + 1]--;
    }
}

