}
void solve(int n) {
  int lim = 30000;
  int pos = 0;
  if(n*2<=lim) {
    for(int i=2;i<=lim && pos<n;i+=2) {
      ret[pos++] = i;
    }
  } else {
    if(n&1) {
      for(int i=2;i<=lim;i+=2) {
        if(i==6) continue;
        ret[pos++] = i;
      }
      for(int i=3;i<=lim && pos<n;i+=3) {
        if(i%2==0) continue;
        ret[pos++] = i;
      }
    } else {
      for(int i=2;i<=lim;i+=2) {
        ret[pos++] = i;
      }
      for(int i=3;i<=lim && pos<n;i+=3) {
        if(i%2==0) continue;
        ret[pos++] = i;
      }
    }
  }
  int sum = 0;

  for(int i=0;i<n;++i) {
    sum += ret[i];
  }
  for(int i=0;i<n;++i) {
    assert(gcd(sum-ret[i],ret[i])!=1);
  }
  for(int i=0;i<pos;++i) {
    printf("%d\n", ret[i]);
  }
}

