    vector<int> v;

    int count = 0;
    for (int j = 1; count < N-2; ++j) {
        if (j % 2 == 0 || j % 3 == 0 || j % 5 == 0) {
            s += j;
            ++count;
            v.push_back(j);
        }
    }


    bool found = false;
    for (int j = v.back()+1; j <= 30000; ++j) {
        if (j % 3 != 0 && j % 5 != 0) continue;
        for (int k = j+1; k <= 30000; ++k) {
            if (k % 3 != 0 && k % 5 != 0) continue;
            if ((s + j + k) % 30 == 0) {
                found = true;
                v.push_back(j);
                v.push_back(k);
                break;
            }
        }
        if (found) break;
    }

    assert(found);

    for (int j = 0; j < v.size(); ++j) {
        if (j > 0) cout << " ";
        cout << v[j];
    }
    cout << endl;

    return 0;
}

