ll n;
vector<ll> ans;
int main() {
	cin >> n;
	if (n == 3) cout << "2 5 63" << endl;
	else if (n == 4) cout << "2 5 20 63" << endl;
	else if (n < 15000) {
		ll t6 = n % 4, t2 = n / 4 * 2, t3 = n / 4 * 2;
		vector<ll>s2, s3, s6;
		REPO(i, 30000) {
			if (i % 6 == 0)s6.push_back(i);
			else if (i % 2 == 0)s2.push_back(i);
			else if (i % 3 == 0)s3.push_back(i);
		}
		if (t3 > 5000) {
			t6 += t3 - 5000;
			t3 = 5000;
		}
		REP(i, t6)ans.push_back(s6[i]);
		REP(i, t2)ans.push_back(s2[i]);
		REP(i, t3)ans.push_back(s3[i]);
	}
	else {
		ll t6 = 20000 - n;
		REPO(i, 30000) {
			if (i <= t6 * 6 and i % 6 == 0)continue;
			else if (i % 2 == 0 or i % 3 == 0)ans.push_back(i);
		}
	}
	REP(i, ans.size()) {
		if (i != 0)cout << " ";
		cout << ans[i];
	}
	cout << endl;
}

