int a[20005],n,lim;
int gcd(int x,int y){
	return y?gcd(y,x%y):x;
}
void check(){
	int s=0;
	for (int i=1;i<=n;i++) s+=a[i];
	for (int i=1;i<=n;i++)
		if (gcd(s-a[i],a[i])==1) return;
	int tmp=a[1];
	for (int i=2;i<=n;i++)
		tmp=gcd(tmp,a[i]);
	if (tmp!=1) return;
	for (int i=1;i<=n;i++)
		printf("%d ",a[i]);
	exit(0);
}
void solve(int dep,int low){
	if (dep>n){
		check();
		return;
	}
	for (int i=low;i<=100;i++)
		a[dep]=i,solve(dep+1,i);
}
int main(){
	scanf("%d",&n);
	solve(1,2);
}

