const int lm = 10;

template <typename T>
long long gcd(T x, T y){
	return y==0 ? x : gcd(y, x%y);
}

bool check(const vector<int>& v) {
    int sum = 0;
    set<int> s(ALL(v));
    if(SZ(s) != SZ(v)) return false;
    REP(i, SZ(v)) {
        if(v[i] > 30000) return false;
        sum += v[i];
    }
    int g = v[0];
    REP(i, SZ(v)) {
        g = gcd(g, v[i]);
    }
    if(g > 1) return false;
    REP(i, SZ(v)) {
        if(gcd(v[i], sum-v[i]) == 1) {
            return false;
        }
    }
    return true;
}

void enu(int n, vector<int>& v) {
    // DEBUG(n);
    if(n == 0) {
        // dpite(ALL(v));
        if(check(v)) dpite(ALL(v));
        return;
    }
    REP(i, lm) {
        v.push_back(i+1);
        enu(n-1, v);
        v.pop_back();
    }
}

void solve(int n) {
    if(n == 3) {
        cout << "2 5 63" << endl;
    } else if(n == 4) {
        cout << "2 5 20 63" << endl;
    } else {
        vector<int> ans;
        ans.push_back(2);
        ans.push_back(3);
        ans.push_back(4);
        ans.push_back(9);
        int cc = 20000-5000;
        int c0 = 6;
        int c2 = 8;
        int c4 = 10;
        int c3 = 15;
        const int lm = 30000;
        while(SZ(ans) < n-n%2) {
            if(c2 <= lm and c4 <= lm) {
                ans.push_back(c2);
                ans.push_back(c4);
                c2 += 6;
                c4 += 6;
            } else if(c3 <= lm and c3+6 <= lm) {
                ans.push_back(c3);
                c3 += 6;
                ans.push_back(c3);
                c3 += 6;
            } else {
                ans.push_back(c0);
                c0 += 6;
            }
        }
        if(n%2) {
            ans.push_back(c0);
            c0 += 6;
        }
        DEBUG(SZ(ans));
        assert(SZ(ans) == n);
        assert(check(ans));
        pite(ALL(ans));
    }
}


