int GCD(int a, int b) {
  if (a == 0) return b;
  return GCD(b % a, a);
}

bool Check(int n) {
  int g = a[0];
  for (int i = 0; i < n; ++i) g = GCD(g, a[i]);
  if (g != 1) return false;
  int sum = accumulate(a, a + n, 0);
  for (int i = 0; i < n; ++i) {
    if (GCD(a[i], sum - a[i]) == 1) return false;
  }
  return true;
}

void Solve(int at, int n, int cap) {
  if (at == n && Check(n)) {
    for (int i = 0; i < n; ++i) {
      if (i) cout << " ";
      cout << a[i];
    }
    cout << endl;
    exit(0);
  }

  if (at == n) return;

  for (int i = 2; i <= cap; ++i) {
    a[at] = i;
    Solve(at + 1, n, cap);
  }
}

