vector<ll> solve(ll N){
    vector<ll> res(N);
    if(N == 3){
        res[0] = 2; res[1] = 5; res[2] = 63;
        return res;
    }
    if(N == 4){
        res = {2,5,20,63};
        return res;
    }
    int idx = 0;
    ll sum = 0;
    res[idx++] = 2; res[idx++] = 5; res[idx++] = 8; res[idx++] = 15;
    sum += (2 + 5 + 8 + 15);
    if(N%2 == 1) {res[idx++] = 30000; sum += 30000;}
    if(N == idx) return res;


    res[idx++] = 4; res[idx++] = 6;
    sum += 4 + 6;

    int base = 10;
    for(int i = 1; i < 3000; i++){ // 10*x + 2 , 10*x + 8
        if(idx == N) break;
        res[idx++] = base*i + 2;
        res[idx++] = base*i + 8;

        sum += base*i + 2;
        sum += base*i + 8;
    }
    if(idx == N) return res;

    for(int i = 1; i < 3000; i++){ // 10*x + 4 , 10*x + 6
        if(idx == N) break;
        res[idx++] = base*i + 4;
        res[idx++] = base*i + 6;

        sum += base*i + 4;
        sum += base*i + 6;
    }
    if(idx == N) return res;

    for(int i = 1; i < 2999; i++){ // 10 * x
        if(idx == N) break;
        res[idx++] = base*i;

        sum += base*i;
    }

   // cout << idx << endl;

    for(int i = 2; i < 2998; i++){ // n*10 + 5
        if(idx == N) break;
        res[idx++] = base*i + 5;
        sum += base*i + 5;
    }
    if(idx == N) return res;

    base = 30;
    for(int i = 0; i < 1000; i++){ // n*30 + 3  n*30 + 27
        if(idx == N) break;
        res[idx++] = base*i + 3;
        res[idx++] = base*i + 27;

        sum += base*i + 3;
        sum += base*i + 27;
    }

    if(idx == N) return res;
    for(int i = 0; i < 1000; i++){ // n*30 + 9  n*30 + 21
        if(idx == N) break;
        res[idx++] = base*i + 9;
        res[idx++] = base*i + 21;
    }
    return res;
}

