#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ull = unsigned long long;

void output(std::vector<int> v){
	for (size_t i = 0; i < v.size() - 1; i++) {
		std::cout << v[i] << ' ';
	}
	std::cout << v[v.size()-1] << '\n';
}

int main(int argc, char const *argv[]) {
	int n;
	std::cin >> n;
	if (n == 3) {
		std::cout << "2 5 63" << '\n';
	}
	else if (n == 4) {
		std::cout << "2 5 20 63" << '\n';
	}
	else if (n == 5) {
		std::cout << "2 5 20 63 60" << '\n';
	}
	else {
		std::vector<int> v = {2,3,4,8,9,10};
		for (int i = 1; i <= n/4 +2; i++) {
			v.push_back(i * 6);
			v.push_back(i * 6 + 2);
			v.push_back(i * 6 + 3);
			v.push_back(i * 6 + 4);
		}

		std::vector<int> ans;
		ll sum = 0;
		for (int i = 0; i < n; i++) {
			ans.push_back(v[i]);
			sum += v[i];
		}

		if (sum % 6 == 2) {
			// 8を削除して6の倍数を追加
			ans.erase(ans.begin()+3);
			ans.push_back((n/4+2)*6);
		}
		else if (sum % 6 == 3) {
			// 9を削除して6の倍数を追加
			ans.erase(ans.begin()+4);
			ans.push_back((n/4+2)*6);
		}
		else if (sum % 6 == 5) {
			// 8を削除して(sum%6==3になる)
			// 6の倍数+3を追加(sum%6==0にする)
			ans.erase(ans.begin()+3);
			ans.push_back((n/4+2)*6+3);
		}

		output(ans);
	}
	return 0;
}

