using namespace std;

constexpr int max_a = 30000;
vector<int> solve(int n) {
    vector<int> answer;
    long long s = 0;
    REP3 (a, 1, max_a + 1) {
        if (a % 2 == 0 or a % 3 == 0 or a % 5 == 0 or a % 7 == 0) {
            answer.push_back(a);
            s += a;
        }
        if (answer.size() == n) break;
    }
    REP3 (a, answer.back() + 1, max_a + 1) {
        if (a % 2 == 0 or a % 3 == 0 or a % 5 == 0 or a % 7 == 0) {
            REP (i, n) {
                if ((s - answer[i] + a) % (2 * 3 * 5 * 7) == 0) {
                    answer[i] = a;
                    return answer;
                }
            }
        }
    }
    assert (false);
}

