        else if(cur%6==3) S.erase(9), S.emplace(last%6==0 ? last+6 : last+2);
        else if(cur%6==5) S.erase(9), S.emplace(last%6==3 ? last+1 : last+2);
    }
    for(int e : S) cout << e << ' ';
    cout << endl;
    return 0;
}

