const int mod = 1e9 + 7;

int pwr(int a,int b) {
	int ans = 1;
	while(b) {
		if(b & 1) ans = (ans * 1LL * a) % mod;
		a = (a * 1LL * a) % mod;
		b >>= 1;
	}
	return ans;
}

const int N = 1e5 + 5;
int n, a[N];
vector<int> v1, v2, v3, v4;

void gen(int i,int j,int k) {
	int n = 2 * i + 2 * j + k;
	for(int p = 1; p <= n; p++) {
		if(p <= 2 * i) {
			if(p & 1) {
				a[p] = v1.back();
				v1.pop_back();
			}
			else {
				a[p] = v4.back();
				v4.pop_back();
			}
		}
		else if(p <= 2 * i + 2 * j) {
			a[p] = v2.back();
			v2.pop_back();
		}
		else {
			a[p] = v3.back();
			v3.pop_back();
		}
	}
	sort(a + 1, a + n + 1);
}

bool check() {
	int g = 0;
	ll s = 0;
	for(int i = 1; i <= n; i++) {
		g = __gcd(g, a[i]);
		s += a[i];
	}
	if(g != 1) {
		return 0;
	}
	for(int i = 1; i <= n; i++) {
		if(__gcd((ll)a[i], s) == 1){
			return 0;
		}
	}
	sort(a + 1, a + n + 1);
	int nn = unique(a + 1, a + n + 1) - a - 1;
	if(n != nn) return 0;
	return 1;
}

void solve() {
	cin >> n;
	int c1 = 0, c2 = 0;
	for(int i = 30000; i >= 1; i--) {
		if(i % 6 == 0) {
			v3.push_back(i);
		}
		else if(i % 3 == 0) {
			v2.push_back(i);
		}
		else if(i % 2 == 0) {
			if((i / 2) % 3 == 1) {
				v1.push_back(i);
			}
			else {
				v4.push_back(i);
			}
		}
	}
	if(n == 3) {
		cout << "2 5 63" << endl;
	}
	else if(n == 4) {
		cout << "2 5 20 63" << endl;
	}
	else {
		for(int i = 1; i <= 5000; i++) {
			for(int j = 1; j <= 2500; j++) {
				if(n - 2 * i - 2 * j >= 0 && n - 2 * i - 2 * j <= 5000) {
					gen(i, j, n - 2 * i - 2 * j);
					for(int i = 1; i <= n; i++) {
						cout << a[i] << " ";
					}
					cout << endl;
					assert(check());
					return;
				}
			}
		}
	}
}

