    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    if (N==3) {
        cout << "2 5 63" << endl;
        return 0;
    }
    if (N==4) {
        cout << "2 5 20 63" << endl;
        return 0;
    }
    if (N==5) {
        cout << "2 3 27 28 30" << endl;
        return 0;
    }
    if (N==6) {
        cout << "2 3 5 25 27 28" << endl;
        return 0;
    }
    if (N==7) {
        cout << "2 3 5 25 27 28 30" << endl;
        return 0;
    }
    vector<bool> A(30501);
    int cnt = 0;
    for (int i = 1; i <= 30000; i++) {
        if (i%2==0 || i%3==0 || i%5==0) {
            if (i%15==0 && i%2==1) continue;
            A[i] = true;
            cnt++;
        }
    }

    int M = cnt - N;
    if (M%2!=0) {
        M--;
        A[30000] = false;
    }
    for (int i = 30000; i >= 1; i--) {
        if (M == 0) break;
        if (!A[i]) continue;
        int k = i/30;
        int l = i%30;
        if (A[k*30+(30-l)]) {
            A[i] = A[k*30+(30-l)] = false;
            M -= 2;
        }
    }

    rep(i,30001) if (A[i]) cout << i << endl;
}

