        ll sum = 0;
        ll current = 2;
        vector <ll> vec;
        for (int i = 0; i < N; i++) {
            if (current % 6 == 1 || current % 6 == 5) {
                vec.push_back(current + 1);
                sum += (ll)(current + 1);
                current += 2;
            } else {
                vec.push_back(current);
                sum += (ll)(current);
                current++;
            }
