int gcd(int x,int y) {
  if(x==0) {
    return y;
  }
  return gcd(y%x,x);
}
void solve(int n) {
  int lim = 30000;
  int pos = 0;
  if(n*2<=lim) {
    if(n==3) {
      printf("2 5 63\n");
      return;
    } else {
      ret[0] = 2;
      ret[1] = 3;
      ret[2] = 9;
      ret[3] = 4;
      pos = 4;
      int parity = (n)%3;
      int sum = 0;
      for(int i=6;i<=lim && pos<n;i+=2) {
        ret[pos++] = i;
        sum += i;
      }
      parity = sum%3;
      if(parity==1) {
        ret[pos-1] += 2;
      } else if(parity==2){
        ret[pos-1] +=4;
      }
    }
  } else {
    if(n&1) {
      for(int i=2;i<=lim;i+=2) {
        if(i==6) continue;
        ret[pos++] = i;
      }
      for(int i=3;i<=lim && pos<n;i+=3) {
        if(i%2==0) continue;
        ret[pos++] = i;
      }
    } else {
      for(int i=2;i<=lim;i+=2) {
        ret[pos++] = i;
      }
      for(int i=3;i<=lim && pos<n;i+=3) {
        if(i%2==0) continue;
        ret[pos++] = i;
      }
    }
  }
  int sum = 0;
  for(int i=0;i<n;++i) {
    sum += ret[i];
  }
  int u = ret[0];
  for(int i=0;i<n;++i) {
    assert(ret[i]<=lim);
    assert(gcd(sum-ret[i],ret[i])!=1);
    u = gcd(u,ret[i]);
  }
  assert(u==1);

}

