          v[i] += 2;
          break;
        }
      }
    }else {
      dep(i, n - 1, 0) {
        if(v[i] % 3 == 0) {
          if(mp[v[i] + 3]) continue;
          mp[v[i] + 3] = 1;
          mp[v[i] - 3] = 0;
          v[i] += 3;
          break;
        }
      }
      dep(i, n - 1, 0) {
        if(v[i] % 2 == 0) {
          if(mp[v[i] - 2]) continue;
          mp[v[i] - 2] = 1;
          mp[v[i] + 5] = 0;
          v[i] -= 2;
          break;
        }
      }
      break;
    }
  }
  rep(i, 0, n) {
    cout << v[i] << " ";
  }
  cout << endl;
}

