bool solve(int n) {

    if (n == 3) {
        cout << "2 5 63" << endl;
        return true;
    }

    vector<int> v2, v3, v6;
    for (int i = 2; i <= 30000; i++) {
        if (i % 2 == 0 && i % 3 == 0) {
            v6.pb(i);
        } else if (i % 2 == 0) v2.pb(i);
        else if (i % 3 == 0) v3.pb(i);
    }

    for (int x = 2; x <= sz(v2) && x < n; x += 2) {
        int ymin = 1, ymax = sz(v3) / 2;
        // x + y <= n
        // n - x - y <= sz(v6)
        // y <= n - x
        // n - x - sz(v6) <= y
        int ry = (n - x) / 2;
        int ly = (max(0, n - x - sz(v6)) + 1) / 2;
        if (ly <= ry && max(ly, ymin) <= min(ymax, ry)) {
            int y = max(ly, ymin) * 2;
            if (n - x - y >= 0 && n - x - y <= sz(v6)) {
