void solve(){
    i64 N;
    cin >> N;

    if(N==3){
        cout << "2 5 63" << endl;
        return;
    }

    if(N==4){
        cout << "2 5 20 63" << endl;
        return;
    }

    if(N==5){
        cout << "2 4 6 3 9" << endl;
        return;
    }

    vector<i64> ans;
    i64 k=0,s=0;
    while(ans.size()<N){
        if(ans.size()<N) ans.push_back(6*k+2), s+=2;
        if(ans.size()<N) ans.push_back(6*k+3), s+=3;
        if(ans.size()<N) ans.push_back(6*k+4), s+=4;
        if(ans.size()<N) ans.push_back(6*k+6), s+=6;
        ++k;
    }

    s%=6;
    if(s==0){
        print_ans(ans);
        return;
    }

    if(s==2){
        ans.erase(find(ans.begin(), ans.end(), 8));
        ans.push_back(6*k+6);
        print_ans(ans);
        return;
    }

    if(s==3){
        ans.erase(find(ans.begin(), ans.end(), 9));
        ans.push_back(6*k+6);
        print_ans(ans);
        return;
    }

    if(s==5){
        ans.erase(find(ans.begin(), ans.end(), 9));
        ans.push_back(6*k+4);
        print_ans(ans);
        return;
    }

    assert(false);
}

