int main(){
  int N;
  std::cin >> N;
  std::vector<int> prime(1,2);
  prime.reserve(20000);
  for(int i = 3; i < N; ++i){
    for(int j = 2; j <= ceil(sqrt(i)); ++j){
      if(i % j == 0) break;
      if(j == ceil(sqrt(i))) prime.push_back(i);
    }
  }
  std::vector<int> residue;
  residue.reserve(20000);
  for(std::vector<int>::iterator it = prime.begin(); it != prime.end(); ++it){
    int tmp = 0;
    for(int i = 1; i < N; ++i){
      tmp += i;
      tmp = tmp%(*it);
    }
    residue.push_back(((*it)-tmp%(*it))%(*it));
  }
  int answer=0;
  for(int i = N; i <= 30000; ++i){
    for(std::vector<int>::iterator it_r = residue.begin(),it_p = prime.begin(); it_r != residue.end(); ++it_r,++it_p){
      if(i%(*it_p) != (*it_r)) break;
      if(it_r == residue.end() - 1) answer = i;
    }
    if(answer != 0) break;
  }
  for(int i = 1; i <= N; ++i){
    std::cout << i << " ";
  }
  std::cout << answer << std::endl;
  return 0;
}

