		std::cout << "2 5 63" << '\n';
	}
	else if (n == 4) {
		std::cout << "2 5 20 63" << '\n';
	}
	else if (n == 5) {
		std::cout << "2 5 20 63 60" << '\n';
	}
	else if (n == 6) {
		std::cout << "2 3 4 8 9 10" << '\n';
	}
	else if (n == 7) {
		std::cout << "2 3 4 6 8 9 10" << '\n';
	}
	else {
		std::vector<int> v = {2,3,4,6,8,9,10};
		for (int i = 1; i <= n/4 +2; i++) {
			v.push_back((i+1) * 6);
			v.push_back((i+1) * 6 + 2);
			v.push_back((i+1) * 6 + 3);
			v.push_back((i+1) * 6 + 4);
		}

		std::vector<int> ans;
		ll sum = 0;
		for (int i = 0; i < n; i++) {
			ans.push_back(v[i]);
			sum += v[i];
		}

		if (sum % 6 == 2) {
			// 8を削除して6の倍数を追加
			ans.erase(ans.begin()+3);
			ans.push_back((ans[ans.size()-1]/6 + !!(ans[ans.size()-1]%6))*6);
		}
		else if (sum % 6 == 3) {
			// 9を削除して6の倍数を追加
			ans.erase(ans.begin()+4);
			ans.push_back((ans[ans.size()-1]/6 + !!(ans[ans.size()-1]%6))*6);
		}
		else if (sum % 6 == 5) {
			// 9を削除して(sum%6==2になる)
			// 6の倍数+4を追加(sum%6==0にする)
			ans.erase(ans.begin()+4);
			if (ans[ans.size()%6] < 4) {
				ans.push_back((ans[ans.size()-1]/6) * 6 + 4);
			}
			else {
				ans.push_back((ans[ans.size()-1]/6 + 1) * 6 + 4);
			}
		}

		output(ans);
	}
	return 0;
}

