bool validate(vector<int>&v, int n) {
  if( v.size() != (size_t)n )
    return false;
  sort(v.begin(), v.end());
  ll tot = v[0];
  for(int i=1; i<n; i++) {
    if( v[i] == v[i-1] ) return false;
    tot += v[i];
  }
  for(int i=0; i<n; i++)
    if( __gcd((ll)v[i], tot-v[i]) == 1 ) {
      cerr << v[i] << ',' << tot-v[i]
	   << ':' << __gcd((ll)v[i], tot-v[i]) << endl;
      return false;
    }
  return true;
}

