  }
  for(int k=1; k<=v[1].size(); k++) {
    if(n-k>v[0].size()) break;
    ll d=v[1][0],sum=d;
    for(int i=1; i<k; i++) {
      d=__gcd(d,v[1][i]);
      sum+=v[1][i];
    }
    for(int i=0; i<n-k; i++) {
      d=__gcd(d,v[0][i]);
      sum+=v[0][i];
    }
    for(int i=0; i<k; i++) {
      if(__gcd(sum-v[1][i],v[1][i])==1) goto next;
    }
    for(int i=0; i<n-k; i++) {
      if(__gcd(sum-v[0][i],v[0][i])==1) goto next;
    }
    if(d==1) {
      vector<int> a;
      for(int i=0; i<k; i++) a.push_back(v[1][i]);
      for(int i=0; i<n-k; i++) a.push_back(v[0][i]);
      for(int i=0; i<a.size(); i++) {
        if(i) cout << " ";
        cout << a[i];
      }
      cout << endl;
      return 0;
    }
    next:;
  }
  return 0;
}

