void solve(long long N) {
    if( N == 3){
        cout << 2 << " " << 5 << " " << 3 << endl;
        return;
    }
    vector<int> r;
    for (int i = 1; i <= 30000; i++) {
        if (i % 2 == 0 || i % 3 == 0) {
            r.push_back(i);
        }
    }

    r.resize(N - 1);
    int tot = accumulate(r.begin(), r.end(), 0);
    set<int> S(r.begin(), r.end());
    for (int i = 1; i <= 30000; i++) {
        if (S.count(i)) continue;
        if ((tot + i) % 6 == 0) {
            r.push_back(i);
            break;
        }
    }
    for(auto i : r ) cout << i << " "; cout << endl;

}

