bool used[30001];

void smain() {
    int n;
    cin >> n;
    vl a(n);
    a[0] = 2, a[1] = 3;
    used[a[0]] = true;
    used[a[1]] = true;
    ll sum = a[0] + a[1];
    int j = 4;
    for (int i = 2; i < n - 1; ++i) {
        while ((j % a[0]) && (j % a[1])) {
            ++j;
        }
        a[i] = j++;
        sum += a[i];
        used[a[i]] = true;
    }

    assert(j <= 30000);
    j = 2;
    while (true) {
        if (used[j]) {
            j++;
            continue;
        }
        if ((sum + j) % (a[0] * a[1])) {
            j++;
            continue;
        }
        if (__gcd(sum, (ll)j) == 1) {
            j++;
            continue;
        }
        break;
    }

    assert(j <= 30000);
    a[n - 1] = j;

    fori (i, n) {
        cout << a[i] << ' ';
    }
}

