vector<int> solve(int N) {
	if (N == 3) {
		return { 2,5,63 };
	}

	vector<int> nums;
	FOR(i, 2, 30000 + 1) {
		if (i % 2 == 0 or i % 3 == 0) {
			nums.push_back(i);
		}
	}

	vector<vector<int> > memo;
	memo.push_back({});
	memo.push_back({ 3 });
	memo.push_back({ 3, 7 });
	memo.push_back({ 0,2,3 });
	memo.push_back({ 0,1,2,5 });
	memo.push_back({ 0,1,2,3,5 });
	memo.push_back({ 0,1,2,4,5,6 });
	memo.push_back({ 0,1,2,3,4,5,6 });
	memo.push_back({ 0,1,2,3,4,5,6,7 });

	int ma = 0;

	int la = 0;
	vector<int> res;
	REP(i, N - (N % 8)) {
		res.push_back(nums[i]);
		la = i + 1;
	}

	for (auto& a : memo[N % 8]) {
		res.push_back(nums[a + la]);
	}

	return res;
}

bool check(vector<int> res) {
	int su = 0;
	for (auto& a : res) {
		if (a > 30000) {
			return false;
		}
		su += a;
	}
	int g = res[0];
	for (auto& a : res) {
		g = gcd(g, a);
	}
	if (g != 1) {
		return false;
	}
	for (auto& a : res) {
		if (gcd(su - a, a) == 1) {
			return false;
		}
	}
	return true;
}

