vector<int> solve(int n) {
    vector<int> res;
    if (n == 3) {
        res = {2, 5, 63};
    } else {
        for (int i = 0; i <= 4999; i++) {
            int x = (3 * i + 1) * 2;
            if (x <= 30000) res.push_back(x);
            x = (3 * i + 2) * 2;
            if (x <= 30000) res.push_back(x);
            x = (4 * i + 1) * 3;
            if (x <= 30000) res.push_back(x);
            x = (4 * i + 3) * 3;
            if (x <= 30000) res.push_back(x);
