	if( 3 * ( cnt2 * 2 - 1 ) > 30000 ) continue;

	vector<int> ans;

	for(int j=1;j<=cnt1;j++){
	  ans.push_back( j * 2 );
	}

	int x = 3, cnt = 0;

	while(1){

	  if( x % 6 != 0 ){
	    ans.push_back( x );
	    cnt++;
	  }

	  x += 3;

	  if( cnt == cnt2 ) break;
	}

	if( flag ) ans.push_back( 30000 );

	for(int j=0;j<n;j++){
	  if(j) cout<<' ';
	  cout<<ans[j];
	}

	cout<<endl;

	assert(check(ans));

	return 0;
      }

    }

  }

  return 0;
}

