using namespace std;

vector< bool > prime_table(int n) {
  vector< bool > prime(n + 1, true);
  if(n >= 0) prime[0] = false;
  if(n >= 1) prime[1] = false;
  for(int i = 2; i * i <= n; i++) {
    if(!prime[i]) continue;
    for(int j = i + i; j <= n; j += i) {
      prime[j] = false;
    }
  }
  return prime;
}


void solve(){
  int n;
  cin>>n;
  set<int>st;
  st.emplace(2);st.emplace(3);
  vector<bool>p=prime_table(30000);
  int num=4;
  while(st.size()<n-1){
    if(!p[num]){
      if((num%2==0)||(num%3==0))st.emplace(num),++num;
      else ++num;
    }
    else ++num;
  }
  ll sum=0;
  for(auto x:st){
    sum+=x;
  }
  while(1){
    ++num;
    if((num%2==sum%2)&&(num%3==(3-(sum%3))%3)){
      if(!p[num]){
        st.emplace(num);
        break;
      }
    }
  }
  for(auto x:st){
    cout<<x<<" ";
  }
  cout<<endl;
}

