int main()
{

	int N;
	cin >> N;

	int r[N];
	r[0] = 2;
	r[1] = 5;
	r[2] = 63;

	ll left[N];
	left[0] = 68;
	left[1] = 65;
	left[2] = 7;

	for(int i=3;i<N;i++){
		ll tmp[N];

		ll al = left[i-1] + r[i-1];

		for(int t=1;t<NMAX;t++){
			fst:
			if(gcd(al,t) == 1){
			  continue;
			}
			r[i] = t;

			// 他のを足す
			REP(j,i){
				tmp[j] = left[j] + r[i];
				if(gcd(tmp[j],r[j]) == 1){
					t++;
					goto fst;
				}
			}

 			// 自分以外の和
			tmp[i] = left[i-1] + r[i-1];
			break;
		}

		REP(t,i+1){
			left[t] = tmp[t];
		}
	}



	REP(i,N-1){
		cout << left[i] << " ";
	} 
	cout << left[N-1] << endl;

	REP(i,N-1){
		cout << r[i] << " ";
	}
