void solve()
{
	int n, i, cnt = 0, bal;
	cin >> n;
	if(n == 3)
	{
		cout << "2 5 63\n";
		return;
	}
	if(n <= 15000)
	{
		if(n % 3 == 0)
		{
			fo(i,1,n-4+1)
				mark[i*2] = 1;
			mark[3] = mark[9] = mark[15] = mark[21] = 1;
		}
		else
		{
			fo(i,1,n-2+1)
				mark[i*2] = 1;
			mark[3] = mark[9] = 1;
		}
	}
	else if(n % 2 == 0)
	{
		for(i = 2; i <= MAX; i+=2)
			mark[i] = 1;
		cnt = MAX/2;
		for(i = 3; i <= MAX; i+=3)
			if(!mark[i])
			{
				mark[i] = 1;
				cnt++;
				if(cnt == n)
					break;
			}
	}
	else
	{
		for(i = 2; i < MAX; i+=2)
			mark[i] = 1;
		cnt = MAX/2 - 1;
		for(i = 3; i <= MAX; i+=3)
			if(!mark[i])
			{
				mark[i] = 1;
				cnt++;
				if(cnt == n)
					break;
			}
	}

	fo(i,2,MAX+1)
		if(mark[i])
			cout << i << " ";
	cout << '\n';
	return;
}

