vector<int> solve(int n) {
	if (n == 3) return { 2, 5, 63 };
	vector<int> ans; int cur_sum = 0;
	for (int i = 1; i <= N; i++) {
		if (i % 2 == 0 or i % 3 == 0) {
			if (n - (int)ans.size() > 2) ans.push_back(i), cur_sum += i;
			else {
				for (int j = i; j <= N; j++) {
					if ((cur_sum + j) % 3 == 0) {
						ans.push_back(j), cur_sum += j;
						break;
					}
				}
				for (int j = i; j <= N; j++) {
					if (j != ans.back() and (cur_sum + j) % 6 == 0) {
						ans.push_back(j), cur_sum += j;
						break;
					}
				}
				// assert(cur_sum % 6 == 0);
				// assert((int)(ans.size()) == n);
				return ans;
			}
		}
	}
	// exit(!printf("didn't finish? n = %d\n", n));
	return ans;
}

