int A[20004];

int solve(int a, int b, int c, int N)
{
    A[1] = a, A[2] = b, A[3] = c;
    int sum = a+b+c, ptr = 2;
    int lcm = a * b * c;

    for(int i=4; i<N; i++)
    {
        A[i] = ptr++;

        while(ptr == a || ptr == b || ptr == c || (ptr%a && ptr%b && ptr%c))
            ptr++;

        sum += A[i];
    }

    while((sum + ptr) % lcm)
    {
        ptr++;

        while(ptr == a || ptr == b || ptr == c || (ptr%a && ptr%b && ptr%c))
            ptr++;

        if(ptr > 30000)
            return 0;
    }

    A[N] = ptr;
    return 1;
}

