            if(!solve(2, 3, 11, N))
                if(!solve(2, 5, 11, N))
                    if(!solve(2, 7, 11, N))
                        if(!solve(3, 5, 7, N))
                            if(!solve(3, 5, 11, N))
                                if(!solve(3, 7, 11, N))
