bool used[30001];
vector<int>primes;

int main() {
	int N; cin >> N;

	for (int i = 2; i < 30001; i++) {
		bool flag = true;
		for (int j = 2; j*j <= i; j++) {
			if (i%j == 0) {
				flag = false;
				break;
			}
		}
		if (flag)primes.push_back(i);
	}

	vector<int>ans;
	ans.push_back(2); used[2] = true;
	ans.push_back(3); used[3] = true;
	if (N % 2)used[4] = true;
	ll sum = 5;
	int cnt = N-2;
	ll pro = 6;
	for (int i = 0; i < primes.size(); i++) {
		if (cnt == 1)break;

		int x = primes[i];
		for (int j = x; j < 30001; j += x) {
			if (used[j])continue;
			sum += j;
			cnt--;
			ans.push_back(j); used[j] = true;
			if (cnt == 1)break;
		}
		if (i > 1)pro *= x;
	}

	ll a = pro - (sum % pro);

	for (int i = a; i < 30001; i+=pro) {
		if (used[i])continue;

		if (gcd(sum, i) != 1) {
			ans.push_back(i);
			for (int j = 0; j < ans.size(); j++) {
				if (j)cout << " ";
				cout << ans[j];
			}
			cout << endl;
			return 0;
		}
	}


	for (int c = 2; c < primes.size(); c++) {
		int x = primes[c];
		ll tmppro = pro * x;
		used[ans.back()] = false;
		used[x] = true;
		sum += x - ans.back();
		ans.back() = x;

		for (int j = a; j < 30001; j += tmppro) {
			if (used[j])continue;

			if (gcd(sum, j) != 1) {
				ans.push_back(j);
				for (int k = 0; k < ans.size(); k++) {
					if (k)cout << " ";
					cout << ans[k];
				}
				cout << endl;

				return 0;
			}
		}
	}

	cout << -1 << endl;

	return 0;
}

