#include<stdio.h>
#include<stdlib.h>
#include<math.h>

int gcd(int m, int n)
{
  int a, b,r;
  if(m < n) {
    a = n;
    b = m;
  } else {
    a = m;
    b = n;
  }
  r = a % b;
  if(r == 0) {
    return b;
    } else {
    return gcd(b,r);
    }
}

