	}
	for(ll num=9;cnt<n-3&&num+6<=30000;num+=12){
		a[cnt++]=num;
		a[cnt++]=num+6;
		s+=num*2+6;
	}
	for(ll num=2;cnt<n-1;num+=2){
		a[cnt++]=num;
		s+=num;
	}
	//sは必ず奇数
	//2,3,5いずれの倍数でもないkであって、s+kが30の倍数かつkの倍数となるようなものが存在すれば良い
	//a[cnt-1]≦26002を大きな偶数に取り替えることでsは30000-a[cnt-1]まで大きくできるので
	//[s,s+30000-a[cnt-1]]にあるssであってとk=30x-ss%30であって、ssがkの倍数であるようなものが存在すれば良い
	//ssの候補が2000個くらい、各ssに対しkの候補が1000個くらいあるので、大丈夫そう

	ll ss=s;
	while(1){
		while(ss%3==0||ss%5==0)ss+=2;
		for(ll k=30-ss%30;k<=30000;k+=30)if(k!=1&&ss%k==0){
			rep(i,0,n-2)printf("%d ",a[i]);
			printf("%d %d\n",a[cnt-1]+(ss-s),k);
			return 0;
		}
		ss+=2;
	}
}

