fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val lst = mutableListOf<Int>()
    var i = 1
    var sum = 0
    while (lst.count() < n - 1) {
        if (i % 2 == 0 || i % 3 == 0 || i % 5 == 0) {
            lst.add(i)
            sum += i
        }
        i++
        if (lst.count() == n - 1 && sum % 2 != 0 && sum % 3 != 0 && sum % 5 != 0) {
            sum -= lst[0]
            lst.removeAt(0)
        }
    }
    while (i <= 30000) {
        val m = sum + i
        if (m % 30 == 0 && (i % 2 == 0 || i % 3 == 0 || i % 5 == 0)) {
            lst.add(i)
            break
        }
        i++
    }
    println(lst.joinToString(" "))
}

