    for (int i = 0; i < 1000; i++) {
      int[] p = new int[10];
      int pt = 0;
      if (Integer.bitCount(i) >= 3) {
        for (int j = 0; j < 10; j++) {
          if (((i >> j) & 1) != 0) {
            p[pt++] = primes[j];
          }
        }
        ret = solve(n, Arrays.copyOf(p, pt));
        if (ret != null)
          break;
      }
    }
    for (long v : ret) {
      out.print(v + " ");
    }
