  }

  public static int[] sieveAtkin(int size) {
    boolean[] isPrime = new boolean[size + 1];
    int sqrtN = (int) Math.sqrt(size);
    int n;
    for (int x = 1; x <= sqrtN; ++x) {
      for (int y = 1; y <= sqrtN; ++y) {
        n = 4 * x * x + y * y;
        if (n <= size && (n % 12 == 1 || n % 12 == 5)) {
          isPrime[n] = !isPrime[n];
        }
        n = 3 * x * x + y * y;
        if (n <= size && n % 12 == 7) {
          isPrime[n] = !isPrime[n];
        }
        n = 3 * x * x - y * y;
        if (x > y && n <= size && n % 12 == 11) {
          isPrime[n] = !isPrime[n];
        }
      }
    }

    for (n = 5; n <= sqrtN; ++n) {
      if (isPrime[n]) {
        for (int k = n * n; k <= size; k += n * n) {
          isPrime[k] = false;
        }
      }
    }
    isPrime[2] = isPrime[3] = true;

    int[] ret = new int[size];
    int count = 0;
    for (int i = 1; i < size; i++) {
      if (isPrime[i]) {
        ret[count++] = i;
      }
    }
    return Arrays.copyOf(ret, count);
  }

  private static long[] solve(int n, int[] primes) {
    long[] ret = new long[n];

    List<Long> cand = new ArrayList<>();
    for (long i = 2; i <= 30000; i++) {
      for (int p : primes) {
        if (i % p == 0) {
          cand.add(i);
          break;
        }
      }
    }
    Collections.sort(cand);

    long primesProd = 1;
    for (int p : primes) {
      primesProd *= p;
    }

    Set<Long> used = new HashSet<>();
    long sum = 0;
    for (int i = 0; i < n - 1; i++) {
      ret[i] = cand.get(i);
      sum += ret[i];
      used.add(ret[i]);
    }

    for (long i = 2; i <= 30000; i++) {
      if ((i + sum) % primesProd == 0 && !used.contains(i)) {
        if (gcd(i, sum) != 1) {
          ret[n - 1] = i;
          return ret;
        }
      }
    }
    return null;
  }

  private static int test(long[] v) {
    long gcd = v[0];
    Set<Long> set = new HashSet<>();
    long sum = 0;
    for (long u : v) {
      gcd = gcd(gcd, u);
      set.add(u);
      sum += u;
    }
    if (gcd != 1) {
      return 1;
    }
    if (set.size() != v.length) {
      return 2;
    }

    for (long u : v) {
      if (gcd(sum - u, u) == 1) {
        return 3;
      }
    }
    return 0;
  }

  public static long gcd(long a, long b) {
    while (b > 0) {
      long c = a;
      a = b;
      b = c % b;
    }
    return a;
  }



