            for (int i = 2; n > 1; i++) {
                if (Utils.gcd(i, q) > 1) {
                    out.println(i);
                    ss += i;
                    n--;
                    last = i;
                }
            }
            while (last % q != 0) last++;
            long add = q - (ss % q);
            last += add;
            while (Utils.gcd(last, ss) == 1) last += q;
            out.println(last);
        }

