public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BGCDSequence solver = new BGCDSequence();
        solver.solve(1, in, out);
        out.close();
    }

    static class BGCDSequence {
        static final int m = 30;
        static final int[] initial = {5, 9, 16};
        static final int[] allowed = {0, 2, 3, 4, 5, 6, 8, 9, 10, 12, 14};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();

            List<Integer> answer = solve(n);

            StringBuilder sb = new StringBuilder();
            for (int x : answer) {
                sb.append(x + " ");
            }
            sb.deleteCharAt(sb.length() - 1);

            out.println(sb);
        }

        private static List<Integer> solve(int n) {
            int remaining = n;

            List<Integer> answer = new ArrayList<>(n);
            for (int x : initial) {
                answer.add(x);
                remaining--;
            }
            if (remaining % 2 == 1) {
                answer.add(m);
                remaining--;
            }

            int mult = 2;
            int next = 0;
            while (remaining > 0) {
                answer.add(mult * m + allowed[next]);
                answer.add(mult * m + (m - allowed[next]));
                remaining -= 2;
                next++;

                if (next == allowed.length) {
                    mult++;
                    next = 0;
                }
            }

            return answer;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
