public class Main {
  private static void solve() {
    int n = ni();


    long[] ret = new long[n];

    int[] primes = {2, 3, 5};
    List<Long> cand = new ArrayList<>();
    for (long i = 2; i <= 30000; i++) {
      for (int p : primes) {
        if (i % p == 0) {
          cand.add(i);
          break;
        }
      }
    }
    Collections.sort(cand);

    long primesProd = 1;
    for (int p : primes) {
      primesProd *= p;
    }

    Set<Long> used = new HashSet<>();
    long sum = 0;
    for (int i = 0; i < n - 1; i++) {
      ret[i] = cand.get(i);
      sum += ret[i];
      used.add(ret[i]);
    }

    for (long i = 2; i <= 30000; i++) {
      if ((i + sum) % primesProd == 0 && !used.contains(i)) {
        if (gcd(i, sum) != 1) {
          ret[n - 1] = i;
          break;
        }
      }
    }

    //System.out.println(test(ret));
    for (long v : ret) {
      out.print(v + " ");
    }
    out.println();
  }

