    long gcd = v[0];
    Set<Long> set = new HashSet<>();
    long sum = 0;
    for (long u : v) {
      gcd = gcd(gcd, u);
      set.add(u);
      sum += u;
    }
    if (gcd != 1) {
      return 1;
    }
    if (set.size() != v.length) {
      return 2;
    }

    for (long u : v) {
      if (gcd(sum - u, u) == 1) {
        return 3;
      }
    }
    return 0;
  }

