/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        AC_GC_22_B solver = new AC_GC_22_B();
        solver.solve(1, in, out);
        out.close();
    }

    static class AC_GC_22_B {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            if (n == 3) {
                out.println("2 5 63");
                return;
            } else if (n == 4) {
                out.println("2 5 20 63");
                return;
            } else if (n == 20000) {
                for (int i = 2; i <= 30000; i++) {
                    if (i % 2 == 0 || i % 3 == 0) {
                        out.print(i);
                        out.print(' ');
                    }
                }
                return;
            }

            List<Integer> ans = new ArrayList<>();
            int _2 = 0;
            int _3 = 0;
            int _23 = 0;
            int i;
            for (i = 2; ans.size() < n - 3; i++) {
                int num = i;
                if (num % 2 == 0 && num % 3 == 0) {
                    _23++;
                } else if (num % 2 == 0) {
                    _2++;
                } else if (num % 3 == 0) {
                    _3++;
                }

                if (num % 2 == 0 || num % 3 == 0) {
                    ans.add(num);
                }
            }

            for (; ans.size() < n; i++) {
                int num = i;
                int treq = req2(_2) + req3(_3);
                if (num % 2 == 0 && num % 3 == 0) {
                    int rs = n - ans.size() - 1;
                    int req = treq;

                    if (rs >= req) {
                        ans.add(num);
                        _23++;
                    }
                } else if (num % 2 == 0) {
                    int req = req2(_2);
                    if (req > 0 || (treq == 0 && req == 0 && n - ans.size() == 3)) {
                        ans.add(num);
                        _2++;
                    }
                } else if (num % 3 == 0) {
                    int req = req3(_3);
                    if (req > 0 || (treq == 0 && req == 0 && n - ans.size() >= 2)) {
                        ans.add(num);
                        _3++;
                    }
                }
            }

//        out.println(_2);
//        out.println(_3);
//        out.println(_23);
            for (int j = 0; j < ans.size(); j++) {
                out.print(ans.get(j));
                out.print(' ');
            }
        }

        int req2(int _2) {
            int div = _2 % 3;

            if (div == 1 || div == 2)
                return 3 - div;
            else
                return 0;
        }

        int req3(int _3) {
            int div = _3 % 2;

            if (div == 1)
                return 1;
            else
                return 0;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void print(char i) {
            writer.print(i);
        }

        public void close() {
            writer.close();
        }

        public void print(int i) {
            writer.print(i);
        }

    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    static int N;

    public static void main(String[] args) {
        FastScanner fc = new FastScanner(System.in);
        N = fc.nextInt();

        PrintWriter pw = new PrintWriter(System.out);
        int[] answer = solve();
        for (int i = 0; i < N; i++) {
            if( i != 0 ) {
                pw.print(" ");
            }
            pw.print(answer[i]);
        }
        pw.println();
        pw.flush();
    }

    static int[] solve() {

        int maxOdd = 0;
        for (int n = 3; n <= 30000; n++) {
            if( n % 2 != 0 && ( n % 3 == 0 || n % 5 == 0) ) maxOdd++;
        }

        maxOdd = maxOdd / 2 * 2; // 二つペアにしたい

        int odd;
        int even;
        if( N > maxOdd ) {
            odd = maxOdd;
            even = N - maxOdd;

        } else {
            if( N % 2 == 0 ) {
                odd = N - 2;
                even = 2;
            } else {
                odd = N - 1;
                even = 1;
            }
        }

        int[] ans = new int[N];
        long all = 0;
        int i = 0;

        for (int n = 2; n <= 30000; n++) {
            if( n % 2 != 0 && (n % 3 == 0 || n % 5 == 0) ) {
                ans[i++] = n;
                all += n;

                odd--;
                if( odd == 0 ) break;
            }
        }

        for (int n = 2; n <= 30000; n+=2) {
            ans[i++] = n;
            all += n;

            even--;
            if( even == 0 ) break;
        }

        while(true) {
            if( all % 3 == 0 && all % 5 == 0 ) {
                break;

            } else {
                all+=2;
                ans[N-1]+=2;
            }
        }

        // 意味はない
        Arrays.sort(ans);

        return ans;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

