            int k = 0;
            for (int i = 0; i < n - 2; i++) {
                k = i / 4 + 1;
                int ai = k * 6 + offset[i % 4];
                nums.add(ai);
                summary += ai;
            }
            int next6k = (k + 1) * 6;
            int fraction = summary % 6;
            int[] candidateToRemove = new int [] {0, 0, 8, 9, 10};
            if (fraction != 0) {
                nums.remove(candidateToRemove[fraction]);
                nums.add(next6k);
            }
            System.out.println(
                    nums.stream().map((Integer i) -> i.toString()).collect(Collectors.joining(" ")));
        }

    }
