				int j = 0;
				list.clear();
				while (list.size() < N) {
					sum += nums.get(j);
					list.add(nums.get(j));
					nums.remove(j);
				}
				long mod = sum % 6;
				if (mod == 2) {
					for (int src : list) {
						if (src % 6 == 2) {
							list.remove((Integer)src);
							break;
						}
					}
					for (int tar : nums) {
						if (tar % 6 == 0) {
							list.add(tar);
							break;
						}
