						}
					}
					for (int tar : nums) {
						if (tar % 6 == 0) {
							list.add(tar);
							break;
						}
					}
				} else if (mod == 5) {
					for (int src : list) {
						if (src % 6 == 3) {
							list.remove((Integer)src);
							break;
						}
					}
					for (int tar : nums) {
						if (tar % 6 == 4) {
							list.add(tar);
