        as.addAll(Arrays.asList(2, 4, 3, 9));
        // add multitples of 2
        for (int i = 2; 6 * i - 2 <= MAX_A; i++) {
            if (N < 2) {
                break;
            }
            as.add(6 * i - 2);
            as.add(6 * i - 4);
            N -= 2;
        }
        // add multitples of 3
        for (int i = 2; 12 * i - 3 <= MAX_A; i++) {
            if (N < 2) {
                break;
            }
            as.add(12 * i - 9);
            as.add(12 * i - 3);
