        {
            int[] A3 = new int[] { 2, 5, 63 };
            int[] A4 = new int[] { 2, 5, 20, 63 };
            int[,] V = new int[,]
            {
                { 0, 0,0,0,0,0,0,0 },
                { 6, 0,0,0,0,0,0,0 },
                { 2, 4,0,0,0,0,0,0 },
                { 2, 4,6,0,0,0,0,0 },
                { 2, 4,6,12,0,0,0,0 },
                { 2, 3,4,6,9,0,0,0 },
                { 2, 3,4,8,9,10,0,0 },
                { 2, 3,4,6,8,9,10,0 },
                { 2, 3,4,6,8,9,10,12 }
            };

            N = Input.ReadInt();
            if (N == 3)
            {
                Console.WriteLine(string.Join(" ", A3));
            }
            else if (N == 4)
            {
                Console.WriteLine(string.Join(" ", A4));
            }
            else
            {
                List<int> ret = new List<int>();
                int M = N % 8;
                int C = N / 8;
                for (int i = 0; i < C; i++)
                {
                    for(int j = 0; j < 8; j++)
                        ret.Add(V[8, j] + 12 * i);
                }

                {
                    for (int j = 0; j < 8; j++)
                    {
                        int v = V[M, j];
                        if (v != 0)
                            ret.Add(v + 12 * C);
                    }
                }

                Console.WriteLine(string.Join(" ", ret));   
            }
        }
    }

