	IList<int> Solve(int N)
	{
		var M = 30000;
		var d = new int[M - 1];
		for (var i = 2; i <= M; i++) d[i - 2] = i;
		{
			var good = new SortedSet<int>();
			for (var p = 2; p <= M; p += 2) good.Add(p);
			for (var p = 3; p <= M; p += 3) good.Add(p);
			var ans = new HashSet<int>();
			var tmp = good.ToArray();
			for (var i = 0; i < N - 1; i++) ans.Add(tmp[i]);
			var s = ans.Sum(i => (long)i);
			for (var j = 0; j < 30; j++)
				if ((s + j) % 2 == 0 && (s + j) % 3 == 0 && (s + j) % 5 == 0)
					for (var k = j; k <= M; k += 30)
						if (!ans.Contains(k) && GCD(s, k) > 1)
						{
							ans.Add(k);
							return ans.ToList();
						}
			return null;
		}
	}
	public static long GCD(long a, long b)
	{
		var n = (ulong)Math.Abs(a); var m = (ulong)Math.Abs(b);
		if (n == 0) return (long)m; if (m == 0) return (long)n;
		int zm = 0, zn = 0;
		while ((n & 1) == 0) { n >>= 1; zn++; }
		while ((m & 1) == 0) { m >>= 1; zm++; }
		while (m != n)
		{
			if (m > n) { m -= n; while ((m & 1) == 0) m >>= 1; }
			else { n -= m; while ((n & 1) == 0) n >>= 1; }
		}
		return (long)n << Math.Min(zm, zn);
	}
}

