	public static void Main() {
		checked{
			long n;
			Lib_IO.rm(out n);

			ll pn = 5;

			var t = PrimeList(100);

			List<ll> ans = new List<ll>();
			ll v = 1;
			for (int i = 0; i < n-1; i++)
			{
				bool c = true;
				while(c){
					v++;
					for (int j = 0; j < pn; j++)
					{
						if(v%t[j]==0){
							c = false;
							break;
						}
					}
				}
				ans.Add(v);
			}

			var s = ans.Sum();
			ll k = 1;
			for (int i = 0; i < pn; i++)
			{
				k *= t[i];
			}
			for (ll i = v+1; i <= 30000; i++)
			{
				if((i+s)%k==0){
					for (int j = 0; j < pn; j++)
					{
						if(i%t[j]==0){
							ans.Add(i);
							break;
						}
					}
					if(ans.Count==n) break;
				}
			}

			Lib_IO.wa(ans);
		}
	}

	public static long[] PrimeList(long n) {
		var l = new List<long>();
		if(n<2) return l.ToArray();
		l.Add(2);
		if(n<3) return l.ToArray();
		l.Add(3);
		bool[] e = PrimeTable(n);
		for (long i = 5, g = 2; i < e.Length; i += g, g ^= 6) if(e[i]) l.Add(i);
		return l.ToArray();
	}
	public static bool[] PrimeTable(long n) {
		bool[] e = Enumerable.Repeat(true, (int)n+1).ToArray();
		if(n >= 0) e[0] = false;
		if(n >= 1) e[1] = false;
		for(int j = 4; j < e.Length; j += 2) e[j] = false;
		for(int j = 9; j < e.Length; j += 6) e[j] = false;
		long i2;
		for(long i = 5, g = 2; (i2 = i * i) <= n; i += g, g ^= 6) {
			if(e[i]) for(long j = i2; j < e.Length; j += i * 2) e[j] = false;
		}
		return e;
	}
















