namespace Kujikatsu003.Questions
{
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var n = inputStream.ReadInt();
            var candidates = Enumerable.Range(1, 30000).Where(i => i % 2 == 0 || i % 3 == 0).ToArray();

            if (n == 3)
            {
                yield return "2 3 4";
                yield break;
            }

            var answer = candidates.Take(n / 8 * 8).ToList();
            var max = answer.Count < 8 ? 0 : answer.Max();
            var mod = n % 8;
            answer.AddRange(GetNext(mod).Select(i => i + max));
            yield return string.Join(" ", answer);
        }

        int[] GetNext(int i)
        {
            switch (i)
            {
                case 1:
                    return new[] { 6 };
                case 2:
                    return new[] { 2, 4 };
                case 3:
                    return new[] { 2, 3, 9 };
                case 4:
                    return new[] { 2, 3, 9, 10 };
                case 5:
                    return new[] { 2, 4, 6, 8, 10 };
                case 6:
                    return new[] { 2, 3, 4, 8, 9, 10 };
                case 7:
                    return new[] { 2, 3, 4, 6, 8, 9, 10 };
                case 8:
                    return new[] { 2, 3, 4, 6, 8, 9, 10, 12 };
                default:
                    return new int[] { };
            }
        }
    }
}

