    {
        if (a.Length == i)
        {
            var sum = a.Sum();
            var disjoint = a.Aggregate((l, r) => gcd(l, r)) == 1;
            var special = a.All(x => gcd(x, sum - x) != 1);
            return disjoint && special;
        }

        for (var x = min; x <= max; x++)
        {
            a[i] = x;
            if (BruteForceCore(a, x + 1, max, i + 1))
            {
                return true;
            }
        }

        return false;
    }

    private int[] BruteForce(int N, int l)
    {
        var a = new int[N];
        for (var m = l; m <= MAX; m++)
        {
            if (BruteForceCore(a, 2, m, 0))
            {
                return a;
            }
        }
        throw new Exception("No solution.");
    }

    private int[] Solve()
    {
        if (N <= 5)
        {
            var t = new int[][] {
                new int[] { 5, 9, 16 },
                new int[] { 2, 3, 4, 9 },
                new int[] { 2, 3, 4, 6, 9 },
            };
            return t[N - 3];
        }

        var set = new HashSet<int>();
        var max = 0;
        var sum = 0L;
        for (var n = 2; ; n++)
        {
            if (n % 2 == 0 || n % 3 == 0)
            {
                set.Add(n);
                sum += n;
                max = Math.Max(max, n);
                if (set.Count == N)
                {
                    break;
                }
            }
        }

        var next = max + 6 - (max % 6);

        switch (sum % 6)
        {
            case 2:
                set.Remove(8);
                set.Add(next);
                break;
            case 3:
                set.Remove(9);
                set.Add(next);
                break;
            case 5:
                set.Remove(9);
                set.Add(next + 4);
                break;
            default:
                break;
        }

        return set.ToArray();
    }

    public void EntryPoint()
    {
        var I = _scanner;
        N = I.N();
        WriteLine(Solve().Intercalate(" "));
        return;
    }
}

