    static List<int> solve(int n)
    {
        int[] mod = { 2, 3, 4, 6 };
        List<int> res = new List<int>();
        for (int i = 0; i < n - 1; i++)
        {
            res.Add((i / 4) * 6 + mod[i % 4]);
        }
        int last = res.Last();
        switch (n % 8)
        {
            case 0:
                //10 -> 12
                res.Add(last + 2);
                break;
            case 1:
                //12 -> 6
                res.Add(last + 6);
                break;
            case 2:
                //2 -> 4 
                res.Add(last + 2);
                break;
            case 3:
                //最後の要素を消して4,6
                //3 -> 4,6
