                res.RemoveAt(res.Count - 1);
                //8 -> 9,12
                res.Add(last + 1);
                res.Add(last + 4);
                break;
            case 7:
                //9
                //9 -> 10
                res.Add(last + 1);
                break;
        }
        return res;
    }
