    class Program
    {
        private int N;
        private void Scan()
        {
            var sc = new Scanner();
            N = sc.NextInt();
        }

        public void Solve()
        {
            if (N == 3)
            {
                Console.WriteLine("2 5 63");
                return;
            }
            long sum = 0;
            List<int> ans = new List<int>();
            Scan();
            var p = new int[] { 2, 3, 4, 6 };
            for (int i = 0; ans.Count < N; i++)
            {
                foreach (var j in p)
                {
                    sum += 6 * i + j;
                    ans.Add(6 * i + j);
                    if (ans.Count >= N)
                    {
                        break;
                    }
                }
            }

            switch (sum%6)
            {
                case 2:
                    for (int i = N - 1; i >= 0; i--)
                    {
                        if (ans[i] % 2 == 0)
                        {
                            ans[i] += 4;
                            break;
                        }
                    }
                    break;
                case 3:
                    for (int i = N - 1; i >= 0; i--)
                    {
                        if (ans[i] % 3 == 0)
                        {
                            ans[i] += 3;
                            break;
                        }
                    }
                    break;
                case 5:
                    for (int i = N - 1; i >= 0; i--)
                    {
                        if (ans[i] % 2 == 0)
                        {
                            ans[i] += 4;
                            break;
                        }
                    }
                    for (int i = N - 1; i >= 0; i--)
                    {
                        if (ans[i] % 3 == 0)
                        {
                            ans[i] += 3;
                            break;
                        }
                    }
                    break;
            }
            Console.WriteLine(string.Join(" ",ans));
        }

        static void Main(string[] args)
        {
            new Program().Solve();
        }
    }
