public class Calculation
{
    public static int LCM(int num1, int num2)
        => num1 / GCD(num1, num2) * num2;

    public static long LCM(long num1, long num2)
        => num1 / GCD(num1, num2) * num2;

    public static int GCD(int num1, int num2)
        => num1 < num2 ? GCD(num2, num1) :
           num2 > 0 ? GCD(num2, num1 % num2) : num1;

    public static long GCD(long num1, long num2)
        => num1 < num2 ? GCD(num2, num1) :
           num2 > 0 ? GCD(num2, num1 % num2) : num1;

    public static long[][] E(int num)
    {
        var tm = new long[num][];
        for(var i = 0; i < num; i++) { tm[i] = new long[num];tm[i][i] = 1; }
        return tm;
    }

    public static T[][] trans<T>(T[][] ar)
    {
        var n = ar[0].Length;var m = ar.Length;
        var tm = new T[n][];
        for(var i = 0; i < n; i++)
        {
            tm[i] = new T[m];
            for (var j = 0; j < m; j++)
                tm[i][j] = ar[j][i];
        }
        return tm;
    }

    public static long dot(long[] ar1, long[] ar2)
    {
        var tm = 0L;
        for (var i = 0; i < ar1.Length; i++)
            tm = (tm + ar1[i] * ar2[i]) % Input.MOD;
        return tm;
    }

    public static long[] mul(long[][] ar, long[] ls)
        => ar.Select(a => dot(a, ls)).ToArray();

    public static long[][] mul(long[][] ar1,long[][] ar2)
    {
        var bt = trans(ar2);
        return ar1.Select(a => mul(bt, a)).ToArray();
    }

    public static long[][] pow(long[][] A,long n)
    {
        if (n == 0) return E(A.Length);
        var tm = pow(A, n / 2);
        if (n % 2 == 0) return mul(tm, tm);
        else return mul(mul(tm, tm), A);
    }

    public static List<int> PrimeList(long num)
    {
        if (num < 2) return new List<int>();
        var prime = new List<int> { 2 };
        var bo = new bool[num + 1];
        for (var i = 3; i <= num; i += 2)
            if (!bo[i])
            {
                prime.Add(i);
                for (var j = 3 * i; j <= num; j += 2 * i)
                    bo[j] = true;
            }
        return prime;
    }

    public static Dictionary<long,int> Factorize(long num)
    {
        var dic = new Dictionary<long, int>();
        for(var i = 2; i * i <= num; i++)
        {
            var ct = 0;
            while (num % i == 0)
            {
                ct++;
                num /= i;
            }
            if (ct != 0) dic[i] = ct;
        }
        if (num != 1) dic[num] = 1;
        return dic;
    }
}

