        }
        var res = new List<int>(num);
        int ct;
        if (num % 2 == 0)
            ct = Min((num - 1) / 4 * 4, 10000);
        else ct = Min((num / 4 - 1) * 4 + 3, 9999);
        for (var i = 1; i <= ct; i++)
            res.Add(i * 3);
        var x = 2;

        for(var i = 0; i < num - ct; i++)
        {
