			continue
		}
		for _, v := range ans {
			g := gcd(s-v+i, v)
			if g <= 1 {
				f = false
				break
			}
		}
		if f {
			ans[n-1] = i
			break
		}
	}
	fmt.Println(strings.Trim(fmt.Sprint(ans), "[]"))
}
func gcd(a, b int) int {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

