		fmt.Println(2, 5, 63)
		return
	}

	// n-2個まで2以上の偶数を入れる
	answers := []int{}
	csum := 0
	for i := 2; i <= 30000; i += 2 {
		answers = append(answers, i)
		csum += i
		if len(answers) == n-2 {
			break
		}
	}
	// (n - len(answers)) % 2 == 0 となるまで末尾を除く
	if (n-len(answers))%2 == 1 {
		csum -= answers[len(answers)-1]
		answers = answers[:len(answers)-1]
	}

	// mod3が0となるまで末尾の要素を2個ずつへらす
	for {
		if csum%3 == 0 {
			break
		}

		a, b := answers[len(answers)-1], answers[len(answers)-2]
		answers = answers[:len(answers)-2]
		if (csum-a-b)%3 == 0 {
			break
		}
	}

	// len(answers)==nとなるまで3の倍数で奇数番目のものを2個ずつ追加する
	for i := 3; i <= 30000; i += 12 {
		answers = append(answers, i)
		answers = append(answers, i+6)
		csum += i
		csum += (i + 6)
		if len(answers) >= n {
			break
		}
	}

	PrintDebug("len: %d, sum: %d\n", len(answers), csum)
	// PrintDebug("%v\n", answers)

	fmt.Println(PrintIntsLine(answers...))
}

