long gcd(long a, long b) {
	if (b == 0) {
		return a;
	}
	return gcd(b, a % b);
}

bool check(in long[] ans)
{
	long sum = ans.sum;
	foreach (v; ans) {
		long sub = sum - v;
		if (gcd(v, sub) == 1) {
			return false;
		}
	}
	long sub = ans[0];
	foreach (v; ans) {
		sub = gcd(v, sub);
	}
	return sub == 1;
}

void main()
{
	int[] primes = [2];
	for (int i = 3; i <= 30000; ++i) {
		bool yes = true;
		foreach (v; primes) {
			yes &= i % v != 0;
		}
		if (yes) {
			primes ~= i;
		}
	}
	int n = readln.chomp.to!int;
	long[] arr = [2, 3, 4];
	long[] brr = [];
	for (int i = 6; i <= 30000; i += 2) {
		brr ~= i;
	}
	for (int i = 6; i <= 30000; i += 3) {
		brr ~= i;
	}
	std.algorithm.sort = brr;
	brr = std.algorithm.uniq(brr).array;
	long[] ans = arr ~ brr[0..n-3];
	bool[long] done;
	foreach (v; ans[0..$-1]) {
		done[v] = true;
	}
	int index = 2;
	while (true) {
		int ite = primes[index];
		bool flag = false;
		while (true) {
			if (ite > 30000) {
				break;
			}
			if (ite in done) {
				ite += primes[index];
				continue;
			}
			ans[$-1] = ite;
			if (ans.check) {
				flag = true;
				break;
			}
			ite += primes[index];
		}
		if (flag) {
			break;
		}
		index++;
	}
	foreach (i, v; ans) {
		if (i) write = " ";
		v.write;
	}
	writeln;
}

