    if idx == -1:
        tmp = [arr[i]**pows[i] for i in range(len(arr))]
        sum_tmp = sum(tmp)
        f = True
        for i in range(len(tmp)):
            x = sum_tmp - tmp[i]
            if gcd(tmp[i], x) == 1:
                f = False
                break
        return f
