from math import gcd, log
sys.setrecursionlimit(10 ** 7)

def calc(arr, lim, pows, idx):
    if idx == -1:
        tmp = [arr[i]**pows[i] for i in range(len(arr))]
        sum_tmp = sum(tmp)
        f = True
        for i in range(len(tmp)):
            x = sum_tmp - tmp[i]
            if gcd(tmp[i], x) == 1:
                f = False
                break
        return f
    for i in range(1, lim[idx]):
        pows[idx] = i
        if calc(arr, lim, pows, idx-1):
            return True
    return False

