import sys
from math import gcd, log
sys.setrecursionlimit(10 ** 7)

def calc(arr, lim, pows, idx):
    if idx == -1:
        tmp = [arr[i]**pows[i] for i in range(len(arr))]
        sum_tmp = sum(tmp)
        f = True
        for i in range(len(tmp)):
            x = sum_tmp - tmp[i]
            if gcd(tmp[i], x) == 1:
                f = False
                break
        return f
    for i in range(1, lim[idx]):
        pows[idx] = i
        if calc(arr, lim, pows, idx-1):
            return True
    return False

def main():
    n = int(input())
    arr = [0]*n
    prime = [-1]*30000
    x = 2
    for i in range(n):
        while prime[x] != -1:
            x += 1
        arr[i] = x
        for j in range(x, 30000, x):
            prime[j] = x
    pow_lim = [int(log(30000, arr[i]))+1 for i in range(n)]
    pows = [1]*n
    _ = calc(arr, pow_lim, pows, n-1)
    ans = [arr[i]**pows[i] for i in range(n)]
    for v in ans:
        print(v, end=" ")

