def check(l):
	l = list(map(int, l.split()))
	tmp = l[0]
	for i in range(len(l) - 1):
		tmp = fractions.gcd(tmp, l[i+1])
	if tmp != 1:
		return(False)

	for i in range(len(l)):
		if fractions.gcd(l[i], sum(l) - l[i]) == 1:
			return(False)

