    while 1:
        a = a%b
        if a == 0:
            return b
        b = b%a
        if b == 0:
            return a

def searchAns(nums):
    cnt = 0
    max_num = sum(nums)
    while cnt < 100000:
        isNotProper = False
        cnt += 1
        last_num = max_num*cnt
        num_list = nums + [last_num]
        sum_others = [sum(num_list) - i for i in num_list]
        for num, sum_of_others in zip(num_list, sum_others):
            flag = gca(num, sum_of_others)
            if flag == 1:
                isNotProper = True
                break          

        if isNotProper:
            continue

        return last_num
    return None

