fn solve(n: u32) -> Vec<u32> {

    if n == 3 {
        return vec![2,5,63];
    } else if n == 4 {
        return vec![2,5,20,63];
    } else if n == 5 {
        return vec![2,5,20,30,63];
    }

    let mut k = 0;
    let mut v = Vec::new();
    let mut sum = 0;
    for i in 1..n+1 {
        let x = match i % 4 {
            1 => { 6*k + 2},
            2 => { 6*k + 3},
            3 => { 6*k + 4},
            0 => {
                k += 1;
                6*k + 6
            },
            _ => unreachable!()
        };
        v.push(x);
        sum += x;
    }

    match sum % 6 {
        0 => {},
        2 => {
            v[4] = 6*(k+2);
        },
        5 => {
            v[5] = 6*(k+1) + 4;
        },
        3 => {
            v[5] = 6*(k+2);
        },
        _ => unreachable!()
    }
    v
}

