fn special_set(n: usize) -> Vec<i64> {
    let base: Vec<i64> = vec![2, 5];
    for v in (base.last().unwrap() + 1) * (n as i64 - 2)..(MAX_ELEMENT + 1) * (n as i64 - 2) {
        println!("v {:?}", v);
        if is_special_set(&[2, 5, v]) {
            println!("before search");
            match search_special_set(n - 2, vec![2, 5], v, v + 7) {
                Some(set) => return set,
                None => (),
            };
        }
    }
    panic!("not found");
}

fn search_special_set(n: usize, base: Vec<i64>, sum: i64, condition: i64) -> Option<Vec<i64>> {
    if n == 1 {
        if *base.last().unwrap() < sum && sum < MAX_ELEMENT && gcd(condition - sum, sum) > 1 {
            Some(base.clone().into_iter().chain(vec![sum]).collect())
        } else {
            None
        }
    } else {
        for v in base.last().unwrap() + 1..MAX_ELEMENT + 1 {
            if sum > v && gcd(condition - v, v) > 1 {
                match search_special_set(
                    n - 1,
                    base.clone().into_iter().chain(vec![v]).collect(),
                    sum - v,
                    condition,
                ) {
                    Some(set) => return Some(set),
                    None => (),
                };
            }
        }
        None
    }
}

fn is_special_set(set: &[i64]) -> bool {
    let mut flag = true;
    for i in 0..set.len() {
        let sum = set.iter()
            .enumerate()
            .fold(0, |acc, (j, v)| if j == i { acc } else { acc + v });
        flag &= gcd(sum, set[i]) > 1;
    }
    flag
}

fn gcd(a: i64, b: i64) -> i64 {
    assert!(a >= 0 && b >= 0);
    let (m, n) = if a >= b { (a, b) } else { (b, a) };
    if n == 0 {
        m
    } else {
        gcd(n, m % n)
    }
}

