    let sum: usize = a.iter().sum();

    for &v in a.iter() {
        let v2 = sum -v;
        if gcd(v, v2) == 1 {
            return false;
        }
    }

    let mut g = a[0];
    for &v in a.iter() {
        g = gcd(v, g);
    }
    g == 1
}

fn solve(n: usize) -> Vec<usize> {
    if n == 3 {
        return vec![2, 5, 63];
    }

    let mut ans = vec![];
    let mut sum = 0;

    let num2 = min(n-2, 15000);
    for i in 0..num2 {
        let v = i * 2 + 2;
        ans.push(v);
        sum += v;
    }
    if sum%3 != 0 {
        ans[num2-1] += 6 - sum%6;
    }

    let num3 = n - num2;
    for i in 0..num3 {
        ans.push(3*(2*i + 1));
    }

    if !check(&ans) {
        debug!(ans);
        panic!();
    }
    ans
}

