fn solve() {
    let n = get!(u64);

    if n == 3 {
        println!("2 5 63");
        return;
    }
    let mut ans = Vec::new();
    let mut x = 2;
    let mut sum = 0;

    for _ in 0..n - 2 {
        while x % 2 != 0 && x % 3 != 0 {
            x += 1;
        }
        ans.push(x);
        sum += x;
        x += 1;
    }

    // debug!(sum % 6);
    // debug!(x);

    match sum % 6 {
        0 => {
            x += 6 - (x % 6);
            ans.push(x);
            ans.push(x + 6);
        }
        1 => {
            x += 6 - (x % 6);
            ans.push(x + 2);
            ans.push(x + 3);
        }
        2 => {
            if n == 20000 {
                ans.push(29998);
                ans.push(30000)
            } else {
                x += 6 - (x % 6);
                ans.push(x);
                ans.push(x + 4);
            }
        }
        3 => {
            while x % 6 != 3 {
                x += 1;
            }
            ans.push(x);
            ans.push(x + 3);
        }
        4 => {
            x += 6 - (x % 6);
            ans.push(x + 2);
            ans.push(x + 6);
        }
        5 => {
            x += 6 - (x % 6);
            if n == 19999 {
                ans.push(29997);
                ans.push(29998)
            } else {
                ans.push(x + 3);
                ans.push(x + 4);
            }
        }
        _ => unreachable!(),
    }

    assert_eq!(ans.iter().sum::<u64>() % 6, 0);
    assert!(ans.iter().max().unwrap() <= &30000);

    println!(
        "{}",
        ans.iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

