#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: tt),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, u1) => {
        $it.next().unwrap().parse::<usize>().unwrap() -1
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut ret: HashSet<usize> = HashSet::new();
    if n == 19999 {
        ret = (2..29999).step_by(2).collect();
        ret.extend((3..30000).step_by(6));
    } else if n == 3 {
        ret.extend([2, 5, 63].iter())
    } else if n == 4 {
        ret.extend([2, 5, 20, 63].iter())
    } else if n == 5 {
        ret.extend([2, 4, 6, 3, 9].iter())
    } else if n == 6 {
        ret.extend([2, 4, 6, 12, 3, 9].iter())
    } else {
        ret.extend([2, 4, 6, 3, 9].iter());
        let n = n - 5;
        for k in 0..2500 {
            let d = n - 2 * k;
            if d % 3 != 0 || d / 3 >= 5000 {
                continue;
            }
            let m = d / 3;
            ret.extend((8..30001).step_by(2).take(3 * m));
            ret.extend((15..30000).step_by(6).take(2 * k));
            break;
        }
    };
    assert_eq!(ret.len(), n);
    println!(
        "{}",
        ret.iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

