        for i in 3..MAX_ELEMENT + 1 {
            if i % 2 == 0 || i % 3 == 0 || i % 5 == 0 {
                set.push(i);
            }
            if set.len() == n - 1 {
                break;
            }
        }

        let mut sum = set.iter().fold(0, |acc, v| acc + v);
        if sum % 2 != 0 {
            set[0] = 2;
            sum -= 1;
        }

        let last = if sum % 3 != 0 && sum % 5 == 0 {
            let mut v = 0;
            for k in 1..3 {
                if (MAX_ELEMENT - 30 + 10 * k) % 3 == 3 - (sum % 3) {
                    v = MAX_ELEMENT - 30 + 10 * k;
                    break;
                }
            }
            v
        } else if sum % 3 == 0 && sum % 5 != 0 {
            let mut v = 0;
            for k in 1..5 {
                if (MAX_ELEMENT - 30 + 6 * k) % 5 == 5 - (sum % 5) {
                    v = MAX_ELEMENT - 30 + 6 * k;
                    break;
                }
            }
            v
        } else {
            let mut v = 0;
            for k in 1..15 {
                if (MAX_ELEMENT - 30 + 2 * k) % 5 == 5 - (sum % 5)
                    && (MAX_ELEMENT - 30 + 2 * k) % 3 == 3 - (sum % 3)
                {
                    v = MAX_ELEMENT - 30 + 2 * k;
                    break;
                }
            }
            v
        };
        set.push(last);
        set
    }
}

fn is_special_set(set: &[i64]) -> bool {
    let mut flag = true;
    for i in 0..set.len() {
        let sum = set.iter()
            .enumerate()
            .fold(0, |acc, (j, v)| if j == i { acc } else { acc + v });
        flag &= gcd(sum, set[i]) > 1;
    }
    flag
}

fn gcd(a: i64, b: i64) -> i64 {
    let (m, n) = if a >= b { (a, b) } else { (b, a) };
    if n == 0 {
        m
    } else {
        gcd(n, m % n)
    }
}

