pub fn prime_factorization(mut n: usize) -> Vec<(usize, usize)> {
    let mut i = 2;
    let mut ans = vec![];
    while i * i <= n {
        let mut cnt = 0;
        while n % i == 0 {
            n /= i;
            cnt += 1;
        }
        if cnt > 0 {
            ans.push((i, cnt));
        }
        i += 1;
    }
    if n > 1 {
        ans.push((n, 1));
    }
    ans
}

pub fn gcd(a: usize, b: usize) -> usize {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn check(a: &Vec<usize>) -> bool {
    let sum: usize = a.iter().sum();

    for &v in a.iter() {
        let v2 = sum -v;
        if gcd(v, v2) == 1 {
            return false;
        }
    }

    let mut g = a[0];
    for &v in a.iter() {
        g = gcd(v, g);
    }
    // debug!(g);
    g == 1
}

fn solve(n: usize) -> Vec<usize> {
    if n == 3 {
        return vec![2, 5, 63];
    }

    let mut ans = vec![];
    let mut sum = 0;
    for i in 0..n-2 {
        let v = i * 2 + 2;
        ans.push(v);
        sum += v;
    }
    for i in 1..20 {
        if sum == 2usize.pow(i) {
            let idx = ans.len()-1;
            ans[idx] += 2;
            sum += 2;
        }
    }
    let primes = prime_factorization(sum);
    let &(p, _) = primes.iter().find(|v| v.0 != 2).unwrap();

    ans.push(p);
    ans.push(p*3);

    // if !check(&ans) {
    //     // debug!(ans);
    //     panic!();
    // }
    ans
}

