        let n = n - 5;
        for k in 0..2501 {
            let d = n - 2 * k;
            if d % 3 != 0 || d / 3 > 5000 {
                continue;
            }
            let m = d / 3;
            ret = (8..30001).step_by(2).take(3 * m).collect();
            ret.extend((15..30000).step_by(6).take(2 * k));
            break;
        }
    };
    assert_eq!(ret.len(), n);
    println!(
        "{}",
        ret.iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

