pub fn prime_factorization(mut n: usize) -> Vec<(usize, usize)> {
    let mut i = 2;
    let mut ans = vec![];
    while i * i <= n {
        let mut cnt = 0;
        while n % i == 0 {
            n /= i;
            cnt += 1;
        }
        if cnt > 0 {
            ans.push((i, cnt));
        }
        i += 1;
    }
    if n > 1 {
        ans.push((n, 1));
    }
    ans
}

pub fn gcd(a: usize, b: usize) -> usize {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn check(a: &Vec<usize>) -> bool {
    let sum: usize = a.iter().sum();

    for &v in a.iter() {
        if v > 30000 {
            return false;
        }
        let v2 = sum -v;
        if gcd(v, v2) == 1 {
            return false;
        }
    }

    let mut g = a[0];
    for &v in a.iter() {
        g = gcd(v, g);
    }
    g == 1
}

fn solve(n: usize) -> Vec<usize> {
    if n == 3 {
        return vec![2, 5, 63];
    }

    let mut ans = vec![];
    let mut sum = 0;

    let mut num2 = min(n-2, 15000);
    let mut num3 = n - num2;
    if num3%2 == 1 {
        num3 += 1;
        num2 -= 1;
    }

    for i in 0..num2 {
        let v = i * 2 + 2;
        ans.push(v);
        sum += v;
    }
    if sum%3 != 0 {
        ans[num2-1] += 6 - sum%6;
    }

    for i in 0..num3 {
        ans.push(3*(2*i + 1));
    }

    if !check(&ans) {
        panic!();
    }
    ans
}

