        0 => [2, 10, 3, 9, 4, 8, 12, 6],
        1 => [6, 2, 10, 3, 9, 4, 8, 12],
        _ => unreachable!(),
    };

    let mut c = 0;
    'lp: for i in 0.. {
        for j in 0..8 {
            write!(&mut ret, "{} ", 12 * i + aa[j]).unwrap();
            c += 1;
            if c == n {
                break 'lp;
            }
        }
    }
    ret.pop();
    ret.push('\n');
    ret
}

