use std::io;

const MAX_ELEMENT: i64 = 30000;

fn main() {
    let mut line = String::new();
    io::stdin().read_line(&mut line).unwrap();
    let inputs = line.as_str().split(' ').collect::<Vec<&str>>();
    let input0 = inputs[0].trim().parse::<usize>().unwrap();

    print!(
        "{}",
        special_set(input0)
            .into_iter()
            .map(|v| format!("{}", v))
            .collect::<Vec<String>>()
            .join(" ")
    );
}

fn special_set(n: usize) -> Vec<i64> {
    if n == 3 {
        vec![2, 5, 63]
    } else if n == 4 {
        vec![2, 5, 20, 63]
    } else {
        let mut prev_special_set = special_set(n - 1);
        prev_special_set.push(0);
        for v in 1..MAX_ELEMENT + 1 {
            if prev_special_set.iter().find(|&&x| x == v) == None {
                prev_special_set.pop();
                prev_special_set.push(v);
                if is_special_set(&prev_special_set) {
                    return prev_special_set;
                }
            }
        }
        panic!("special set of size {} not found", n);
    }
}

fn is_special_set(set: &[i64]) -> bool {
    let mut flag = true;
    for i in 0..set.len() {
        let sum = set.iter()
            .enumerate()
            .fold(0, |acc, (j, v)| if j == i { acc } else { acc + v });
        flag &= gcd(sum, set[i]) > 1;
    }
    flag
}

fn gcd(a: i64, b: i64) -> i64 {
    let (m, n) = if a >= b { (a, b) } else { (b, a) };
    if n == 0 {
        m
    } else {
        gcd(n, m % n)
    }
}

